-- ==============================================================================
-- TINPATH - MASTER SEED DATABASE SCRIPT
-- Nạp toàn bộ dữ liệu hoàn chỉnh cho hệ thống TinPath gồm 14 bảng:
-- 1. Trường học (34 THPT Quảng Ngãi)
-- 2. Chuyên đề (8 Topics chuẩn GDPT 2018)
-- 3. Đề thi (5 Đề thi thử THPT 2026 chính thức)
-- 4. Ngân hàng câu hỏi (140+ câu hỏi trắc nghiệm & đúng sai có giải thích)
-- 5. Tri thức SGK (Knowledge Chunks phục vụ AI Mentor RAG)
-- 6. Cấu hình phân quyền RLS an toàn, tránh lỗi permission
-- ==============================================================================

-- 1. CẤU HÌNH PHÂN QUYỀN ROW LEVEL SECURITY (RLS) TRÁNH LỖI INSERT/SELECT
DROP POLICY IF EXISTS "Allow public all on schools" ON public.schools;
CREATE POLICY "Allow public all on schools" ON public.schools FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on topics" ON public.topics;
CREATE POLICY "Allow public all on topics" ON public.topics FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on exams" ON public.exams;
CREATE POLICY "Allow public all on exams" ON public.exams FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on questions" ON public.questions;
CREATE POLICY "Allow public all on questions" ON public.questions FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on knowledge_chunks" ON public.knowledge_chunks;
CREATE POLICY "Allow public all on knowledge_chunks" ON public.knowledge_chunks FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on classrooms" ON public.classrooms;
CREATE POLICY "Allow public all on classrooms" ON public.classrooms FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on assignments" ON public.assignments;
CREATE POLICY "Allow public all on assignments" ON public.assignments FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on classroom_members" ON public.classroom_members;
CREATE POLICY "Allow public all on classroom_members" ON public.classroom_members FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on exam_comments" ON public.exam_comments;
CREATE POLICY "Allow public all on exam_comments" ON public.exam_comments FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on daily_challenge_attempts" ON public.daily_challenge_attempts;
CREATE POLICY "Allow public all on daily_challenge_attempts" ON public.daily_challenge_attempts FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Allow public all on xp_transactions" ON public.xp_transactions;
CREATE POLICY "Allow public all on xp_transactions" ON public.xp_transactions FOR ALL USING (true) WITH CHECK (true);

