-- Câu hỏi Phần I của thpt_thu_xa_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c1', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo (AI) gồm hai loại chính nào?', '{"A": "AI hẹp và AI siêu thông minh: Sai vì \"AI siêu thông minh\" (Superintelligent AI) là một mức độ giả thuyết vượt cả trí tuệ con người, chưa được xem là một trong hai loại chính hiện nay.", "B": "AI tổng quát và AI hẹp.", "C": "AI tổng quát và AI tự học: Sai vì \"AI tự học\" chỉ là một phương pháp học của AI, không phải là một loại AI chính.", "D": "AI tổng quát và AI siêu thông minh: Sai vì thiếu AI hẹp, trong khi AI hẹp mới là loại AI phổ biến và đang được sử dụng hiện nay."}'::jsonb, 'B', '- Trí tuệ nhân tạo (AI) thường được chia thành hai loại chính dựa trên phạm vi và khả năng của nó:
AI hẹp (Narrow AI hay Weak AI): Là loại AI được thiết kế để thực hiện một nhiệm vụ cụ thể. Nó không có khả năng tự suy nghĩ hoặc hiểu biết như con người.
AI tổng quát (General AI hay Strong AI): Là loại AI có khả năng thực hiện bất kỳ nhiệm vụ trí tuệ nào mà con người có thể làm được. Nó có thể tự suy nghĩ, học hỏi và thích nghi trong nhiều tình huống khác nhau. Hiện nay, AI tổng quát vẫn đang là mục tiêu nghiên cứu, chưa được phát triển hoàn thiện.
- Giải thích vì sao các đáp án khác sai:
A. AI hẹp và AI siêu thông minh: Sai vì "AI siêu thông minh" (Superintelligent AI) là một mức độ giả thuyết vượt cả trí tuệ con người, chưa được xem là một trong hai loại chính hiện nay.
C. AI tổng quát và AI tự học: Sai vì "AI tự học" chỉ là một phương pháp học của AI, không phải là một loại AI chính.
D. AI tổng quát và AI siêu thông minh: Sai vì thiếu AI hẹp, trong khi AI hẹp mới là loại AI phổ biến và đang được sử dụng hiện nay.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c2', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'AI tác động như thế nào đối với việc làm của con người?', '{"A": "AI thay thế hoàn toàn con người → Sai, vì AI không thể thay thế hết tất cả công việc, nhất là những công việc mang tính sáng tạo, nhân văn, giao tiếp.", "B": "AI tạo ra những việc làm mới và thay thế một số công việc hiện có.", "C": "AI chỉ tác động đến các công việc đơn giản, lặp đi lặp lại → Chưa chính xác, vì hiện nay AI còn tác động đến cả các lĩnh vực chuyên môn cao như y tế, tài chính, giáo dục, nghệ thuật…", "D": "AI không có tác động đáng kể → Sai, vì AI đang tạo ra sự thay đổi lớn trong cách con người làm việc và tổ chức công việc."}'::jsonb, 'B', 'A. AI thay thế hoàn toàn con người → Sai, vì AI không thể thay thế hết tất cả công việc, nhất là những công việc mang tính sáng tạo, nhân văn, giao tiếp.
C. AI chỉ tác động đến các công việc đơn giản, lặp đi lặp lại → Chưa chính xác, vì hiện nay AI còn tác động đến cả các lĩnh vực chuyên môn cao như y tế, tài chính, giáo dục, nghệ thuật…
D. AI không có tác động đáng kể → Sai, vì AI đang tạo ra sự thay đổi lớn trong cách con người làm việc và tổ chức công việc.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c3', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Trong những dịch vụ khách hàng sau đây, AI có thể làm được việc gì?', '{"A": "Tổ chức sự kiện khai trương cho doanh nghiệp → Sai , vì việc này đòi hỏi yếu tố con người, sự sáng tạo linh hoạt và quản lý thực tế tại hiện trường.", "B": "Thay thế hoàn toàn nhân viên dịch vụ → Sai , vì AI có thể hỗ trợ nhưng chưa thể thay thế hoàn toàn con người trong mọi tình huống dịch vụ khách hàng.", "C": "Tạo ra các sản phẩm mới → Sai , vì việc tạo ra sản phẩm mới thường dựa trên chiến lược kinh doanh, nghiên cứu thị trường và ý tưởng sáng tạo từ con người.", "D": "Quản lý dữ liệu khách hàng."}'::jsonb, 'D', 'A. Tổ chức sự kiện khai trương cho doanh nghiệp → Sai , vì việc này đòi hỏi yếu tố con người, sự sáng tạo linh hoạt và quản lý thực tế tại hiện trường.
B. Thay thế hoàn toàn nhân viên dịch vụ → Sai , vì AI có thể hỗ trợ nhưng chưa thể thay thế hoàn toàn con người trong mọi tình huống dịch vụ khách hàng.
C. Tạo ra các sản phẩm mới → Sai , vì việc tạo ra sản phẩm mới thường dựa trên chiến lược kinh doanh, nghiên cứu thị trường và ý tưởng sáng tạo từ con người.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c4', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Để kết nối không dây trong mạng cục bộ (LAN), thiết bị nào sau đây được sử dụng?', '{"A": "Hub.", "B": "Router.", "C": "WAP.", "D": "Switch."}'::jsonb, 'C', 'WAP (Wireless Access Point) là thiết bị cho phép các thiết bị kết nối không dây (như laptop, smartphone) truy cập vào mạng cục bộ (LAN).
Hub, Switch, Router là các thiết bị mạng dùng trong kết nối có dây, dù Router đôi khi có tích hợp chức năng WAP, nhưng thiết bị chuyên dùng để tạo kết nối không dây trong LAN vẫn là WAP.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c5', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao thức nào được sử dụng để truyền tin trong mạng cục bộ?', '{"A": "Ethernet", "B": "TCP", "C": "IP", "D": "HTTP"}'::jsonb, 'A', 'Ethernet là một giao thức truyền thông được sử dụng phổ biến trong mạng cục bộ (LAN - Local Area Network). Nó quy định cách các thiết bị trong mạng trao đổi dữ liệu với nhau.
TCP (Transmission Control Protocol) và IP (Internet Protocol) là các giao thức hoạt động ở tầng cao hơn, thường dùng trong mạng diện rộng (WAN) hoặc trên Internet.
HTTP (HyperText Transfer Protocol) là giao thức dùng để truyền siêu văn bản trên web, hoạt động ở tầng ứng dụng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c6', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Chọn phương án đúng khi nói về chức năng của router.', '{"A": "Là chức năng chính của Switch hoặc Hub, không phải Router.", "B": "Dẫn đường cho dữ liệu từ một mạng đến mạng khác trên Internet.", "C": "Là chức năng của Modem (thiết bị chuyển đổi tín hiệu số - analog).", "D": "Là chức năng của Hub – phát tín hiệu đến tất cả các cổng."}'::jsonb, 'B', 'Router (bộ định tuyến) có chức năng chính là định tuyến dữ liệu giữa các mạng khác nhau, ví dụ như giữa mạng LAN tại nhà bạn và mạng Internet.
Các phương án khác:
A: Là chức năng chính của Switch hoặc Hub, không phải Router.
C: Là chức năng của Modem (thiết bị chuyển đổi tín hiệu số - analog).
D: Là chức năng của Hub – phát tín hiệu đến tất cả các cổng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c7', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Trong quá trình truyền dữ liệu, giao thức TCP có vai trò như thế nào?', '{"A": "Đảm bảo dữ liệu được truyền chính xác, hiệu quả", "B": "Tăng tốc độ truyền dữ liệu không phải là chức năng chính của TCP.", "C": "TCP không nhằm giảm số lượng gói tin mà tập trung vào đảm bảo độ chính xác.", "D": "Việc “kết nối và truyền nhanh chóng” thuộc về các yếu tố kỹ thuật khác như băng thông, không phải đặc trưng chính của TCP."}'::jsonb, 'A', 'TCP (Transmission Control Protocol) là một giao thức hướng kết nối, có nhiệm vụ chính là đảm bảo dữ liệu được truyền đi một cách đầy đủ, đúng thứ tự và không bị lỗi. TCP sử dụng các cơ chế như kiểm tra lỗi, xác nhận gói tin (acknowledgement), truyền lại gói bị mất, kiểm soát luồng và kiểm soát tắc nghẽn để đảm bảo độ tin cậy của quá trình truyền dữ liệu.
Các lựa chọn còn lại:
B: Tăng tốc độ truyền dữ liệu không phải là chức năng chính của TCP.
C: TCP không nhằm giảm số lượng gói tin mà tập trung vào đảm bảo độ chính xác.
D: Việc “kết nối và truyền nhanh chóng” thuộc về các yếu tố kỹ thuật khác như băng thông, không phải đặc trưng chính của TCP.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c8', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Khi sử dụng hub để kết nối các máy tính trong mạng LAN, nếu có nhiều máy tính gửi dữ liệu cùng lúc thì điều gì sau đây sẽ xảy ra?', '{"A": "Mạng hoạt động hiệu quả hơn.", "B": "Có thể xảy ra xung đột tín hiệu.", "C": "Tốc độ truyền dữ liệu nhanh hơn.", "D": "Tín hiệu sẽ được định tuyến đến các cổng nhận."}'::jsonb, 'B', 'Hub là thiết bị hoạt động ở tầng vật lý (Layer 1) trong mô hình OSI. Khi một máy tính gửi dữ liệu qua hub, dữ liệu đó sẽ được truyền đến tất cả các cổng còn lại, không phân biệt đích đến. Nếu nhiều máy tính gửi dữ liệu cùng lúc, các tín hiệu có thể va chạm (collision) với nhau, gây ra xung đột tín hiệu, làm giảm hiệu quả mạng. Đây là đặc điểm của mạng sử dụng hub, khác với switch (chuyển mạch) – thiết bị thông minh hơn, có thể định tuyến dữ liệu đến đúng cổng nhận.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c9', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Trong một ứng dụng web, bạn muốn bảo mật thông tin người dùng khi truyền tải qua Internet. Bạn nên chọn giao thức nào?', '{"A": "HTTPS", "B": "HTTP", "C": "FTP", "D": "UDP"}'::jsonb, 'A', 'HTTPS (HyperText Transfer Protocol Secure) là phiên bản bảo mật của HTTP, sử dụng giao thức SSL/TLS để mã hóa dữ liệu trước khi truyền qua Internet. Điều này giúp bảo vệ thông tin người dùng khỏi bị đánh cắp hoặc can thiệp trong quá trình truyền tải.
HTTP không có tính năng mã hóa, dễ bị tấn công và nghe lén.
FTP là giao thức truyền tệp, không phù hợp để bảo mật thông tin trong ứng dụng web.
UDP là giao thức truyền dữ liệu không đảm bảo độ tin cậy, không được dùng để truyền dữ liệu quan trọng cần bảo mật như thông tin người dùng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c10', 'thpt_thu_xa_2026', '12D', 'Đạo đức, pháp luật thế giới ảo', 'single_choice', 'van_dung', 'ALL', 'Trong không gian mạng – môi trường giao tiếp và trao đổi thông tin rộng lớn, việc ứng xử có văn hóa là rất quan trọng. Theo bạn, hành vi nào dưới đây thể hiện cách ứng xử phù hợp trên không gian mạng?', '{"A": "Dùng lời lẽ xúc phạm khi chỉ trích bạn trên mạng xã hội.", "B": "Hạn chế việc lan truyền video ghi lại cảnh xô xát giữa bạn bè trong lớp.", "C": "Chia sẻ đoạn nhật ký cá nhân của bạn (có nội dung không hài lòng về một bạn cùng lớp) cho nhiều người khác.", "D": "Bình luận tiêu cực vào bài viết của người khác để thể hiện ý kiến cá nhân."}'::jsonb, 'B', 'Dùng lời lẽ xúc phạm khi chỉ trích bạn trên mạng xã hội. → Không hợp lí. Đây là hành vi thiếu văn hóa, dễ gây tổn thương tinh thần cho người khác, vi phạm nguyên tắc ứng xử văn minh và có thể dẫn đến các hậu quả như mâu thuẫn, bắt nạt trên mạng hoặc vi phạm pháp luật về xúc phạm danh dự, nhân phẩm người khác.
Chia sẻ đoạn nhật ký cá nhân của bạn (có nội dung không hài lòng về một bạn cùng lớp) cho nhiều người khác. → Không hợp lí. Hành động này dễ dẫn đến hiểu lầm, chia rẽ mối quan hệ giữa các bạn trong lớp, và vi phạm quyền riêng tư. Thay vì chia sẻ công khai, cần trao đổi trực tiếp với người có liên quan để giải quyết mâu thuẫn.
Bình luận tiêu cực vào bài viết của người khác để thể hiện ý kiến cá nhân. →  Không hợp lí. Việc thể hiện ý kiến cá nhân là quyền của mỗi người, nhưng cần lựa chọn cách nói lịch sự, mang tính xây dựng. Bình luận tiêu cực có thể gây tổn thương, tranh cãi hoặc làm ảnh hưởng xấu đến tinh thần người khác.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c11', 'thpt_thu_xa_2026', '12D', 'Đạo đức, pháp luật thế giới ảo', 'single_choice', 'van_dung', 'ALL', 'Confession là một trào lưu được nhiều người sử dụng để chia sẻ tâm tư, cảm xúc hay câu chuyện cá nhân. Tại các trường học, confession trở thành một diễn đàn sôi động. Trong các ý kiến dưới đây, ý kiến nào KHÔNG ĐÚNG về confession?', '{"A": "\"Sau khi người viết gửi tâm sự, admin sẽ duyệt bài phù hợp với thuần phong mỹ tục và chính sách của trang. Những bài được duyệt sẽ được đăng để mọi người chia sẻ, góp ý.\" → Đúng. Đây là quy trình phổ biến của các trang confession hiện nay. Admin sẽ kiểm duyệt nội dung để đảm bảo không vi phạm thuần phong mỹ tục, quy định pháp luật hoặc gây ảnh hưởng tiêu cực trước khi đăng tải.", "B": "\"Nhiều confession bị lợi dụng để nói xấu, bóc phốt cá nhân, gây ảnh hưởng tâm lý người khác.\" → Đúng. Dù confession có mục đích tích cực, nhưng thực tế đã có trường hợp bị lợi dụng để nói xấu, công kích cá nhân, gây ra hậu quả về tâm lý hoặc mâu thuẫn giữa các cá nhân, tập thể.", "C": "\"Confession không có vai trò chia sẻ, cảm thông hay thấu hiểu những khó khăn của người khác.\" → Sai, vì confession thực chất là nơi để chia sẻ tâm tư, cảm xúc, câu chuyện – kể cả những khó khăn và khúc mắc trong cuộc sống, học tập, tình cảm… Thông qua đó, người viết mong nhận được sự lắng nghe, cảm thông và thấu hiểu từ cộng đồng. Vậy nên, nói confession \"không có vai trò chia sẻ, cảm thông\" là không đúng với bản chất của trào lưu này.", "D": "\"Khi tham gia viết bài trong confession, các thành viên nên chú ý ngôn từ để tránh gây hiểu nhầm hoặc mang tính khiêu khích.\" → Đúng. Đây là một lời khuyên đúng đắn. Dù viết ẩn danh, người dùng confession vẫn cần tôn trọng người đọc, thể hiện trách nhiệm qua cách sử dụng từ ngữ, tránh gây tổn thương, mâu thuẫn hoặc hiểu lầm."}'::jsonb, 'C', 'C. "Confession không có vai trò chia sẻ, cảm thông hay thấu hiểu những khó khăn của người khác." → Sai, vì confession thực chất là nơi để chia sẻ tâm tư, cảm xúc, câu chuyện – kể cả những khó khăn và khúc mắc trong cuộc sống, học tập, tình cảm… Thông qua đó, người viết mong nhận được sự lắng nghe, cảm thông và thấu hiểu từ cộng đồng. Vậy nên, nói confession "không có vai trò chia sẻ, cảm thông" là không đúng với bản chất của trào lưu này.
A. "Sau khi người viết gửi tâm sự, admin sẽ duyệt bài phù hợp với thuần phong mỹ tục và chính sách của trang. Những bài được duyệt sẽ được đăng để mọi người chia sẻ, góp ý." → Đúng. Đây là quy trình phổ biến của các trang confession hiện nay. Admin sẽ kiểm duyệt nội dung để đảm bảo không vi phạm thuần phong mỹ tục, quy định pháp luật hoặc gây ảnh hưởng tiêu cực trước khi đăng tải.
B. "Nhiều confession bị lợi dụng để nói xấu, bóc phốt cá nhân, gây ảnh hưởng tâm lý người khác." → Đúng. Dù confession có mục đích tích cực, nhưng thực tế đã có trường hợp bị lợi dụng để nói xấu, công kích cá nhân, gây ra hậu quả về tâm lý hoặc mâu thuẫn giữa các cá nhân, tập thể.
D. "Khi tham gia viết bài trong confession, các thành viên nên chú ý ngôn từ để tránh gây hiểu nhầm hoặc mang tính khiêu khích." → Đúng. Đây là một lời khuyên đúng đắn. Dù viết ẩn danh, người dùng confession vẫn cần tôn trọng người đọc, thể hiện trách nhiệm qua cách sử dụng từ ngữ, tránh gây tổn thương, mâu thuẫn hoặc hiểu lầm.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c12', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Điều nào sau đây là một biện pháp bảo mật cơ bản để bảo vệ dữ liệu cá nhân trên Internet?', '{"A": "Sử dụng mật khẩu kết hợp các kí tự: chữ cái viết hoa, viết thường, số và ký tự đặc biệt.", "B": "Sử dụng mật khẩu là số CCC", "C": "Ghi mật khẩu vào ghi nhớ trong điện thoại để không quên: Nếu điện thoại bị mất hoặc bị hack, mật khẩu sẽ bị lộ.", "D": "Sử dụng cùng mật khẩu cho tất cả tài khoản: Nếu một tài khoản bị lộ, tất cả các tài khoản khác cũng bị đe dọa."}'::jsonb, 'A', '- Đây là một biện pháp bảo mật cơ bản và hiệu quả để bảo vệ dữ liệu cá nhân trên Internet. Mật khẩu mạnh sẽ giúp giảm nguy cơ bị hacker tấn công hoặc dò mật khẩu.
- Giải thích các đáp án sai:
B. Sử dụng mật khẩu là số CCCD: Mật khẩu dễ đoán và có thể bị lộ thông tin, không an toàn.
C. Ghi mật khẩu vào ghi nhớ trong điện thoại để không quên: Nếu điện thoại bị mất hoặc bị hack, mật khẩu sẽ bị lộ.
D. Sử dụng cùng mật khẩu cho tất cả tài khoản: Nếu một tài khoản bị lộ, tất cả các tài khoản khác cũng bị đe dọa.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c13', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Hình thức nào dưới đây KHÔNG phải là một dạng lừa đảo phổ biến trên mạng?', '{"A": "Gửi tin nhắn chúc mừng tới người thân, bạn bè quen biết", "B": "Lừa đảo nhận quà từ người nước ngoài thường nhằm đánh cắp tiền bằng cách yêu cầu đóng phí nhận quà.", "C": "Lừa trúng thưởng là chiêu trò phổ biến để đánh cắp tiền hoặc thông tin cá nhân.", "D": "Giả mạo cán bộ nhà nước để lừa lấy thông tin cá nhân là một thủ đoạn tinh vi đang được cảnh báo nhiều."}'::jsonb, 'A', 'A là một hành động bình thường trong giao tiếp, không mang tính chất lừa đảo nếu nội dung chỉ đơn thuần là chúc mừng.
Các lựa chọn B, C, D đều là những hình thức lừa đảo phổ biến trên mạng hiện nay:
B: Lừa đảo nhận quà từ người nước ngoài thường nhằm đánh cắp tiền bằng cách yêu cầu đóng phí nhận quà.
C: Lừa trúng thưởng là chiêu trò phổ biến để đánh cắp tiền hoặc thông tin cá nhân.
D: Giả mạo cán bộ nhà nước để lừa lấy thông tin cá nhân là một thủ đoạn tinh vi đang được cảnh báo nhiều.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c14', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Tại sao bạn không nên chia sẻ mật khẩu với người khác?', '{"A": "Vì người khác có thể giúp bạn quản lý tài khoản tốt hơn: Việc chia sẻ mật khẩu không đảm bảo an toàn và không nên dựa vào người khác để quản lý tài khoản cá nhân.", "B": "Mật khẩu là thông tin cá nhân cần được bảo vệ để tránh bị xâm phạm tài khoản.", "C": "Chia sẻ mật khẩu giúp tăng tính bảo mật: Hoàn toàn sai — chia sẻ mật khẩu làm giảm tính bảo mật, không phải tăng.", "D": "Người khác có thể xử lý tốt các vấn đề tài khoản khi cần: Nếu cần trợ giúp, bạn nên sử dụng tính năng hỗ trợ từ hệ thống, không nên chia sẻ mật khẩu, vì sẽ tiềm ẩn rủi ro mất kiểm soát."}'::jsonb, 'B', 'Mật khẩu là lớp bảo vệ đầu tiên giúp bạn giữ an toàn cho thông tin cá nhân, dữ liệu và quyền truy cập vào tài khoản của mình.
Nếu bạn chia sẻ mật khẩu, người khác có thể truy cập, thay đổi thông tin, đánh cắp dữ liệu, hoặc thực hiện hành vi xấu dưới danh nghĩa của bạn mà bạn không kiểm soát được.
Việc giữ mật khẩu riêng tư giúp ngăn chặn nguy cơ bị xâm nhập, lừa đảo hoặc mất quyền kiểm soát tài khoản.
Vì sao các đáp án còn lại sai:
A. Vì người khác có thể giúp bạn quản lý tài khoản tốt hơn: Việc chia sẻ mật khẩu không đảm bảo an toàn và không nên dựa vào người khác để quản lý tài khoản cá nhân.
C. Chia sẻ mật khẩu giúp tăng tính bảo mật: Hoàn toàn sai — chia sẻ mật khẩu làm giảm tính bảo mật, không phải tăng.
D. Người khác có thể xử lý tốt các vấn đề tài khoản khi cần: Nếu cần trợ giúp, bạn nên sử dụng tính năng hỗ trợ từ hệ thống, không nên chia sẻ mật khẩu, vì sẽ tiềm ẩn rủi ro mất kiểm soát.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c15', 'thpt_thu_xa_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Công việc chính của nghề sửa chữa và bảo trì máy tính liên quan đến vấn đề nào sau đây?', '{"A": "Duy trì sự ổn định của phần cứng và phần mềm của máy tính.", "B": "Xây dựng hệ thống mới là công việc của kỹ sư hệ thống.", "C": "Sản xuất linh kiện thuộc lĩnh vực sản xuất phần cứng.", "D": "Thiết kế giao diện người dùng thuộc lĩnh vực thiết kế phần mềm/UI-UX."}'::jsonb, 'A', 'Công việc chính của nghề sửa chữa và bảo trì máy tính là kiểm tra, khắc phục lỗi phần cứng (như ổ cứng, RAM, nguồn điện,...) và phần mềm (hệ điều hành, virus, phần mềm ứng dụng...) để đảm bảo máy tính hoạt động ổn định và hiệu quả.
Các đáp án còn lại không phù hợp với mục tiêu chính của nghề này:
B: Xây dựng hệ thống mới là công việc của kỹ sư hệ thống.
C: Sản xuất linh kiện thuộc lĩnh vực sản xuất phần cứng.
D: Thiết kế giao diện người dùng thuộc lĩnh vực thiết kế phần mềm/UI-UX.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c16', 'thpt_thu_xa_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Người làm nghề quản trị mạng có nhiệm vụ chính là gì?', '{"A": "Lập kế hoạch truyền thông cho tổ chức: Việc này thường thuộc về bộ phận marketing hoặc truyền thông, không liên quan trực tiếp đến quản trị mạng.", "B": "Quản lí và duy trì hệ thống máy tính của tổ chức.", "C": "Phát triển các ứng dụng di động: Đây là công việc của lập trình viên ứng dụng di động, không phải của người quản trị mạng.", "D": "Thực hiện khảo sát về nhu cầu của khách hàng: Nhiệm vụ này thuộc về bộ phận nghiên cứu thị trường hoặc chăm sóc khách hàng, không liên quan đến công việc quản trị mạng."}'::jsonb, 'B', 'Người làm quản trị mạng là người chịu trách nhiệm thiết kế, cài đặt, vận hành, bảo trì và bảo mật hệ thống mạng máy tính trong một tổ chức. Mục tiêu là giúp hệ thống hoạt động ổn định, an toàn và hiệu quả. Quản lý và duy trì hệ thống máy tính là nhiệm vụ trung tâm của quản trị mạng — bao gồm cả mạng nội bộ (LAN), mạng diện rộng (WAN), máy chủ, thiết bị mạng, an ninh mạng...
Giải thích vì sao các đáp án khác sai:
A. Lập kế hoạch truyền thông cho tổ chức: Việc này thường thuộc về bộ phận marketing hoặc truyền thông, không liên quan trực tiếp đến quản trị mạng.
C. Phát triển các ứng dụng di động: Đây là công việc của lập trình viên ứng dụng di động, không phải của người quản trị mạng.
D. Thực hiện khảo sát về nhu cầu của khách hàng: Nhiệm vụ này thuộc về bộ phận nghiên cứu thị trường hoặc chăm sóc khách hàng, không liên quan đến công việc quản trị mạng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c17', 'thpt_thu_xa_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây là lí do đúng nhất lí giải sự gia tăng nhu cầu về nhân lực trong nhóm nghề quản trị trong ngành Công nghệ thông tin?', '{"A": "", "B": "Sự gia tăng số lượng thiết bị kết nối mạng và các nguy cơ tấn công mạng.", "C": "Sự gia tăng các cửa hàng bán lẻ trực tuyến.", "D": "Sự phát triển của ngành dịch vụ du lịch trực tuyến. Các phương án B, C, D tuy liên quan đến ngành CNTT, nhưng không trực tiếp gắn với nhóm nghề “quản trị” như phương án"}'::jsonb, 'A', 'Sự phổ biến mạnh mẽ của mạng xã hội, ứng dụng di động, và các nền tảng số kéo theo nhu cầu lớn về quản trị hệ thống, quản lý dữ liệu người dùng, vận hành hạ tầng công nghệ, cũng như phân tích hành vi người dùng. Điều này làm tăng nhu cầu nhân lực trong nhóm nghề quản trị trong ngành Công nghệ thông tin, đặc biệt ở các vị trí như quản trị hệ thống, quản trị mạng, quản trị cơ sở dữ liệu, quản trị sản phẩm công nghệ số, v.v.
Các phương án B, C, D tuy liên quan đến ngành CNTT, nhưng không trực tiếp gắn với nhóm nghề “quản trị” như phương án A.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c18', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án  nào dưới đây khi nói câu lệnh lặp While trong ngôn ngữ lập trình Python:', '{"A": "Lệnh lặp với số lần không biết trước.", "B": "Lệnh lặp vô hạn.", "C": "Lệnh lặp với số lần biết trước.", "D": "Lệnh rẽ nhánh."}'::jsonb, 'A', 'SGK trang 108 đã chỉ rõ') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c19', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Đoạn chương trình sau cho kết quả là?', '{"A": "0 1 2.", "B": "1 2 3.", "C": "0 1 2 3.", "D": "Lỗi chương trình."}'::jsonb, 'A', 'đã kiểm chứng trên PM Python') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c20', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'cho đoạn chương trình sau:', '{"A": "Vòng lặp này sẽ in ra các số ừ 0 đến 5.", "B": "Vòng lặp này sẽ in ra các số từ 0 đến 4.", "C": "Vòng lặp này sẽ in ra các số từ 0 đến 6.", "D": "Vòng lặp này sẽ in ra các số từ 0 đến 7."}'::jsonb, 'A', 'đã kiểm chứng trên PM Python.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c21', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', '. Sau khi thực hiện các lệnh dưới đây, skq sẽ có giá trị bao nhiêu?', '{"A": "Phương án A", "B": "“172”.", "C": "“123”.", "D": "kết quả thu được “173”\nGiải thích: skq sẽ bao gồm các chữ số lẻ trong xâu s. kết quả thu được về “173” (đã kiểm chứng trên Python)"}'::jsonb, 'A', 'skq sẽ bao gồm các chữ số lẻ trong xâu s. kết quả thu được về “173” (đã kiểm chứng trên Python)') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c22', 'thpt_thu_xa_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Cho đoạn chương trình sau:', '{"A": "Chuyển toàn bộ xâu s thành chữ in hoa và đếm số lượng ký tự trong xâu s.", "B": "Chuyển toàn bộ xâu s thành chữ thường và tính cộng tổng số lượng ký tự trong xâu s.", "C": "Chuyển toàn bộ xâu s thành chữ in hoa và nhân số lượng ký tự trong xâu s.", "D": "Chuyển toàn bộ xâu s thành chữ thường và tính tích số lượng ký tự trong xâu s."}'::jsonb, 'A', 'đã kiểm chứng trên Python.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c23', 'thpt_thu_xa_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thuộc tính nào sau đây có độ ưu tiên cao nhất trong CSS?', '{"A": "Thuộc tính có gắn id", "B": "Thuộc tính có gắn dấu sao", "C": "Thuộc tính có trọng số cao nhất", "D": "Thuộc tính với !important"}'::jsonb, 'D', 'Trong CSS, mức độ ưu tiên của các thuộc tính được xác định theo quy tắc độ ưu tiên (specificity) và độ quan trọng (!important). Thứ tự ưu tiên từ cao đến thấp là:
!important → cao nhất, ghi đè mọi quy tắc khác, kể cả inline style hay selector có độ ưu tiên cao.
Inline style (viết trực tiếp trong thẻ HTML: style="...")
Selector theo ID (#id)
Selector theo class, attribute, pseudo-class (.class, [type="text"], :hover, v.v.)
Selector theo thẻ (element) hoặc dấu sao *
Mặc định từ trình duyệt') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thuxa_p1_c24', 'thpt_thu_xa_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Để đặt nền màu xanh cho phần tử h1, cách khai báo thuộc tính CSS nào sau đây KHÔNG chính xác?', '{"A": "background-color: blue;  đúng", "B": "background-color: rgb(0,0,255); đúng (RGB xanh dương)", "C": "background-color: #0000FF; đúng (Hex màu xanh dương)", "D": "h1{background-color : hsl(0,100%,100%);}"}'::jsonb, 'A', 'hsl(0,100%,100%) là mã màu trắng, không phải màu xanh.
HSL nghĩa là: Hue (tông màu), Saturation (độ bão hòa), Lightness (độ sáng).
hsl(0, 100%, 100%) nghĩa là màu đỏ với độ sáng 100%, tức là trắng.
Các đáp án còn lại đều thể hiện đúng màu xanh:
A. background-color: blue;  đúng
B. background-color: rgb(0,0,255); đúng (RGB xanh dương)
C. background-color: #0000FF; đúng (Hex màu xanh dương)') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của thpt_thu_xa_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c1', 'thpt_thu_xa_2026', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', '(12B, Chung, D2, NLa, AC7). Một người muốn mở rộng mạng gia đình gồm 8 thiết bị (máy tính, smart TV, camera giám sát...) nhưng không biết nên chọn hub hay switch. Một người tư vấn như sau:', '[{"id": "a", "text": "Hub phù hợp cho việc kết nối mạng gia đình với ít thiết bị.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Switch là thiết bị dùng để kết nối nhiều thiết bị trong mạng diện rộng.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Switch giảm thiểu nguy cơ xung đột tín hiệu so với hub.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng theo đáp án THPT Thu Xà."}, {"id": "d", "text": "Hub có thể thay thế hoàn toàn switch trong mọi tình huống.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c2', 'thpt_thu_xa_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', '(12F, Chung, D2, NLc, CC3). Nhà trường muốn đăng tải thông tin về các câu lạc bộ ngoại khóa lên website để học sinh tiện tham khảo. Câu lạc bộ Truyền thông được giao', '[{"id": "a", "text": "Nên sử dụng thẻ <ul> để liệt kê tên các câu lạc bộ.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Để chèn hình ảnh minh họa cho phần này, nên dùng thẻ <img>.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Để làm bo tròn hình ảnh mà không cần chỉnh sửa bằng phần mềm, có thể dùng lệnh CSS img { image-border: ellipse; }", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng theo đáp án THPT Thu Xà."}, {"id": "d", "text": "Để hiển thị hình ảnh và danh sách câu lạc bộ trên cùng một hàng, nên đặt chúng vào cùng một phần tử và gán thuộc tính CSS display: flex", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c3', 'thpt_thu_xa_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', '(12BCS, R-CS, D2, Nla, AS3). Căn cứ vào chuẩn Ethernet, phương án nào thích hợp khi liên kết hai khu vực trong các phương án sau?', '[{"id": "a", "text": "Dùng cáp đồng trục.", "isCorrect": false, "explanation": "Mệnh đề (a) là Sai theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Dùng cáp UTP kết nối trực tiếp giữa hai thiết bị.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Dùng Repeater với cáp UTP.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng theo đáp án THPT Thu Xà."}, {"id": "d", "text": "Dùng cáp quang.", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c4', 'thpt_thu_xa_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', '(11FCS, R-CS, D2, Nlc, CS3). An đang tìm hiểu về cách lưu trữ dữ liệu điểm số của các bạn trong lớp. An cho rằng nên sử dụng một biến duy nhất để lưu trữ điểm của tất cả các bạn.', '[{"id": "a", "text": "Mảng một chiều là một cấu trúc dữ liệu dùng để lưu trữ một dãy các phần tử có cùng kiểu dữ liệu.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Nên sử dụng một biến duy nhất để lưu trữ điểm của tất cả các bạn.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Sử dụng mảng một chiều giúp An có thể dễ dàng truy cập, sắp xếp và tính toán điểm số của các bạn.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng theo đáp án THPT Thu Xà."}, {"id": "d", "text": "An có thể sử dụng danh sách", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c5', 'thpt_thu_xa_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', '(12EICT, R-ICT, D2, Nla, AI1). Kết nối máy tính với điện thoại qua Bluetooth để truyền tệp.', '[{"id": "a", "text": "Máy tính xách tay thường có khả năng kết nối bluetooth, còn máy bàn thường không có khả năng này.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Bluetooth là một công nghệ kết nối không dây có thể thay thế cho Internet.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Khi tai nghe Bluetooth đưa lại gần điện thoại thông minh, 2 thiết bị sẽ tự động ghép đôi.", "isCorrect": false, "explanation": "Mệnh đề (c) là Sai theo đáp án THPT Thu Xà."}, {"id": "d", "text": "Sau khi ghép đôi điện thoại với máy tính qua Bluetooth thành công, muốn gửi một tệp hình ảnh từ điện thoại sang máy tính, em cần thao tác: Chọn ảnh → Nhấn Chia sẻ → Chọn Bluetooth → Chọn tên thiết bị máy tính đã ghép đôi.", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thuxa_p2_c6', 'thpt_thu_xa_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', '(11EICT, R-ICT, D2, Nlc, CI2). Để kết nối với MySQL, cần phải nhập đúng tên người dùng và mật khẩu.', '[{"id": "a", "text": "Mật khẩu của người dùng root được tạo trong quá trình cài đặt MySQL.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng theo đáp án THPT Thu Xà."}, {"id": "b", "text": "Có thể kết nối với MySQL mà không cần mật khẩu.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai theo đáp án THPT Thu Xà."}, {"id": "c", "text": "Việc nhập đúng tên người dùng và mật khẩu giúp đảm bảo an toàn cho hệ thống CSDL.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng theo đáp án THPT Thu Xà."}, {"id": "d", "text": "Nếu quên mật khẩu, người dùng có thể sử dụng các công cụ khôi phục mật khẩu hoặc cài đặt lại MySQL.", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng theo đáp án THPT Thu Xà."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

