INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c1', 'thpt_binh_son_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong CSS, thuộc tính nào sau đây được sử dụng để căn chỉnh nội dung của một phần tử theo chiều ngang?', '{"A": "align-text.", "B": "center.", "C": "horizontal-align.", "D": "text-align."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c2', 'thpt_binh_son_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Điều nào sau đây là nguyên nhân chính khiến nhu cầu bảo trì và sửa chữa máy tính ngày càng tăng?', '{"A": "Phần mềm cũ không còn tương thích với các hệ điều hành mới.", "B": "Chi phí sở hữu máy tính cá nhân ngày càng đắt đỏ.", "C": "Ngày càng ít người sử dụng máy tính so với trước đây.", "D": "Máy tính được sử dụng rộng rãi trong nhiều lĩnh vực, bao gồm giáo dục và doanh nghiệp."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c3', 'thpt_binh_son_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Điều gì xảy ra nếu KHÔNG khai báo thuộc tính width và height trong thẻ <img>?', '{"A": "Hình ảnh sẽ không hiển thị.", "B": "Kích thước ảnh sẽ được hiển thị mặc định là 100x100 pixel.", "C": "Trình duyệt sẽ yêu cầu nhập kích thước ảnh thủ công.", "D": "Hình ảnh sẽ hiển thị theo kích thước gốc."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c4', 'thpt_binh_son_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phát biểu nào sau đây nêu ĐÚNG khái niệm Trí tuệ nhân tạo (AI)?', '{"A": "Khả năng của máy tính có thể làm những công việc mang tính trí tuệ con người.", "B": "Tích hợp công nghệ hiện đại vào máy tính, giúp máy tính hiểu được con người.", "C": "Trí tuệ của máy tính có thể làm những công việc tương đương trí tuệ con người.", "D": "Hoạt động máy tính giao tiếp được với con người bằng ngôn ngữ tự nhiên."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c5', 'thpt_binh_son_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào cho bên dưới, đưa ra nhận xét ĐÚNG về chương trình Python sau đây:', '{"A": "Chương trình giúp tìm ra giá trị nhỏ nhất trong hai số a,b.", "B": "Chương trình không cho kết quả giá trị cần tìm trong hai số a,b.", "C": "So sánh hai số a và b để tìm ra giá trị lớn hơn và gán cho m.", "D": "So sánh hai số a và b và sắp xếp lại thứ tự của giữa hai số a,b."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c6', 'thpt_binh_son_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Đoạn mã nào sau đây tạo một hộp kiểm (checkbox) trong biểu mẫu HTML?', '{"A": "<checkbox name=\"option\">...</checkbox>.", "B": "<input type=\"boxcheck\" name=\"option\">.", "C": "<check type=\"box\" name=\"option\">.", "D": "<input type=\"checkbox\" name=\"option\">."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c7', 'thpt_binh_son_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trong một phòng máy có 25 máy vi tính, muốn kết nối các máy tính đó thành mạng LAN, ta dùng thiết bị nào sau đây?', '{"A": "Modem.", "B": "Access Point.", "C": "Switch.", "D": "Router."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c8', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Chọn phát biểu ĐÚNG trong các phát biểu sau?', '{"A": "Các máy tính kết nối với nhau qua Switch để được một mạng LAN.", "B": "Các máy tính trong mạng LAN không thế kết nối internet.", "C": "Các máy tính trong cùng một phòng thì chỉ có thể kết nối mạng LAN.", "D": "Kết nối mạng internet phải dùng cáp quang."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c9', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Khi sử dụng tệp CSS ngoài (external CSS), kiểu dáng của trang web có ảnh hưởng như thế nào nếu tệp CSS được sửa đổi?', '{"A": "Các thay đổi trong tệp CSS sẽ chỉ áp dụng cho trang HTML hiện tại.", "B": "Kiểu dáng của trang web sẽ thay đổi trên tất cả các trang sử dụng tệp CSS đó.", "C": "Tệp HTML sẽ tự động liên kết với tệp CSS mới khi sửa đổi.", "D": "Kiểu dáng của trang web sẽ không thay đổi cho đến khi người dùng làm mới trang."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c10', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Bộ chọn CSS h1.title sẽ áp dụng cho các phần tử nào sau đây trên trang web?', '{"A": "Các thẻ <h1> có thuộc tính class là \"title\".", "B": "Tất cả các thẻ <h1> trong trang.", "C": "Các thẻ <h1> có thuộc tính id là \"title\".", "D": "Tất cả các thẻ có tên là title."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c11', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Cho đoạn mã HTML sau:', '{"A": "3 hàng, 3 cột.", "B": "2 hàng, 2 cột.", "C": "3 hàng, 2 cột.", "D": "2 hàng, 3 cột."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c12', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Trong CSS, để chọn phần tử với id là myId và lớp là myClass, cần sử dụng khai báo nào sau đây?', '{"A": "#myId.myClass.", "B": "myId  #myClass", "C": "myId.myClass.", "D": "#myId  #myClass."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c13', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Ứng xử nhân văn trên không gian mạng có thể góp phần tạo ra điều gì?', '{"A": "Sự gia tăng của hành vi bắt nạt trực tuyến.", "B": "Một xã hội mạng tích cực.", "C": "Tạo nhiều việc làm hữu ích.", "D": "Một môi trường mạng thông tin khổng lồ."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c14', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Đoạn mã HTML nào sau đây tạo một hình ảnh liên kết đến địa chỉ trang web https://example.com?', '{"A": "<a href=\"https://example.com\"><img src=\"image.jpg\" alt=\"Example\"></a>", "B": "<link src=\"image.jpg\" alt=\"Example\" href=\"https://example.com\">", "C": "<img href=\"https://example.com\" src=\"image.jpg\" alt=\"Example\">", "D": "<a url=\"https://example.com\" image=\"image.jpg\">"}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c15', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Phát biểu nào sau đây ĐÚNG khi nói về giao thức TCP/IP?', '{"A": "Một hệ điều hành.", "B": "Một loại phần cứng mạng.", "C": "Một giao thức truyền thông được sử dụng rộng rãi trên Internet.", "D": "Một loại virus máy tính."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c16', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Công việc nào sau đây KHÔNG phải là công việc hằng ngày của một chuyên viên an ninh mạng?', '{"A": "Kiểm tra các thành phần phần cứng của hệ thống máy tính.", "B": "Kiểm tra và đánh giá độ an toàn của hệ thống.", "C": "Cập nhật và vá lỗi bảo mật.", "D": "Giám sát hệ thống mạng."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c17', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Rủi ro lớn nhất khi sử dụng AI trong tự động hóa sản xuất là gì? Hãy chọn phương án ĐÚNG.', '{"A": "Sản phẩm sản xuất ra có chất lượng kém.", "B": "Hệ thống sản xuất dễ bị tấn công mạng.", "C": "Chi phí đầu tư ban đầu quá cao.", "D": "Mất việc làm của con người."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c18', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Lĩnh vực nghiên cứu nào của AI có khả năng phân tích và nhận dạng các hình ảnh từ thế giới bên ngoài?', '{"A": "AI tạo sinh.", "B": "Xử lí ngôn ngữ tự nhiên.", "C": "Thị giác máy tính.", "D": "Học máy."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c19', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Khi tham gia giao tiếp trên không gian mạng, hành động nào sau đây thể hiện ứng xử nhân văn?', '{"A": "Tham gia vào việc quấy rối, bắt nạt trên mạng.", "B": "Mạo danh người khác để gây cười.", "C": "Phát tán các tin đồn không có căn cứ.", "D": "Phê phán, phản đối các hành động bắt nạt, quấy rối."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c20', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Phần nội dung nào trong cấu trúc HTML được hiển thị trực tiếp trên màn hình trình duyệt web?', '{"A": "Phần tử meta trong cặp thẻ <head>.", "B": "Nội dung trong cặp thẻ <body>.", "C": "Chỉ dẫn phiên bản HTML.", "D": "Tiêu đề trong cặp thẻ <title>."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c21', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Thiết bị nào sau đây thường được sử dụng để mở rộng vùng phủ sóng Wi-Fi?', '{"A": "Repeater.", "B": "Modem.", "C": "Switch.", "D": "Firewall."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c22', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Hành vi nào dưới đây là vi phạm quyền riêng tư trên không gian mạng?', '{"A": "Chia sẻ thông tin cá nhân của người khác mà không có sự đồng ý.", "B": "Bình luận trái chiều về một ý kiến công khai.", "C": "Tạo tài khoản ẩn danh để bày tỏ quan điểm.", "D": "Gửi email quảng cáo đến danh sách người nhận."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c23', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Sự phát triển của AI KHÔNG gây ra thách thức nào sau đây?', '{"A": "Phát sinh các vấn đề đạo đức trong việc sử dụng dữ liệu AI.", "B": "Cải thiện hiệu suất làm việc của con người.", "C": "Tăng chi phí bảo trì hệ thống mạng do AI phức tạp hơn.", "D": "Gia tăng rủi ro thất nghiệp ở một số ngành nghề."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('bso_p1_c24', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Chọn một trong hai ngôn ngữ C++ hoặc python để xem xét đoạn chương trình sau:', '{"A": "50.", "B": "60.", "C": "28.", "D": "70."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng ma trận đáp án chính thức THPT Bình Sơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của thpt_binh_son_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c1', 'thpt_binh_son_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Câu 1: Một trường đại học thiết kế cơ sở dữ liệu quản lý thông tin sinh viên, môn học, và đăng ký môn học với 3 bảng có cấu trúc như sau:', '[{"id": "a", "text": "Nếu cần liên kết thông tin sinh viên với điểm của từng môn học họ đăng ký, cần sử dụng INNER JOIN giữa bảng SINHVIEN và bảng DANGKY dựa trên MaMH.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Trong bảng SINHVIEN, cột HoTen lưu thông tin họ tên của sinh viên.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Thuộc tính MaSV là khoá chính của bảng DANGKY.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Nếu muốn liệt kê danh sách các môn học có số tín chỉ lớn hơn 3, câu lệnh SQL sau là chính xác: SELECT * FROM MONHOC WHERE SoTinChi > 3;", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c2', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Câu 2: Một công ty có 4 phòng ban cần thiết lập mạng LAN để liên kết các phòng ban với nhau. Công ty đã lắp đặt một Modem do nhà cung cấp dịch vụ Internet (ISP) cung cấp. Modem này tích hợp cả chức năng của Router và Access Point.', '[{"id": "a", "text": "Để kết nối các thiết bị mạng trong mỗi phòng ban, nên sử dụng thiết bị Hub thay vì Switch.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Chức năng Access Point trong Modem giúp kết nối không dây giữa các máy tính trong mạng LAN.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Nếu Modem không tích hợp chức năng của Access Point, cần bổ sung thiết bị riêng, và thứ tự kết nối thiết bị như sau: Máy tính → Access Point → Router → Modem.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Một mạng LAN có thể hoạt động mà không cần thiết bị Router, miễn là tất cả máy tính đều kết nối qua Switch.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c3', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 3: Một sinh viên xây dựng một trang web cá nhân để giới thiệu về bản thân và các dự án đã thực hiện. Trang web bao gồm các phần chính: Giới thiệu, Dự án và Liên hệ. Một số nhận xét về việc xây dựng trang web này:', '[{"id": "a", "text": "Có thể sử dụng dịch vụ tạo website trực tuyến miễn phí như Google Sites hoặc WordPress để tạo trang web.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Khi thiết kế trang web, để hiển thị hình ảnh của các dự án, nên sử dụng thẻ <background- color> trong mã HTML.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Phần Liên hệ có thể sử dụng biểu mẫu (form) HTML để cho phép khách truy cập gửi tin nhắn hoặc thông tin liên lạc.", "isCorrect": true, "explanation": "Ý (c) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Để tăng tốc độ tải trang, nên tải các hình ảnh chất lượng cao và không cần tối ưu hóa.", "isCorrect": false, "explanation": "Ý (d) là Sai theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c4', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 4: Chọn một trong hai ngôn ngữ C++ hoặc Python để xem xét đoạn chương trình sau:', '[{"id": "a", "text": ":", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Dãy A được sắp xếp theo thứ tự giảm dần.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Độ phức tạp của thuật toán trong hàm trên là O(n).", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Với dãy đầu vào A = [64, 25, 12, 22, 11} kết quả sau khi thực hiện hàm trên là A = [11, 12, 22, 25, 64}.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c5', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 5: Nhóm học sinh chủ nhiệm Câu lạc bộ (CLB) Tin học cần thiết kế website giới thiệu về CLB gồm ba trang: Giới thiệu, Hoạt động nổi bật, Thông báo sự kiện. Trong lúc thảo luận, các học sinh đưa ra một số nhận định sau:', '[{"id": "a", "text": "Có thể tạo ba trang này từ các mẫu (theme) có sẵn của phần mềm tạo trang web.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Trang Thông báo sự kiện chỉ hiển thị văn bản, không thể chèn hình ảnh hoặc video.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Trang Hoạt động nổi bật có thể hiển thị ảnh theo dạng trình chiếu (Slideshow) để người xem dễ theo dõi.", "isCorrect": true, "explanation": "Ý (c) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Để thu thập thông tin đăng ký tham gia sự kiện của các bạn học sinh trong trường, chỉ có thể sử dụng biểu mẫu (Forms) trên trang Thông báo sự kiện.", "isCorrect": false, "explanation": "Ý (d) là Sai theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('bso_p2_c6', 'thpt_binh_son_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 6: Một nhóm học sinh đang tiến hành xây dựng và khai thác một cơ sở dữ liệu có tên là QUANLI_HS. Cơ sở dữ liệu này bao gồm các thông tin bên dưới:', '[{"id": "a", "text": "Trong bảng tt_hs, trường id_HS là khóa chính.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "b", "text": "Để biết được tên giáo viên chủ nhiệm của một học sinh thì cần phải biết được tên của học sinh đó.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Bình Sơn."}, {"id": "c", "text": "Một số học sinh đưa ra các ý kiến sau:", "isCorrect": true, "explanation": "Ý (c) là Đúng theo đáp án THPT Bình Sơn."}, {"id": "d", "text": "Câu lệnh SQL: SELECT tenHS, bangdiem_th.tb_HK1, bangdiem_th.tb_HK2, (bangdiem_th.tb_HK1+ bangdiem_th.tb_HK2*2)/3 AS “TBCN” FROM tt_hs INNER JOIN bangdiem_th WHERE id_Monhoc = “1”; dùng để liệt kê thông tin của những học sinh có id_monhoc bằng “1”.", "isCorrect": false, "explanation": "Ý (d) là Sai theo đáp án THPT Bình Sơn."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

