-- Câu hỏi Phần I của thpt_chuyen_le_khiet_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c1', 'thpt_chuyen_le_khiet_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Lĩnh vực nào sau đây có thể áp dụng AI?', '{"A": "Duy nhất trong ngành công nghiệp phần mềm.", "B": "Trong nhiều lĩnh vực như chăm sóc sức khỏe, ô tô tự lái, tài chính, và giáo dục...", "C": "Chỉ trong việc phát triển các trò chơi điện tử.", "D": "Chỉ trong các ứng dụng văn phòng."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c2', 'thpt_chuyen_le_khiet_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Cảnh báo nào sau đây liên quan đến sự phát triển quá nhanh của AI?A. AI có thể làm cho con người trở nên thông minh hơn.B. AI có thể phát triển vượt tầm kiểm soát của con người.C. AI có thể giúp nâng cao sự sáng tạo của con người.D. AI có thể cải thiện cuộc sống con người một cách nhanh chóng.', '{"A": "AI có thể làm cho con người trở nên thông minh hơn.", "B": "AI có thể phát triển vượt tầm kiểm soát của con người.", "C": "AI có thể giúp nâng cao sự sáng tạo của con người.", "D": "AI có thể cải thiện cuộc sống con người một cách nhanh chóng."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c3', 'thpt_chuyen_le_khiet_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Một hệ thống AI giúp bác sĩ xác định bệnh qua hình ảnh y tế như X-quang hoặc MRI là một ví dụ của ứng dụng nào dưới đây?A. Trợ lý ảo.', '{"A": "Trợ lý ảo.", "B": "Phân tích.", "C": "Chẩn đoán.", "D": "Nhận dạng."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c4', 'thpt_chuyen_le_khiet_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Hệ thống AI nào sau đây sử dụng nhận dạng tiếng nói để tương tác với người dùng trong các thiết bị điện thoại thông minh?A. Trợ lý ảo Siri.', '{"A": "Trợ lý ảo Siri.", "B": "Hệ thống nhận dạng khuôn mặt.", "C": "Hệ thống chẩn đoán bệnh.", "D": "Xe tự lái của Tesla."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c5', 'thpt_chuyen_le_khiet_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Khi cần kết nối một mạng LAN với Internet, loại thiết bị nào sau đây thường được sử dụng?', '{"A": "Switch.", "B": "Modem.", "C": "Hub.", "D": "Wireless Access Point."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c6', 'thpt_chuyen_le_khiet_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Các thiết bị nào sau đây được sử dụng để tạo thành một mạng LAN?', '{"A": "Thiết bị đầu cuối, cáp mạng, Switch, Hub.", "B": "Thiết bị đầu cuối, Access point.", "C": "Thiết bị đầu cuối, Switch, Hub.", "D": "Thiết bị đầu cuối, Switch, Hub, Access point."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c7', 'thpt_chuyen_le_khiet_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Phát biểu nào dưới đây đúng khi nói về điểm chung của hai địa chỉ IP 192.168.1.5 và 192.168.1.10?', '{"A": "Là địa chỉ IP phiên bản IPv6.", "B": "Bao gồm 16 bit.", "C": "Có cùng một địa chỉ mạng LAN.", "D": "Có cùng một địa chỉ máy."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c8', 'thpt_chuyen_le_khiet_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', '(12B, Chung, D1, NLa, Vận dụng) Một máy tính có địa chỉ IP là 192.168.1.9, địa chỉ đó được biểu diễn ở dạng nhị phân như thế nào?', '{"A": "11000000.10101000.00000001.00001001", "B": "11000000:10101000:00000001:00001001", "C": "01011100-10101000-00000001-00001001", "D": "01011100.10101000.00000001.00001001"}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c9', 'thpt_chuyen_le_khiet_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để tìm hiểu chương trình sau:', '{"A": "4", "B": "27", "C": "9", "D": "10"}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('lkh_p1_c10', 'thpt_chuyen_le_khiet_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào dưới đây được sử dụng để định dạng tiêu đề của một trang web?', '{"A": "<h1>", "B": "<header>", "C": "<title>", "D": "<head>"}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng đáp án trường THPT Chuyên Lê Khiết.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
