-- Câu hỏi Phần I của thpt_quang_trung_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c1', 'thpt_quang_trung_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo (AI) hẹp (Narrow AI) khác với AI rộng (General AI) ở điểm nào sau đây?', '{"A": "Chỉ thực hiện được một hoặc một vài tác vụ cụ thể.", "B": "Có khả năng tự nhận thức như con người.", "C": "Có thể giải quyết mọi vấn đề trong mọi lĩnh vực.", "D": "AI hẹp không cần dữ liệu để huấn luyện."}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c2', 'thpt_quang_trung_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Ứng dụng nào sau đây KHÔNG sử dụng công nghệ AI?', '{"A": "Tính năng mở khóa điện thoại bằng nhận diện khuôn mặt.", "B": "Phần mềm quản lý học sinh bằng bảng tính Excel thông thường.", "C": "Trợ lý ảo hỗ trợ tìm kiếm và điều khiển bằng giọng nói.", "D": "Hệ thống đề xuất sản phẩm khi mua sắm trực tuyến."}'::jsonb, 'D', 'Đáp án: D theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c3', 'thpt_quang_trung_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trong lĩnh vực y tế, ứng dụng nào sau đây là ví dụ điển hình của việc sử dụng trí tuệ nhân tạo (AI)?', '{"A": "Thay thế hoàn toàn bác sĩ trong việc phẫu thuật.", "B": "Phân tích hình ảnh y khoa để hỗ trợ chẩn đoán bệnh.", "C": "Sản xuất thuốc tự động không cần kiểm thử.", "D": "Xóa bỏ hồ sơ bệnh án truyền thống."}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c4', 'thpt_quang_trung_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Thiết bị Switch (Bộ chuyển mạch) trong mạng LAN có vai trò chính nào dưới đây?', '{"A": "Thực hiện chuyển đổi giữa tín hiệu quang và tín hiệu điện trong mạng.", "B": "Kết nối các thiết bị trong mạng cục bộ và chuyển dữ liệu đến đúng thiết bị đích.", "C": "Cung cấp kết nối không dây cho các thiết bị sử dụng mạng Wi-Fi.", "D": "Bảo vệ hệ thống mạng khỏi các phần mềm độc hại từ bên ngoài."}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c5', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao thức DNS (Domain Name System) thực hiện chức năng nào dưới đây?', '{"A": "Tự động cấp phát địa chỉ IP cho các thiết bị trong mạng.", "B": "Chuyển đổi tên miền sang địa chỉ IP tương ứng.", "C": "Truyền tải dữ liệu giữa các máy tính trong mạng.", "D": "Bảo mật và mã hóa dữ liệu khi truyền trên mạng."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c6', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Định dạng nào sau đây là địa chỉ IPv4 hợp lệ?', '{"A": "192.168.1.256", "B": "10.0.0.-1", "C": "172.16.254.1", "D": "2001:0db8:85a3:0000:0000:8a2e:0370:7334"}'::jsonb, 'D', 'Đáp án: D theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c7', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Đặc điểm nào dưới đây là nổi bật nhất của Điện toán đám mây (Cloud Computing) đối với người dùng cá nhân?', '{"A": "Yêu cầu người dùng phải trang bị máy chủ và phần cứng có chi phí cao.", "B": "Cho phép lưu trữ và truy cập dữ liệu mọi lúc, mọi nơi qua Internet.", "C": "Có thể đồng bộ và sử dụng dữ liệu mà không cần kết mạng.", "D": "Tốc độ xử lý luôn phụ thuộc vào RAM của điện thoại cá nhân."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c8', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Khi chia sẻ một thư mục trong mạng LAN trên hệ điều hành Windows, quyền "Read/Write" cho phép người dùng khác thực hiện thao tác nào sau đây?', '{"A": "Xem và mở các tệp trong thư mục đã được chia sẻ.", "B": "Xem, sao chép, chỉnh sửa và xóa các tệp trong thư mục.", "C": "Thay đổi cấu hình và quản lý toàn bộ hệ thống mạng.", "D": "Đổi tên thư mục nhưng không được truy cập nội dung bên trong."}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c9', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Trong môi trường số, hành vi nào sau đây là vi phạm bản quyền?', '{"A": "Trích dẫn một đoạn văn ngắn và ghi rõ nguồn của tác giả.", "B": "Chia sẻ đường link một bài báo công khai trên mạng xã hội.", "C": "Tải và đăng lại nội dung có bản quyền lên nền tảng cá nhân để kiếm tiền.", "D": "Mua phần mềm và cài đặt trên máy tính cá nhân theo đúng điều khoản."}'::jsonb, 'D', 'Đáp án: D theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c10', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Để tạo mật khẩu mạnh bảo vệ tài khoản mạng xã hội, quy tắc nào sau đây là SAI?', '{"A": ".", "B": "Không sử dụng thông tin cá nhân dễ đoán như ngày sinh, số điện thoại.", "C": "Sử dụng chung một mật khẩu cho tất cả các tài khoản để dễ nhớ.", "D": "Thường xuyên thay đổi mật khẩu và bật xác thực hai bước (2F"}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c11', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Một email lạ gửi đến có thông báo "Bạn đã trúng thưởng, vui lòng click vào link sau và nhập tài khoản ngân hàng để nhận tiền". Bạn nên thực hiện hành động nào dưới đây?', '{"A": "Nhấp vào link và làm theo hướng dẫn để nhận thưởng.", "B": "Báo cáo thư rác/lừa đảo (Phishing) và xóa email khỏi hộp thư.", "C": "Chuyển tiếp email cho bạn bè để cùng tham gia nhận thưởng.", "D": "Phản hồi lại email để yêu cầu cung cấp thêm thông tin chi tiết."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c12', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Một công ty công nghệ cần tuyển một nhân sự chịu trách nhiệm thiết kế, triển khai và bảo mật kho dữ liệu khách hàng. Chuyên môn nào sau đây là phù hợp nhất?', '{"A": "Lập trình viên Front-end (Front-end Developer).", "B": "Quản trị cơ sở dữ liệu (Database Administrator).", "C": "Kỹ thuật viên thiết kế đồ họa (Graphic Design Technician).", "D": "Nhân viên tiếp thị kỹ thuật số (Digital Marketer)."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c13', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Trong HTML, thẻ nào được sử dụng để chèn một liên kết (hyperlink)?', '{"A": "<link>", "B": "<href>", "C": "<a>", "D": "<url>"}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c14', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Đoạn mã HTML <body style="background-color: blue;"> có ý nghĩa nào dưới đây?', '{"A": "Đổi màu chữ của toàn bộ trang web thành màu xanh.", "B": "Đổi màu nền của toàn bộ trang web thành màu xanh.", "C": "Tạo một vùng hiển thị có nền màu xanh trong trang.", "D": "Chèn một hình ảnh có nền màu xanh vào trang Web."}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c15', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây được dùng để tạo tiêu đề lớn nhất cho trang web?', '{"A": "<h1>", "B": "<h6>", "C": "<title>", "D": "<header>"}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c16', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Để tạo một bảng trong HTML, cấu trúc nào sau đây là đúng trình tự?', '{"A": "<table>, <tr>, <td>", "B": "<table>, <td>, <tr>", "C": "<tr>, <table>, <td>", "D": "<td>, <tr>, <table>"}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c17', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Thẻ <audio> trong HTML5 được sử dụng để làm gì?', '{"A": "Chèn hình ảnh và phát video.", "B": "Chèn và phát tệp âm thanh.", "C": "Chèn video và ghi âm từ microphone.", "D": "Ghi âm từ microphone của người dùng."}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c18', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'hieu', 'ALL', 'Đoạn mã Python sau sẽ in ra kết quả bằng bao nhiêu?', '{"A": "8", "B": "9", "C": "10", "D": "11"}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c19', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Trong Python, kiểu dữ liệu nào sau đây là của biến X = [1, "Hello", 3.14]?', '{"A": "string", "B": "tuple", "C": "dictionary", "D": "list"}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c20', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Chương trình Python sau in ra kết quả nào dưới đây?', '{"A": "1 2 3 4 5", "B": "1 2 3 4", "C": "0 1 2 3 4", "D": "2 3 4 5"}'::jsonb, 'B', 'Đáp án: B theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c21', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Để khai báo một hàm trong Python, từ khóa nào dưới đây được sử dụng?', '{"A": "function", "B": "declare", "C": "def", "D": "void"}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c22', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Trong HTML, thuộc tính alt trong thẻ <img> có tác dụng nào sau đây?', '{"A": "Thiết lập kích thước hiển thị của hình ảnh.", "B": "Thay đổi kiểu hiển thị của hình ảnh theo định dạng.", "C": "Hiển thị văn bản thay thế khi ảnh không tải được.", "D": "Tạo đường viền bao quanh hình ảnh trong trang Web."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c23', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Việc ứng dụng công nghệ thông tin vào giáo dục E-learning mang lại lợi ích nào dưới đây?', '{"A": "Xóa bỏ hoàn toàn hình thức học tập trực tiếp tại trường học.", "B": "Làm giảm sự tương tác giữa người học với môi trường giáo dục.", "C": "Làm gia tăng chi phí đi lại và sinh hoạt cho người học.", "D": "Hỗ trợ người học tiếp cận nội dung linh hoạt về thời gian và địa điểm."}'::jsonb, 'A', 'Đáp án: A theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('qtr_p1_c24', 'thpt_quang_trung_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'single_choice', 'van_dung', 'ALL', 'Thuật ngữ "IoT" (Internet of Things) được hiểu là nội dung nào sau đây?', '{"A": "Hệ thống các thiết bị thông minh kết nối và trao đổi dữ liệu qua Internet.", "B": "Mạng nội bộ kết nối các máy tính trong phạm vi một tổ chức.", "C": "Giao thức dùng để bảo mật thông tin khi truy cập trang web.", "D": "Công nghệ hỗ trợ thiết kế và in ấn mô hình ba chiều."}'::jsonb, 'C', 'Đáp án: C theo hướng dẫn chấm thi THPT Quang Trung.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của thpt_quang_trung_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c1', 'thpt_quang_trung_2026', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Câu 1. Một nhóm học sinh thảo luận về giao thức mạng và Điện toán đám mây. Các nhận định sau đây đúng hay sai?', '[{"id": "a", "text": "Giao thức IP (Internet Protocol) có nhiệm vụ định tuyến các gói tin đi qua mạng Internet đến đúng đích.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Dịch vụ Google Drive, OneDrive là các ví dụ điển hình của Điện toán đám mây theo mô hình SaaS (Phần mềm như một dịch vụ).", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Quang Trung."}, {"id": "c", "text": "Điện toán đám mây yêu cầu người dùng phải tự cài đặt máy chủ vật lý tại nhà để lưu trữ.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Địa chỉ MAC (Media Access Control) của một thiết bị mạng có thể thay đổi liên tục mỗi khi khởi động lại máy tính.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c2', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Câu 2. Cho đoạn mã HTML sau:', '[{"id": "a", "text": "Đoạn mã sẽ tạo ra một danh sách có đánh số thứ tự (1, 2, 3...) cho các sở thích.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Cụm từ \"Nghe nhạc\" sẽ được hiển thị với định dạng in đậm trên trình duyệt.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Quang Trung."}, {"id": "c", "text": "Thẻ <title> quy định nội dung tiêu đề sẽ hiển thị trên tab của trình duyệt we", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Nhấp vào chữ \"Truy cập blog\", trình duyệt sẽ chuyển hướng đến địa chỉ [https://example.com](https://example.com).", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c3', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 3. Một học sinh viết đoạn chương trình Python để đếm số chẵn trong một danh sách:', '[{"id": "a", "text": "Dòng 4 if x % 2 == 0: là điều kiện kiểm tra xem biến x có phải là số chẵn hay không.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Biến count dùng để tính tổng giá trị của tất cả các phần tử trong danh sách numbers.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Quang Trung."}, {"id": "c", "text": "Chương trình sử dụng cấu trúc lặp với số lần biết trướ", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Khi chạy xong, kết quả in ra màn hình sẽ là: Ket qua là: 3.", "isCorrect": false, "explanation": "Ý (d) là Sai theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c4', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 4. Khi nghiên cứu về cấu trúc mạng và truyền dữ liệu, các nhận định sau đúng hay sai:', '[{"id": "a", "text": "Quá trình truyền dữ liệu trên Internet sử dụng phương thức chuyển mạch gói (Packet Switching).", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Modem là thiết bị duy nhất chịu trách nhiệm tìm đường đi ngắn nhất cho dữ liệu trên Internet.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Quang Trung."}, {"id": "c", "text": "Địa chỉ IPv6 được phát triển để giải quyết tình trạng cạn kiệt không gian địa chỉ của IPv4.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Giao thức TCP đảm bảo dữ liệu truyền đi một cách tin cậy bằng cách kiểm tra lỗi và yêu cầu gửi lại nếu gói tin bị mất.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c5', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 5. Khi sử dụng phần mềm chỉnh sửa ảnh (ví dụ: GIMP, Photoshop) và chỉnh sửa video, các nhận định sau đúng hay sai:', '[{"id": "a", "text": "Lớp (Layer) trong phần mềm chỉnh sửa ảnh cho phép xử lý các chi tiết độc lập mà không ảnh hưởng đến lớp khá", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Không thể chèn thêm nhạc nền (Audio) vào một tệp video đã có sẵn âm thanh gố", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án THPT Quang Trung."}, {"id": "c", "text": "", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Cắt ghép video (Trim/Cut) là thao tác làm thay đổi độ phân giải của video.", "isCorrect": false, "explanation": "Ý (d) là Sai theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('qtr_p2_c6', 'thpt_quang_trung_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 6. Về việc thiết lập kết nối các thiết bị ngoại vi và phần cứng, các nhận định sau đúng hay sai:', '[{"id": "a", "text": "Cổng VGA chỉ truyền được tín hiệu hình ảnh, không truyền được tín hiệu âm thanh.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án THPT Quang Trung."}, {"id": "b", "text": "Driver là một phần cứng vật lý gắn vào bo mạch chủ để máy tính nhận diện thiết bị mới.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án THPT Quang Trung."}, {"id": "c", "text": "Để kết nối điện thoại thông minh với máy tính để truyền file, ta chỉ có thể sử dụng cáp USB, không thể dùng Bluetooth.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án THPT Quang Trung."}, {"id": "d", "text": "Chế độ \"Duplicate\" (Nhân bản) màn hình sẽ hiển thị cùng một nội dung trên cả màn hình máy tính và máy chiếu.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án THPT Quang Trung."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

