-- Câu hỏi Phần I của thpt_tran_quoc_tuan_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c1', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Thiết bị nào sau đây có chức năng chuyên dùng cung cấp kết nối không dây cho các thành phần trong một mạng?', '{"A": "Switch.", "B": "Hub.", "C": "Access Point.", "D": "Router."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c2', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao thức mạng là gì?', '{"A": "Phần mềm giúp máy tính kết nối với Internet.", "B": "Tập hợp các quy tắc và quy định về cách thức giao tiếp để truyền dữ liệu giữa các thiết bị trong mạng.", "C": "Loại cáp mạng được sử dụng để kết nối các thiết bị trong mạng.", "D": "Thiết bị được sử dụng để kết nối các thiết bị trong mạng."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c3', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Phát biểu nào sau đây là đúng về Router?', '{"A": "Router chỉ hoạt động trong mạng nội bộ (LAN).", "B": "Router kết nối các mạng khác nhau và định tuyến gói dữ liệu giữa chúng.", "C": "Router chỉ hỗ trợ kết nối không dây.", "D": "Router không cần cấu hình để hoạt động."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c4', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Cổng nào trên một thiết bị máy tính được dùng để cắm trực tiếp dây cáp mạng có đầu RJ45?', '{"A": "Cổng Ethernet.", "B": "Cổng USB.", "C": "Cổng HDMI.", "D": "Cổng nguồn."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c5', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Khi truyền một tệp tin lớn qua mạng, giao thức TCP chia tệp tin đó thành nhiều phân đoạn (segment) nhỏ. Mục đích chính của việc đánh số thứ tự (Sequence Number) cho từng phân đoạn này là gì?', '{"A": "Để tăng tốc độ mã hóa dữ liệu trước khi gửi đi.", "B": "Để giúp bên nhận có thể sắp xếp lại các phân đoạn đúng thứ tự ban đầu và phát hiện nếu có phân đoạn bị thiếu.", "C": "Để ngăn chặn các phần mềm độc hại xâm nhập vào nội dung của gói tin.", "D": "Để định tuyến gói tin đi theo con đường ngắn nhất từ nguồn đến đích."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c6', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong giao thức TCP, quá trình "Bắt tay ba bước" (Three-way handshake) khi bắt đầu thiết lập kết nối giữa máy tính gửi và máy tính nhận có mục đích chính là gì?', '{"A": "Để nén dữ liệu giúp truyền đi nhanh hơn.", "B": "Để đồng bộ hóa số thứ tự gói tin và xác nhận cả hai bên đều sẵn sàng truyền nhận dữ liệu.", "C": "Để kiểm tra xem tệp tin có chứa virus hay không.", "D": "Để tìm đường đi ngắn nhất giữa các Router trên mạng Internet."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c7', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong các thiết bị mạng sau đây, thiết bị nào hoạt động ở tầng liên kết dữ liệu (Data link) và dùng để kết nối các thiết bị trong cùng một mạng LAN?', '{"A": "Switch.", "B": "Router.", "C": "Hub.", "D": "Modem."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c8', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong mạng LAN văn phòng, máy tính A chia sẻ một thư mục dữ liệu cho máy tính B. Hãy xác định tình huống mà máy tính B vẫn có thể truy cập được dữ liệu trong thư mục này?', '{"A": "Máy tính A đã tắt nguồn hoàn toàn để tiết kiệm điện.", "B": "Cáp mạng nối giữa máy tính A và thiết bị Switch bị rút ra.", "C": "Máy tính A đang hoạt động và quyền truy cập đã được cấp cho máy tính B.", "D": "Máy tính B thay đổi địa chỉ IP sang một lớp mạng khác với máy tính A."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c9', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Bạn muốn lấy tài liệu từ thư mục "BAI_TAP" mà bạn nhóm trưởng đã chia sẻ trên máy tính của bạn ấy trong mạng LAN. Để thực hiện việc này, bạn nên thực hiện các thao tác nào?', '{"A": "Sử dụng trình duyệt web để tìm kiếm từ khóa \"Thư mục BAI_TAP\" trên Google.", "B": "Mở cửa sổ mạng (Network) trên máy tính của mình -> Tìm tên máy tính của nhóm trưởng -> Truy cập vào thư mục \"BAI_TAP\".", "C": "Gửi một email cho nhóm trưởng yêu cầu cấp một địa chỉ website để tải thư mục đó về máy.", "D": "Tắt tường lửa (Firewall) của máy tính mình và đợi thư mục \"BAI_TAP\" tự động hiện ra trên màn hình Desktop."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c10', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Bạn chia sẻ một thư mục ảnh kỷ yếu cho các bạn trong lớp qua mạng LAN và chỉ thiết lập quyền truy cập là "Read"(chỉ đọc). Một người bạn trong lớp muốn giúp bạn xóa đi những ảnh bị mờ trong thư mục đó từ máy tính của họ. Điều gì sẽ xảy ra?', '{"A": "Người bạn đó xóa được ảnh bình thường và tệp tin sẽ biến mất khỏi máy tính của bạn.", "B": "Người bạn đó vẫn nhìn thấy ảnh nhưng khi thực hiện lệnh xóa, hệ thống sẽ báo lỗi hoặc từ chối thao tác.", "C": "Máy tính của người bạn đó sẽ tự động ngắt kết nối mạng LAN ngay khi nhấn phím Delete.", "D": "Người bạn đó chỉ có thể xem ảnh dưới dạng trắng đen chứ không xem được ảnh màu."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c11', 'thpt_tran_quoc_tuan_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Dịch vụ lưu trữ dữ liệu trực tuyến như Google Drive, OneDrive cho phép người dùng lưu trữ, chia sẻ và chỉnh sửa tệp tin trực tiếp trên trình duyệt. Các dịch vụ này được xếp vào loại dịch vụ đám mây nào?', '{"A": "IaaS (Cung cấp hạ tầng như một dịch vụ).", "B": "PaaS (Cung cấp nền tảng như một dịch vụ).", "C": "SaaS (Cung cấp phần mềm như một dịch vụ).", "D": "Network (Cung cấp mạng lưới kết nối)."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c12', 'thpt_tran_quoc_tuan_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Khi nói về việc ứng dụng Công nghệ thông tin trong quản lý đô thị và dịch vụ công hiện nay, phát biểu nào sau đây chưa chính xác?', '{"A": "Các ứng dụng như VNeID giúp người dân thực hiện các thủ tục hành chính mà không cần mang theo nhiều giấy tờ bản cứng.", "B": "Hệ thống camera giám sát đô thị chỉ có tác dụng ghi lại hình ảnh chứ không thể hỗ trợ cảnh báo vi phạm giao thông tự động.", "C": "Việc sử dụng hóa đơn điện tử giúp các cơ quan thuế quản lý minh bạch và giảm thiểu rủi ro thất thoát dữ liệu.", "D": "Các cổng dịch vụ công trực tuyến giúp rút ngắn thời gian chờ đợi và giảm chi phí đi lại cho người dân."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c13', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Trong các hành vi dưới đây, hành vi nào là biểu hiện của việc ứng xử thiếu văn hóa và vi phạm quyền riêng tư trên không gian mạng?', '{"A": "Chúc mừng sinh nhật bạn bè công khai trên dòng thời gian của họ.", "B": "Tự ý công khai số điện thoại và địa chỉ nhà của người khác khi chưa được họ đồng ý.", "C": "Gửi lời mời kết bạn cho những người có cùng sở thích học tập.", "D": "Tham gia vào các nhóm thảo luận về kiến thức tin học trên mạng xã hội."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c14', 'thpt_tran_quoc_tuan_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Việc một cá nhân thiếu kiểm chứng mà vội vàng chia sẻ các thông tin sai sự thật, xúc phạm danh dự người khác trên mạng xã hội có thể dẫn đến hệ quả nghiêm trọng nào sau đây?', '{"A": "Làm tăng tốc độ truy cập internet cho cộng đồng người dùng.", "B": "Gây tổn thương tinh thần cho nạn nhân và làm nhiễu loạn thông tin xã hội.", "C": "Giúp bài viết cá nhân nhận được nhiều lượt tương tác tích cực hơn từ bạn bè.", "D": "Làm cho các thuật toán của mạng xã hội hoạt động chính xác và minh bạch hơn."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c15', 'thpt_tran_quoc_tuan_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Một trong những đặc trưng quan trọng giúp phân biệt hệ thống Trí tuệ nhân tạo (AI) với các chương trình máy tính truyền thống là gì?', '{"A": "Có khả năng lưu trữ một lượng lớn dữ liệu trong bộ nhớ.", "B": "Có khả năng thực hiện các phép tính toán học với tốc độ cao.", "C": "Có khả năng học từ dữ liệu để tự cải thiện hiệu quả xử lý.", "D": "Có khả năng kết nối với các thiết bị ngoại vi như chuột và bàn phím."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c16', 'thpt_tran_quoc_tuan_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Trong lĩnh vực giao thông thông minh, trí tuệ nhân tạo (AI) đóng vai trò cốt lõi trong việc phát triển công nghệ nào sau đây?', '{"A": "Sản xuất các loại lốp xe có độ bền cao và chống trơn trượt.", "B": "Thiết kế các biển báo giao thông bằng chất liệu phản quang mới.", "C": "Phát triển hệ thống xe tự lái và điều khiển luồng giao thông tự động.", "D": "Xây dựng các cây cầu vượt thép để giảm thiểu ùn tắc tại các ngã tư."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c17', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Khi soạn thảo nội dung trang web bằng HTML, cặp thẻ nào thường được dùng để tạo tiêu đề có kích thước lớn nhất?', '{"A": "<h6>", "B": "<head>", "C": "<title>", "D": "<h1>"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c18', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Trong ngôn ngữ HTML, cặp thẻ nào sau đây được sử dụng để chèn một hình ảnh vào trang web?', '{"A": "<a>: anchorB. <img>: image C. <table>: tableD. <br>: break", "B": "", "C": "<table>: tableD. <br>: break", "D": ""}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c19', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Để thiết lập màu nền xanh lá (green) cho tất cả các đoạn văn (p ) và các mục danh sách (li) trong trang web, câu lệnh CSS nào sau đây là chính xác?', '{"A": "p li {background-color:green;}", "B": "p + li {background:green;}", "C": "p, li {background-color:green;}", "D": "p; li {background-color:green;}"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c20', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Để căn giữa nội dung văn bản cho tất cả các ô (<td>) nằm trong một hàng (<tr>) và đặt màu nền cho hàng đó là màu vàng, đoạn mã HTML/CSS nào sau đây là chuẩn xác và tương thích tốt nhất với các trình duyệt?', '{"A": "<tr style=\"background-color: yellow; text-align: center;\"> <td>Mục 1</td> <td>Mục 2</td> </tr>", "B": "<tr align=\"center\" color=\"yellow\"> <td>Mục 1</td> <td>Mục 2</td> </tr>", "C": "<tr style=\"align: center; background: yellow;\"> <td style=\"center\">Mục 1</td> <td>Mục 2</td> </tr>", "D": "<table style=\"text-align: center; background-color: yellow;\"> <tr> <td>Mục 1</td> <td>Mục 2</td> </tr> </table>"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c21', 'thpt_tran_quoc_tuan_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Tình huống nào sau đây thể hiện khả năng học máy (Machine Learning) của AI trong lĩnh vực giải trí?', '{"A": "Người dùng nhấn nút \"Tạm dừng\" khi đang xem một bộ phim trên ứng dụng trực tuyến.", "B": "Ứng dụng xem phim hiển thị danh sách tất cả các bộ phim hành động hiện có trong kho dữ liệu theo thứ tự bảng chữ cái.", "C": "Ứng dụng xem phim tự động đề xuất các bộ phim mới dựa trên lịch sử xem và sở thích cá nhân của người dùng trước đó.", "D": "Người dùng nhập tên phim vào ô tìm kiếm và hệ thống trả về kết quả chính xác tên bộ phim đó."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c22', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Trong thư mục dự án có tệp index.html và một thư mục tên là images chứa ảnh logo.png. Để hiển thị logo này lên trang chủ bằng thẻ <img>, cần viết thuộc tính src như thế nào cho đúng?', '{"A": "<img src=\"logo.png\" alt=\"Logo\">", "B": "<img src=\"images/logo.png\" alt=\"Logo\">", "C": "<img href=\"images/logo.png\" alt=\"Logo\">", "D": "<img src=\"/logo.png\" alt=\"Logo\">"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c23', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Khi tạo một biểu mẫu đăng ký thành viên, ở ô nhập "Số điện thoại", bạn muốn trình duyệt trên điện thoại di động tự động hiển thị bàn phím số thay vì bàn phím chữ để thuận tiện cho người dùng. Loại (type) nào của thẻ <input> là phù hợp nhất?', '{"A": "<input type=\"text\">", "B": "<input type=\"password\">", "C": "<input type=\"tel\">", "D": "<input type=\"button\">"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_tran_quoc_tuan_2026_p1_c24', 'thpt_tran_quoc_tuan_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'van_dung', 'ALL', 'Một người lập trình muốn tất cả các đoạn văn (<p>)có màu xanh, nhưng riêng đoạn văn giới thiệu bản thân phải có màu đỏ. Phương án nào sau đây là chuyên nghiệp và dễ bảo trì nhất?', '{"A": "Sử dụng thuộc tính style=\"color: red;\" trực tiếp vào thẻ <p> của đoạn giới thiệu.", "B": "Viết tất cả mã định dạng vào thẻ <body>.", "C": "Đặt một id hoặc class riêng cho đoạn văn giới thiệu (ví dụ: <p id=\"intro\">) và định nghĩa màu đỏ cho id đó trong tệp CSS.", "D": "Tạo một tệp HTML mới chỉ để chứa đoạn văn màu đỏ."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của thpt_tran_quoc_tuan_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c1', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Khi tìm hiểu về việc định dạng giao diện trang web bằng CSS và HTML, một nhóm học sinh thảo luận về cách tối ưu hóa mã nguồn. Hãy đánh giá các phát biểu sau:', '[{"id": "a", "text": "CSS (Cascading Style Sheets) là ngôn ngữ được sử dụng để định dạng cách hiển thị các thành phần của trang web như màu sắc, phông chữ và bố cục.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Việc sử dụng CSS nội tuyến (inline style) viết trực tiếp trong thẻ HTML luôn giúp mã nguồn trang web gọn gàng và dễ bảo trì hơn so với việc dùng tệp CSS bên ngoài.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Để tất cả các thẻ tiêu đề <h2> trong website có chữ màu đỏ và căn giữa, có thể viết trong tệp CSS: h2 { color: red; text-align: center; }", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Khi muốn tạo một vùng chứa nội dung có nền màu xám và bo góc, có thể định nghĩa lớp CSS: .box { background-color: gray; border-radius: 10px; } và áp dụng cho nhiều thẻ <div> khác nhau.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c2', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Trong giờ học Tin học, học sinh thiết kế một trang web giới thiệu các hợp chất hóa học và phương trình phản ứng. Hãy đánh giá các nhận định sau:', '[{"id": "a", "text": "Các thẻ <b>, <i>, <u> là các thẻ định dạng văn bản cơ bản dùng để làm chữ in đậm, in nghiêng và gạch chân trong HTML.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Đoạn mã <p><strong>Axit Sunfuric</strong> là một axit mạnh.</p> sẽ hiển thị phần \"Axit Sunfuric\" với ý nghĩa nhấn mạnh và thường được trình duyệt hiển thị in đậm.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Để hiển thị đúng công thức hóa học của Axit Sunfuric (H2SO4) trên trang web, có thể sử dụng:", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Để hiển thị đúng dạng phân số của công thức nồng độ mol CM=nV trên cùng một dòng văn bản, có thể sử dụng:", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c3', 'thpt_tran_quoc_tuan_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'CS', 'Trong giờ học về mô phỏng máy tính, một nhóm học sinh đưa ra các nhận định sau:', '[{"id": "a", "text": "Mô phỏng máy tính là việc sử dụng chương trình máy tính để tái tạo các hoạt động của một hệ thống thực hoặc giả định nhằm quan sát và phân tích hành vi của nó.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Phần mềm GeoGebra là một công cụ hỗ trợ mô phỏng chuyên sâu chủ yếu trong các lĩnh vực tài chính, kế toán và quản trị kinh doanh.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Một trong những ưu điểm quan trọng của phần mềm mô phỏng là cho phép người dùng thực hiện các thí nghiệm ảo có độ nguy hiểm cao hoặc chi phí đắt đỏ trong thực tế mà không gây rủi ro về người và tài sản.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Để mô phỏng sự rơi tự do của một vật cần thiết lập các tham số như độ cao ban đầu, khối lượng và gia tốc trọng trường để quan sát sự thay đổi vận tốc theo thời gian.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c4', 'thpt_tran_quoc_tuan_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'CS', 'Một nhóm học sinh viết chương trình Python sau để tìm giá trị lớn nhất trong danh sách số nguyên: A = [5, 12, 8, 20, 7, 15] max_val = A[0] for x in A: if x > max_val: max_val = x print("Giá trị lớn nhất là:", max_val) Xét tính chính xác của các phát biểu:', '[{"id": "a", "text": "Biến A trong chương trình trên thuộc kiểu dữ liệu danh sách (list), cho phép lưu trữ nhiều giá trị cùng một lúc.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Cấu trúc for x in A: là một vòng lặp duyệt qua từng phần tử của danh sách bắt đầu từ phần tử thứ hai đến phần tử cuối cùng.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Thuật toán đang sử dụng kỹ thuật \"lính canh\", giả định phần tử đầu tiên là lớn nhất, sau đó so sánh lần lượt để cập nhật lại giá trị lớn nhất mới.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Cần sử dụng câu lệnh if not A: để kiểm tra danh sách rỗng trước khi gán max_val = A[0]; nếu danh sách rỗng, nên thông báo “Danh sách không có dữ liệu” thay vì thực hiện thuật toán.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c5', 'thpt_tran_quoc_tuan_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Một câu lạc bộ (CLB) thiện nguyện trong nhà trường muốn xây dựng một website để giới thiệu các dự án đã thực hiện và kêu gọi quyên góp. Trang chủ cần có một biểu mẫu (form) để người dùng đăng ký tham gia thành viên và một bản đồ chỉ đường đến văn phòng CLB. Hãy đánh giá tính chính xác của các nhận định sau đây về quá trình thực hiện:', '[{"id": "a", "text": "Các phần mềm tạo website hiện nay thường cung cấp tính năng \"Kéo và thả\" (Drag and Drop) giúp người dùng không cần biết lập trình vẫn có thể tạo được trang web.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Website sau khi thiết kế xong chỉ có thể xem được trên máy tính để bàn và không thể tự động thay đổi kích thước để hiển thị trên điện thoại di động.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Để tích hợp biểu mẫu đăng ký, người dùng có thể sử dụng các tiện ích có sẵn như Google Forms và nhúng (Embed) mã HTML hoặc liên kết vào trang web thông qua công cụ của phần mềm.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Để hiển thị bản đồ chỉ đường, học sinh có thể sử dụng dịch vụ bản đồ trực tuyến (như Google Maps), sau đó nhúng vào trang web và tùy chỉnh kích thước hiển thị cho phù hợp.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_tran_quoc_tuan_2026_p2_c6', 'thpt_tran_quoc_tuan_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ICT', 'Cửa hàng sách "Tri Thức" muốn chuyển đổi việc quản lý sổ sách sang sử dụng Cơ sở dữ liệu (CSDL) để theo dõi kho hàng và hóa đơn. Một nhóm học sinh đang thực hành cài đặt và kết nối hệ quản trị CSDL MySQL bằng phần mềm HeidiSQL: Hãy đánh giá tính chính xác của các nhận định sau đây:', '[{"id": "a", "text": "Hệ quản trị CSDL là phần mềm cung cấp môi trường để người dùng có thể tạo lập, lưu trữ và khai thác dữ liệu một cách bảo mật và hiệu quả.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "HeidiSQL là phần mềm có giao diện đồ họa giúp người dùng tương tác với các hệ quản trị CSDL như MySQL, MariaDB.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Khi thiết lập kết nối (Session) trong HeidiSQL, thông tin \"Hostname/IP\" mặc định thường là 127.0.0.1 hoặc localhost để chỉ định rằng CSDL đang nằm ngay trên chính máy tính đang sử dụng.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Người dùng cần chọn thẻ “Data” để xem định nghĩa các cột và kiểu dữ liệu của bảng.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

