INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c1', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Khi nhận được một tin nhắn thông báo trúng thưởng yêu cầu nhấp vào liên kết và nhập thông tin cá nhân, em nên làm gì?', '{"A": "Chia sẻ tin nhắn cho bạn bè để cùng nhận thưởng.", "B": "Bỏ qua, không nhấp vào liên kết và báo cho người lớn hoặc giáo viên.", "C": "Nhấp vào liên kết và nhập thông tin ngay để nhận thưởng.", "D": "Trả lời tin nhắn để hỏi thêm thông tin."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c2', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Cho đoạn mã HTML sau: Khi mở trang web trên trình duyệt và nhấp vào chữ “Tìm kiếm”, điều gì sẽ xảy ra?', '{"A": "Trang web sẽ hiển thị thêm một đoạn văn mới.", "B": "Trang web sẽ bị đóng lại.", "C": "Hình ảnh sẽ được hiển thị trên trang.", "D": "Trình duyệt sẽ chuyển đến trang Google."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c3', 'thpt_dinh_tien_hoang_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao thức TCP/IP đóng vai trò gì trong mạng máy tính?', '{"A": "Lưu trữ thông tin người dùng.", "B": "Điều khiển việc bật/tắt máy tính.", "C": "Quy định cách các thiết bị kết nối và trao đổi dữ liệu với nhau trên mạng.", "D": "Tăng tốc độ xử lí của máy tính."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c4', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Vì sao cần sử dụng thẻ <body> trong một trang HTML?', '{"A": "Để liên kết đến tệp CSS.", "B": "Để khai báo tiêu đề trang web.", "C": "Để chứa các thông tin hiển thị trên trang web.", "D": "Để lưu trữ dữ liệu người dùng."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c5', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Ngôn ngữ nào sau đây được sử dụng để tạo cấu trúc cơ bản của một trang web?', '{"A": "C++.", "B": "Python.", "C": "Java.", "D": "HTML."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c6', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Khi tạo một liên kết đến trang web khác, vì sao cần sử dụng thuộc tính href trong thẻ <a>?', '{"A": "Để chèn hình ảnh vào liên kết.", "B": "Để định dạng chữ in đậm.", "C": "Để chỉ định địa chỉ trang web cần liên kết đến.", "D": "Để thay đổi màu nền trang web."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c7', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Thẻ nào trong HTML được dùng để chèn hình ảnh vào trang web?', '{"A": "<img>", "B": "<a>", "C": "<div>", "D": "<p>"}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c8', 'thpt_dinh_tien_hoang_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo (AI) được ứng dụng trong lĩnh vực nào sau đây?', '{"A": "Ghi chép bài học bằng vở.", "B": "Soạn thảo văn bản bằng tay.", "C": "Vẽ tranh bằng bút chì.", "D": "Nhận dạng khuôn mặt trên điện thoại."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c9', 'thpt_dinh_tien_hoang_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Vì sao khi giải quyết một bài toán bằng máy tính, người lập trình cần viết chương trình bằng các ngôn ngữ như Python hoặc C++?', '{"A": "Vì máy tính chỉ hiểu được ngôn ngữ tự nhiên của con người.", "B": "Vì Python và C++ giúp biểu diễn thuật toán để máy tính thực hiện giải bài toán.", "C": "Vì sử dụng Python và C++ giúp tăng dung lượng bộ nhớ máy tính.", "D": "Vì Python và C++ chỉ dùng để thiết kế giao diện."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c10', 'thpt_dinh_tien_hoang_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Một lớp học muốn kết nối nhiều máy tính với nhau để chia sẻ tài liệu và sử dụng chung máy in trong cùng một phòng. Thiết bị nào sau đây là phù hợp nhất để thực hiện nhiệm vụ này?', '{"A": "Máy chiếu.", "B": "Access Point.", "C": "Switch.", "D": "Modem."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c11', 'thpt_dinh_tien_hoang_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Ngành nghề nào sau đây không thuộc lĩnh vực tin học?', '{"A": "Thợ xây.", "B": "Thiết kế đồ họa máy tính.", "C": "Lập trình viên.", "D": "Quản trị mạng."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c12', 'thpt_dinh_tien_hoang_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Nhu cầu nhân lực trong lĩnh vực tin học hiện nay có xu hướng như thế nào?', '{"A": "Tăng cao.", "B": "Không còn cần thiết.", "C": "Giảm mạnh.", "D": "Không thay đổi."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c13', 'thpt_dinh_tien_hoang_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'hieu', 'ALL', 'Một doanh nghiệp muốn nâng cao hiệu quả quản lí và kinh doanh. Giải pháp nào sau đây là phù hợp?', '{"A": "Không sử dụng máy tính trong công việc.", "B": "Chỉ làm việc thủ công như trước.", "C": "Giảm sử dụng công nghệ trong doanh nghiệp.", "D": "Ứng dụng phần mềm và hệ thống tin học vào quản lí."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
