INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c15', 'thpt_dinh_tien_hoang_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Tại sao nghề trong lĩnh vực tin học thường yêu cầu người lao động phải học tập liên tục?', '{"A": "Vì không cần kỹ năng chuyên môn.", "B": "Vì công nghệ phát triển nhanh, cần cập nhật kiến thức mới.", "C": "Vì kiến thức tin học không thay đổi.", "D": "Vì công việc trong lĩnh vực này rất đơn giản."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c16', 'thpt_dinh_tien_hoang_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để tìm hiểu chương trình sau: Chương trình viết bằng ngôn ngữ Python Chương trình viết bằng ngôn ngữ C++ Trong chương trình Python và C++ tính tổng từ 1 đến n ở trên, vai trò của vòng lặp for là gì?', '{"A": "Lặp lại việc cộng dồn các số từ 1 đến n.", "B": "Khai báo biến cho chương trình.", "C": "In kết quả ra màn hình.", "D": "Nhập giá trị n từ bàn phím."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c17', 'thpt_dinh_tien_hoang_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Vì sao nhiều ngành nghề hiện nay cần sử dụng tin học trong công việc?', '{"A": "Vì tin học thay thế hoàn toàn con người trong mọi công việc.", "B": "Vì tin học làm tăng thời gian làm việc.", "C": "Vì tin học chỉ dùng để giải trí.", "D": "Vì tin học giúp xử lí thông tin nhanh và nâng cao hiệu quả công việc."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c18', 'thpt_dinh_tien_hoang_2026', '12D', 'Đạo đức, pháp luật thế giới ảo', 'single_choice', 'hieu', 'ALL', 'Hành vi nào sau đây là dấu hiệu của lừa đảo trên Internet?', '{"A": "Trang web yêu cầu đăng nhập để sử dụng dịch vụ quen thuộc.", "B": "Email từ người lạ yêu cầu cung cấp mật khẩu hoặc thông tin cá nhân.", "C": "Tìm kiếm thông tin học tập trên mạng.", "D": "Xem video giải trí trên các nền tảng uy tín."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
