INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c20', 'thpt_dinh_tien_hoang_2026', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Một học sinh yêu thích công nghệ, muốn làm việc trong lĩnh vực có nhu cầu nhân lực cao và cơ hội phát triển tốt. Lựa chọn nào sau đây là phù hợp nhất?', '{"A": "Không cần học thêm kỹ năng nào.", "B": "Chỉ sử dụng máy tính để giải trí.", "C": "Theo học ngành Công nghệ thông tin hoặc Khoa học máy tính.", "D": "Học nghề không liên quan đến công nghệ."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c21', 'thpt_dinh_tien_hoang_2026', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'van_dung', 'ALL', 'Ngôn ngữ lập trình nào sau đây có thể được sử dụng để viết chương trình giải quyết bài toán trên máy tính?', '{"A": "Paint và Word.", "B": "Python và C++.", "C": "HTML và CSS.", "D": "PowerPoint và Excel."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c22', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Vì sao cần sử dụng thẻ <title> trong trang web HTML?', '{"A": "Để hiển thị nội dung chính trên trang.", "B": "Để chèn hình ảnh vào trang.", "C": "Để đặt tên cho trang web hiển thị trên tab trình duyệt.", "D": "Để tạo liên kết đến trang khác."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c23', 'thpt_dinh_tien_hoang_2026', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Vì sao trí tuệ nhân tạo (AI) có thể được sử dụng để lọc thư rác trong email?', '{"A": "Vì AI làm tăng dung lượng lưu trữ email.", "B": "Vì AI có thể tự động xóa tất cả email trong hộp thư.", "C": "Vì AI giúp gửi email nhanh hơn.", "D": "Vì AI có khả năng phân tích nội dung email và nhận diện thư không mong muốn."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('thpt_dinh_tien_hoang_2026_p1_c24', 'thpt_dinh_tien_hoang_2026', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Thiết bị nào sau đây có chức năng cung cấp kết nối không dây (Wi-Fi) cho các thiết bị trong mạng?', '{"A": "Modem.", "B": "Access Point.", "C": "Switch.", "D": "Router."}'::jsonb, 'A', '') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của thpt_dinh_tien_hoang_2026
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c1', 'thpt_dinh_tien_hoang_2026', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Đoạn code HTML như sau:', '[{"id": "a", "text": "Thẻ <p> dùng để chèn hình ảnh vào trang web.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Thẻ <h1> dùng để tạo tiêu đề lớn trên trang web.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Thẻ <title> giúp hiển thị tên trang trên tab trình duyệt.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Khi nhấp vào chữ “Truy cập”, trình duyệt sẽ chuyển đến trang web có địa chỉ https://www.example.com.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c2', 'thpt_dinh_tien_hoang_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Nhận định nào sau đây đúng, nhận định nào sai?', '[{"id": "a", "text": "Access Point có chức năng phát sóng Wi-Fi giúp các thiết bị không dây kết nối vào mạng.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Khi muốn chia sẻ tệp giữa các máy tính trong cùng mạng, có thể sử dụng chức năng chia sẻ tài nguyên của hệ điều hành.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Giao thức TCP/IP được dùng để điều khiển bật/tắt máy tính từ xa.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Switch là thiết bị dùng để kết nối các máy tính trong cùng một mạng nội bộ.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c3', 'thpt_dinh_tien_hoang_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'CS', 'Nhận định nào sau đây đúng, nhận định nào sai?', '[{"id": "a", "text": "Khi thiết kế mạng, cần xác định số lượng thiết bị sẽ kết nối.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Modem có chức năng chính là kết nối các máy tính trong mạng LAN với nhau.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Việc lựa chọn thiết bị mạng phù hợp giúp đảm bảo mạng hoạt động ổn định và hiệu quả.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Khi thiết kế mạng cho một lớp học, có thể sử dụng Switch để kết nối các máy tính và Access Point để cung cấp Wi-Fi cho thiết bị di động.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c4', 'thpt_dinh_tien_hoang_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'CS', 'Để biết học sinh có hiểu rõ về thuật toán hay không, giáo viên đưa ra dãy số A = [-13, 2, 3, 6, 9, 11, 25, 38, 50, 65], biết chỉ số đầu của A là 0. Với yêu cầu tìm vị trí của số 11 trong dãy A bằng cách áp dụng thuật toán tìm kiếm nhị phân và số lần lặp lại của thuật toán. Giáo viên đưa ra các nhận định sau:', '[{"id": "a", "text": "Không áp dụng thuật toán tìm kiếm nhị phân được, vì dãy A có số âm.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Tìm kiếm nhị phân sẽ có số lần lặp ít hơn tìm kiếm tuần tự.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Lần lặp đầu tiên chỉ số đầu bên trái là 0, chỉ số cuối bên phải là 9, chỉ số giữa là 7.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Tìm được số 11 ở vị trí 5 và số lần lặp là 3.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c5', 'thpt_dinh_tien_hoang_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ICT', 'Nhận định nào sau đây đúng, nhận định nào sai?', '[{"id": "a", "text": "Trong GIMP không thể cắt (crop) hoặc thay đổi kích thước ảnh.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Việc sử dụng các lớp (layer) trong GIMP giúp chỉnh sửa ảnh linh hoạt hơn mà không ảnh hưởng trực tiếp đến ảnh gốc.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "GIMP là phần mềm dùng để chỉnh sửa và thiết kế hình ảnh.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Có thể sử dụng GIMP để thiết kế một poster học tập bằng cách chèn ảnh, thêm chữ và hiệu ứng.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('thpt_dinh_tien_hoang_2026_p2_c6', 'thpt_dinh_tien_hoang_2026', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ICT', 'Nhận định nào sau đây đúng, nhận định nào sai?', '[{"id": "a", "text": "Cáp USB chỉ dùng để sạc điện, không thể truyền dữ liệu.", "isCorrect": true, "explanation": "Mệnh đề (a) của đề thi."}, {"id": "b", "text": "Kết nối Bluetooth cho phép truyền dữ liệu không dây giữa các thiết bị ở khoảng cách gần.", "isCorrect": false, "explanation": "Mệnh đề (b) của đề thi."}, {"id": "c", "text": "Máy tính có thể kết nối với máy in để in tài liệu.", "isCorrect": true, "explanation": "Mệnh đề (c) của đề thi."}, {"id": "d", "text": "Khi muốn trình chiếu bài giảng từ máy tính lên màn hình lớn, có thể kết nối máy tính với máy chiếu bằng cáp HDMI.", "isCorrect": false, "explanation": "Mệnh đề (d) của đề thi."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

