ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, base_xp = EXCLUDED.base_xp;

-- Câu hỏi Phần I của de_on_luyen_01
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c1', 'de_on_luyen_01', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Thuật ngữ nào sau đây mô tả khả năng học của trí tuệ nhân tạo dựa trên dữ liệu?', '{"A": "Machine Learning", "B": "Data Mining", "C": "Learning Data", "D": "Cloud Computing"}'::jsonb, 'A', 'Câu 1. Thuật ngữ nào sau đây mô tả khả năng học của trí tuệ nhân tạo dựa trên dữ liệu?
A. Đúng. Machine Learning (Học máy) là lĩnh vực của AI cho phép hệ thống học từ dữ
liệu để cải thiện hiệu suất.
B. Sai. Data Mining là khai phá dữ liệu, không phải là "học".
C. Sai. Learning Data không phải thuật ngữ chuẩn.
D. Sai. Cloud Computing là điện toán đám mây, không liên quan đến khả năng học.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c2', 'de_on_luyen_01', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Ứng dụng nào sau đây không tích hợp khả năng hiểu ngôn ngữ tự nhiên của trí tuệ nhân tạo?', '{"A": "Siri", "B": "Google Assistant", "C": "Microsoft Word", "D": "Alexa"}'::jsonb, 'C', 'Câu 2. Ứng dụng nào sau đây không tích hợp khả năng hiểu ngôn ngữ tự nhiên của trí
tuệ nhân tạo?
A. Sai. Siri là trợ lí ảo, có tích hợp khả năng hiểu ngôn ngữ tự nhiên.
B. Sai. Google Assistant là trợ lí ảo, có tích hợp khả năng hiểu ngôn ngữ tự nhiên.
C. Đúng. Microsoft Word là phần mềm soạn thảo văn bản, không tích hợp khả năng hiểu
ngôn ngữ tự nhiên như các trợ lý ảo.
D. Sai. Alexa là trợ lí ảo, có tích hợp khả năng hiểu ngôn ngữ tự nhiên.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c3', 'de_on_luyen_01', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo AI không có khả năng nào sau đây?', '{"A": "Phân tích dữ liệu lớn để đưa ra dự đoán.", "B": "Học từ kinh nghiệm để cải thiện hiệu suất.", "C": "Cảm nhận cảm xúc một cách tự nhiên như con người.", "D": "Nhận diện hình ảnh và giọng nói."}'::jsonb, 'C', 'Câu 3. Trí tuệ nhân tạo AI không có khả năng nào sau đây?
A. Sai. AI hoàn toàn có thể phân tích Big Data.
B. Sai. AI có khả năng học từ kinh nghiệm (Machine Learning).
C. Đúng. AI không thể cảm nhận cảm xúc một cách tự nhiên như con người.
D. Sai. AI có thể nhận diện hình ảnh và giọng nói nhờ công nghệ như Computer Vision,
Speech Recognition.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c4', 'de_on_luyen_01', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây đúng về tình hình lao động trong một công ty khi sử dụng AI để tự động hóa quy trình kiểm tra chất lượng sản phẩm?', '{"A": "Tăng nhu cầu tuyển thêm nhân viên kiểm tra chất lượng sản phẩm.", "B": "Cần có lao động kỹ thuật để quản lí và vận hành hệ thống AI.", "C": "Tăng nhanh số lượng lao động do cần nhiều người làm việc cùng AI.", "D": "Tất cả lao động sẽ bị thay thế hoàn toàn bởi AI."}'::jsonb, 'B', 'Câu 4. Phương án nào sau đây đúng về tình hình lao động trong một công ty khi sử dụng
A. Sai. AI thay thế hoặc hỗ trợ công việc kiểm tra chất lượng, không cần thêm người làm
việc đó.
B. Đúng. Sử dụng AI sẽ tăng nhu cầu về nhân sự kỹ thuật để giám sát và bảo trì hệ thống.
C. Sai. Không cần nhiều lao động hơn khi AI đã tự động hóa.
D. Sai. AI không thay thế hoàn toàn con người trong mọi vị trí.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c5', 'de_on_luyen_01', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ def dem_uoc(n): dem = 0 for i in range(1, n//2+1): if n % i == 0: dem += 1 return dem int dem_uoc(int n) { int dem = 0; for (int i = 1; i <= n / 2; ++i) { if (n % i == 0) { dem++; } } return dem; } Phương án nào sau đây là kết quả của lời gọi hàm dem_uoc(12)?', '{"A": "5", "B": "6", "C": "12", "D": "0"}'::jsonb, 'A', 'Câu 5. Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau:
Đoạn chương trình viết bằng ngôn ngữ
Python
Đoạn chương trình viết bằng ngôn ngữ C++
def dem_uoc(n):
dem = 0
for i in range(1, n//2+1):
if n % i == 0: dem += 1
return dem
int dem_uoc(int n) {
int dem = 0;
for (int i = 1; i <= n / 2; ++i) {
if (n % i == 0) {
dem++;
}
}
return dem;
}
Phương án nào sau đây là giá trị của dem_uoc(12)?
A. Đúng. Hàm dem_uoc thực hiện đếm các ước của n (không xét ước n). Vậy
dem_uoc(12) là 5 (5 ước là: 1, 2, 3, 4, 6).') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c6', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Thiết bị Access Point trong mạng có chức năng nào sau đây?', '{"A": "Khuếch đại tín hiệu Internet từ nhà cung cấp dịch vụ.", "B": "Kết nối các thiết bị mạng thông qua cáp mạng.", "C": "Cung cấp kết nối không dây cho các thiết bị trong mạng cục bộ.", "D": "Định tuyến đường truyền gói tin giữa các mạng cục bộ."}'::jsonb, 'C', 'Câu 6. Thiết bị Access Point trong mạng có chức năng nào sau đây?
A. Sai. Access Point không có chức năng khuếch đại Internet.
B. Sai. Kết nối thiết bị qua cáp là chức năng của Switch hoặc Hub.
C. Đúng. Access Point là thiết bị tạo kết nối không dây (Wi-Fi) trong mạng LAN.
D. Sai. Định tuyến là chức năng của Router.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c7', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Thiết bị nào sau đây chuyển đổi dữ liệu số thành tín hiệu tương tự để truyền qua mạng?', '{"A": "Switch", "B": "Access Point", "C": "Hub", "D": "Modem"}'::jsonb, 'D', 'Câu 7. Thiết bị nào sau đây chuyển đổi dữ liệu số thành tín hiệu tương tự để truyền qua
mạng?
A. Sai. Switch chỉ chuyển dữ liệu trong mạng cục bộ.
B. Sai. Access Point cung cấp kết nối Wi-Fi, không xử lý chuyển đổi tín hiệu.
C. Sai. Hub kết nối thiết bị trong mạng cục bộ.
D. Đúng. Modem (viết tắt của Modulator-Demodulator) chuyển đổi dữ liệu số thành tín
hiệu tương tự và ngược lại.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c8', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao thức TCP không có vai trò nào sau đây?', '{"A": "Gán địa chỉ nguồn và đích cho gói tin.", "B": "Chia nhỏ dữ liệu thành các gói tin.", "C": "Đánh số thứ tự trên các gói tin.", "D": "Đảm bảo dữ liệu được truyền đi một cách chính xác."}'::jsonb, 'A', 'Câu 8. Giao thức TCP không có vai trò nào sau đây?
A. Đúng. Gán địa chỉ nguồn và đích là nhiệm vụ của IP (Internet Protocol).
B. Sai. TCP chia nhỏ dữ liệu thành các gói tin.
C. Sai. TCP đánh số thứ tự để đảm bảo đúng trình tự.
D. Sai. TCP đảm bảo dữ liệu truyền đi chính xác và đáng tin cậy.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c9', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Công ty có 2 mạng LAN riêng biệt tại dãy văn phòng A và B. Thiết bị nào sau đây cần được lắp đặt để hai mạng LAN này có thể trao đổi dữ liệu với nhau?', '{"A": "Hub", "B": "Switch", "C": "Router", "D": "Modem"}'::jsonb, 'C', 'Câu 9. Công ty có 2 mạng LAN riêng biệt tại dãy văn phòng A và B. Thiết bị nào sau đây
cần được lắp đặt để hai mạng LAN này có thể trao đổi dữ liệu với nhau?
A. Sai. Hub không hỗ trợ kết nối giữa các mạng khác nhau.
B. Sai. Switch chỉ kết nối thiết bị trong phạm vi một mạng LAN.


C. Đúng. Router kết nối và định tuyến dữ liệu giữa các mạng khác nhau.
D. Sai. Modem chuyển đổi dữ liệu số thành tín hiệu tương tự để truyền qua mạng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c10', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Giao tiếp trong không gian mạng không có lợi ích nào sau đây?', '{"A": "Tiết kiệm thời gian, chi phí.", "B": "Không liên tục do yếu tố kỹ thuật.", "C": "Công cụ giao tiếp đa dạng.", "D": "Xóa bỏ rào cản giao tiếp."}'::jsonb, 'B', 'Câu 10. Giao tiếp trong không gian mạng không có lợi ích nào sau đây?
A. Sai. Tiết kiệm thời gian, chi phí là lợi ích rõ ràng.
B. Đúng. Không liên tục do yếu tố kỹ thuật là một hạn chế, không phải lợi ích.
C. Sai. Công cụ giao tiếp đa dạng (email, chat, video call...) là lợi ích.
D. Sai. Giao tiếp qua mạng giúp xóa bỏ rào cản về khoảng cách địa lý.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c11', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Không nên chia sẻ thông tin cá nhân trên không gian mạng vì lí do nào sau đây?', '{"A": "Bạn bè khó kết nối và chia sẻ.", "B": "Tăng nguy cơ bị xâm phạm quyền riêng tư.", "C": "Tạo điều kiện hợp tác và học tập hiệu quả.", "D": "Góp phần xây dựng hình ảnh cá nhân tích cực."}'::jsonb, 'B', 'Câu 11. Không nên chia sẻ thông tin cá nhân trên không gian mạng vì lí do nào sau đây?
A. Sai. Không liên quan, không chia sẻ thông tin cá nhân, bạn bè vẫn có thể kết.
B. Đúng. Việc chia sẻ thông tin cá nhân dễ khiến bạn bị xâm phạm quyền riêng tư, đánh
cắp thông tin, hoặc bị lừa đảo.
C. Sai. Chia sẻ thông tin cá nhân không liên quan đến hiệu quả học tập.
D. Sai. Hình ảnh có nhân tích cực không liên quan đến việc bạn có đăng thông tin cá
nhân hay không.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c12', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Lan bắt gặp bài đăng trên mạng xã hội của một bạn trong lớp có nội dung sai lệch và mang tính chế giễu người khác. Với vai trò là người sử dụng mạng có trách nhiệm Lan nên làm gì sau đây?', '{"A": "Bỏ qua bài viết vì không liên quan đến mình.", "B": "Chụp màn hình và chia sẻ lại để cảnh báo người khác.", "C": "Gửi tin nhắn riêng góp ý nhẹ nhàng và khuyến khích bạn gỡ bài.", "D": "Bình luận công khai để chỉ trích bạn đó trước mọi người."}'::jsonb, 'C', 'Câu 12. Lan bắt gặp bài đăng trên mạng xã hội của một bạn trong lớp có nội dung sai
lệch và mang tính chế giễu người khác. Với vai trò là người sử dụng mạng có trách nhiệm
Lan nên làm gì sau đây?
A. Sai. Bỏ qua là thiếu trách nhiệm, không giúp cải thiện môi trường mạng.
B. Sai. Chia sẻ lại có thể làm sự việc lan rộng.
C. Đúng. Góp ý riêng tư, nhẹ nhàng và khuyến khích gỡ bài là hành động văn minh,
đúng tinh thần ứng xử trên mạng.
D. Sai. Chỉ trích công khai dễ dẫn đến mâu thuẫn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c13', 'de_on_luyen_01', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Người làm nghề dịch vụ thuộc ngành Công nghệ thông tin không thực hiện công việc nào sau đây?', '{"A": "Hỗ trợ kĩ thuật, khắc phục sự cố phần mềm.", "B": "Khắc phục lỗi phần cứng máy tính.", "C": "Triển khai các giải pháp bảo mật hệ thống.", "D": "Bảo trì máy tính và thiết bị ngoại vi."}'::jsonb, 'C', 'Câu 13. Người làm nghề dịch vụ thuộc ngành Công nghệ thông tin (CNTT) không thực
hiện công việc nào sau đây?
A. Sai. Đây là công việc thường gặp trong nghề dịch vụ CNTT.
B. Sai. Khắc phục lỗi phần cứng là công việc của người làm nghề dịch vụ CNTT.
C. Đúng. Triển khai giải pháp bảo mật là công việc thuộc nhóm nghề bảo mật hệ thống
thông tin.
D. Sai. Bảo trì máy tính, thiết bị ngoại vi là công việc của người làm nghề dịch vụ CNTT.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c14', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Người làm nghề Quản trị mạng cần thường xuyên giám sát và bảo trì hệ thống mạng vì lí do nào sau đây?', '{"A": "Đảm bảo người dùng không thể truy cập vào hệ thống mạng.", "B": "Đảm bảo hệ thống hoạt động liên tục, ổn định và sớm phát hiện sự cố.", "C": "Tăng tốc độ truy cập Internet cho tất cả người dùng.", "D": "Dễ dàng truy cập vào mọi máy tính trong hệ thống."}'::jsonb, 'B', 'Câu 14. Người làm nghề Quản trị mạng cần thường xuyên giám sát và bảo trì hệ thống
mạng vì lí do nào sau đây?
A. Sai. Mục tiêu là duy trì hoạt động của hệ thống, không phải chặn người dùng.
B. Đúng. Đảm bảo hệ thống hoạt động ổn định, tránh sự cố là nhiệm vụ quan trọng của
quản trị mạng.
C. Sai. Tăng tốc độ mạng không phải là mục tiêu chính của giám sát, bảo trì.
D. Sai. Giám sát, bảo trì không đồng nghĩa với truy cập vào mọi máy tính, điều này liên
quan đến quyền riêng tư và bảo mật.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c15', 'de_on_luyen_01', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Doanh nghiệp A cần trang bị máy tính và thiết bị tin học phục vụ công việc. Họ nên liên hệ người thuộc nhóm nghề nào sau đây để được tư vấn về phần cứng và thiết bị ngoại vi phù hợp?', '{"A": "Dịch vụ kĩ thuật Công nghệ thông tin.", "B": "Lập trình ứng dụng.", "C": "Quản trị cơ sở dữ liệu.", "D": "Thiết kế đồ họa."}'::jsonb, 'A', 'Câu 15. Doanh nghiệp A cần trang bị máy tính và thiết bị tin học phục vụ công việc. Họ
nên liên hệ người thuộc nhóm nghề nào sau đây để được tư vấn về phần cứng và thiết bị
ngoại vi phù hợp?
A. Đúng. Nhân viên dịch vụ kỹ thuật CNTT có nhiệm vụ tư vấn, lắp đặt, bảo trì thiết bị
phần cứng và ngoại vi.
B. Sai. Lập trình ứng dụng tập trung vào viết phần mềm.
C. Sai. Quản trị CSDL làm việc với dữ liệu, không tư vấn phần cứng.
D. Sai. Thiết kế đồ họa không liên quan đến tư vấn thiết bị.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c16', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Sử dụng thẻ HTML nào sau đây để chèn một đường kẻ ngang trong trang web?', '{"A": "<hr>", "B": "<br>", "C": "<p>", "D": "<pre>"}'::jsonb, 'A', 'Câu 16. Sử dụng thẻ HTML nào sau đây để chèn một đường kẻ ngang trong trang web?
A. Đúng. Thẻ <hr> dùng để tạo một đường kẻ ngang.
B. Sai. Thẻ <br> xuống dòng.
C. Sai. Thẻ <p> tạo đoạn văn bản.
D. Sai. Thẻ <pre> hiển thị văn bản giữ nguyên định dạng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c17', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ <img> trong HTML không có thuộc tính nào sau đây?', '{"A": "alt", "B": "src", "C": "href", "D": "title"}'::jsonb, 'C', 'Câu 17. Thẻ <img> trong HTML không có thuộc tính nào sau đây?
A. Sai. alt dùng để hiển thị văn bản thay thế nếu ảnh không tải được.
B. Sai. src là đường dẫn tới ảnh.
C. Đúng. href là thuộc tính của thẻ <a>.
D. Sai. title dùng để hiển thị chú thích khi rê chuột vào ảnh.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c18', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thuộc tính CSS nào sau đây định kiểu bo tròn các góc của đường viền?', '{"A": "border-style", "B": "border-radius", "C": "border-color", "D": "border-width"}'::jsonb, 'B', 'Câu 18. Thuộc tính CSS nào sau đây định kiểu bo tròn các góc của đường viền?
A. Sai. border-style quy định kiểu đường viền (solid, dashed…).
B. Đúng. border-radius định kiểu bo tròn các góc của đường viền.
C. Sai. border-color định kiểu màu viền.
D. Sai. border-width định kiểu độ dày viền.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c19', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Trong CSS không tồn tại bộ chọn nào sau đây?', '{"A": "Tên định danh.", "B": "Tên miền.", "C": "Tên lớp.", "D": "Tên phần tử."}'::jsonb, 'B', 'Câu 19. Trong CSS không tồn tại bộ chọn nào sau đây?
A. Sai. Bộ chọn theo ID (tên định danh) tồn tại.
B. Đúng. "Tên miền" không phải là bộ chọn hợp lệ trong CSS.
C. Sai. Bộ chọn theo lớp (.class) phổ biến.
D. Sai. Tên phần tử là một bộ chọn trong CSS.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c20', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây phù hợp để trình bày danh sách các món ăn yêu thích trên một trang web?', '{"A": "<table>", "B": "<li>", "C": "<ul>", "D": "<ol>"}'::jsonb, 'C', 'Câu 20. Thẻ HTML nào sau đây phù hợp để trình bày danh sách các món ăn yêu thích
trên một trang web?
A. Sai. <table> dùng cho bảng, không phải danh sách.
B. Sai. <li> là phần tử bên trong danh sách, không dùng độc lập.
C. Đúng. <ul> tạo danh sách không thứ tự, phù hợp liệt kê sở thích.
D. Sai. <ol> tạo danh sách có thứ tự. Liệt kê sở thích không cần danh sách có thứ tự.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c21', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Sử dụng mã CSS nào sau đây để tất cả đề mục cấp 1 hiển thị màu đỏ bất kể các quy tắc CSS khác?', '{"A": "h1 {color: red !priority;}", "B": "#h1 {color: red;}", "C": ".h1 {color: red;}", "D": "h1 {color: red !important;}"}'::jsonb, 'D', 'Câu 21. Sử dụng mã CSS nào sau đây để tất cả đề mục cấp 1 hiển thị màu đỏ bất kể các
quy tắc CSS khác?


A. Sai. !priority không tồn tại trong CSS.
B. Sai. Chọn phần tử có id="h1", không áp dụng cho tất cả h1.
C. Sai. Chọn class tên h1, không phải thẻ h1.
D. Đúng. !important giúp quy tắc CSS có độ ưu tiên cao nhất.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c22', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Nam muốn tạo bảng điểm gồm các cột: Họ tên, Toán, Văn. Mã HTML nào sau đây tạo dòng tiêu đề cho bảng điểm?', '{"A": "<tr><th>Họ tên</th><th>Toán</th><th>Văn</th></tr>", "B": "<tr><td>Họ tên</td><td>Toán</td><td>Văn</td></tr>", "C": "<th>Họ tên</th><th>Toán</th><th>Văn</th>", "D": "<td><th>Họ tên</th><th>Toán</th><th>Văn</th></td>"}'::jsonb, 'A', 'Câu 22. Nam muốn tạo bảng điểm gồm các cột: Họ tên, Toán, Văn. Mã HTML nào sau
đây tạo dòng tiêu đề cho bảng điểm?
A. Đúng. <th> là thẻ tạo ô tiêu đề của bảng.
B. Sai. <td> tạo ô dữ liệu.
C. Sai. Thiếu phần tử dòng <tr>.
D. Sai. Không hợp lệ: <th> không được đặt bên trong <td>.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c23', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Lan sử dụng mã HTML nào sau đây để chèn một liên kết trên trang web cá nhân sao cho khi người dùng nhấp vào, trang liên kết sẽ mở ra trong một tab mới của trình duyệt?', '{"A": "<a href=\"https://info.com\">Trang của tôi</a>", "B": "<a href=\"https://info.com\" target=\"_self\">Trang của tôi</a>", "C": "<a href=\"https://info.com\" target=\"_blank\">Trang của tôi</a>", "D": "<a src=\"https://info.com\" target=\"_blank\">Trang của tôi</a>"}'::jsonb, 'C', 'Câu 23. Lan sử dụng mã HTML nào sau đây để chèn một liên kết trên trang web cá nhân
sao cho khi người dùng nhấp vào, trang liên kết sẽ mở ra trong một tab mới của trình
duyệt?
A. Sai. Mở trong cùng tab (mặc định).
B. Sai. target="_self" mở trong tab hiện tại.
C. Đúng. target="_blank" mở liên kết trong tab mới.
D. Sai. Thẻ <a> dùng href, không dùng src.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_01_p1_c24', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Cho đoạn mã HTML sau: <ol style="list-style-type: decimal-leading-zero;"> <li>Bước 1</li> <li>Bước 2</li> </ol> Kết quả nào sau đây được hiển thị trên trình duyệt?', '{"A": "1. Bước 1 2. Bước 2", "B": "01. Bước 1 02. Bước 2", "C": "I. Bước 1 II. Bước 2", "D": "a. Bước 1 b. Bước 2"}'::jsonb, 'B', 'Câu 24. Cho đoạn mã HTML sau:
<ol style="list-style-type: decimal-leading-zero;">
<li>Bước 1</li>
<li>Bước 2</li>
</ol>
Kết quả nào sau đây được hiển thị trên trình duyệt?
A. Sai. Hiển thị số 1, 2, …- không đúng với mã CSS đã dùng.
B. Đúng. Giá trị decimal-leading-zero hiển thị số dạng 01, 02, ...
C. Sai. I, II thuộc kiểu danh sách La Mã (upper-roman).
D. Sai. a, b thuộc kiểu lower-alpha.
PHẦN II
Điểm tối đa của 01 câu hỏi là 1 điểm.
- Thí sinh chỉ lựa chọn đúng chính xác 01 ý trong 1 câu hỏi được 0,1 điểm
- Thí sinh chỉ lựa chọn đúng chính xác 02 ý trong 1 câu hỏi được 0,25 điểm
- Thí sinh ch') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_01
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c1', 'de_on_luyen_01', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Trường phổ thông A tổ chức thi Tin học trực tuyến tại 2 phòng máy. Đề thi được lưu trên một máy chủ nội bộ. Các máy tính học sinh truy cập vào máy chủ để lấy đề thi và nộp bài vào thư mục được chỉ định. Máy tính không được kết nối Internet trong suốt thời gian thi để đảm bảo tính nghiêm túc và bảo mật.', '[{"id": "a", "text": "Máy chủ nội bộ và các máy học sinh cùng kết nối trong một mạng LAN.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Thư mục chứa đề thi được chia sẻ cho học sinh với quyền Full control.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Ở mỗi phòng máy, cần một Switch để kết nối các máy tính thành mạng LAN.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Để học sinh có thể nộp bài lên máy chủ vào cuối giờ thi, cần kết nối lại Internet cho toàn bộ máy tính.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c2', 'de_on_luyen_01', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một cửa hàng quản lí bán hàng bằng hệ thống dữ liệu gồm bảng KhachHang và DonHang. Bảng KhachHang gồm các cột: MaKH (Mã khách hàng), HoTen (Họ tên), DiaChi (Địa chỉ), SoDienThoai (Số điện thoại). Thông tin đơn hàng được lưu trong bảng DonHang với các cột: MaHD (Mã hóa đơn), MaKH, NgayDatHang (Ngày đặt hàng), TongTien (Tổng tiền mua hàng). Sau đây là các ý kiến thảo luận của nhóm học sinh về hệ thống trên:', '[{"id": "a", "text": "MaKH là khóa chính trong bảng KhachHang.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Bảng DonHang có 4 trường dữ liệu.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng."}, {"id": "c", "text": "Nếu cửa hàng không có chi nhánh thì chỉ cần sử dụng hệ cơ sở dữ liệu phân tán để quản lí cơ sở dữ liệu.", "isCorrect": false, "explanation": "Mệnh đề (c) là Sai."}, {"id": "d", "text": "Câu lệnh SELECT* FROM DonHang; truy vấn họ tên tất cả khách hàng đã mua hàng. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Định hướng Khoa học máy tính", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c3', 'de_on_luyen_01', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Minh viết chương trình sắp xếp danh sách các số nguyên do người dùng nhập vào. Chương trình của Minh được chia thành các hàm riêng biệt: – Hàm nhập dữ liệu từ người dùng. – Hàm sắp xếp danh sách. – Hàm in kết quả ra màn hình. Sau đây là đoạn lệnh mô tả một trong các hàm trong chương trình của Bình: Chọn một trong hai ngôn ngữ Python hoặc C++ để tìm hiểu: Hàm viết bằng ngôn ngữ Python Hàm viết bằng ngôn ngữ C++ def bubble_sort(arr, n): for i in range(n): for j in range(n-i-1): if arr[j] > arr[j+1]: arr[j], arr[j+1] = arr[j+1], arr[j] void bubble_sort(int arr[], int n) { for (int i = 0; i < n-1; i++) { for (int j = 0; j < n-i-1; j++) { if (arr[j] > arr[j+1]) { swap(arr[j], arr[j+1]); } } } } Một số bạn học sinh nhận xét về tình huống trên như sau:', '[{"id": "a", "text": "Hàm bubble_sort thực hiện thao tác sắp xếp danh sách số nguyên theo thuật toán sắp xếp trộn.", "isCorrect": false, "explanation": "Mệnh đề (a) là Sai."}, {"id": "b", "text": "Việc chia chương trình thành nhiều hàm riêng biệt là thể hiện của lập trình theo mô đun.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng."}, {"id": "c", "text": "Hàm bubble_sort sử dụng kỹ thuật duyệt tuần tự để so sánh các phần tử trong danh sách.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Độ phức tạp thuật toán của hàm sắp xếp trong trường hợp xấu nhất là O(n²).", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c4', 'de_on_luyen_01', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'Trong buổi tham quan tại một trung tâm y tế thông minh, các bạn học sinh được giới thiệu về cách ứng dụng học máy trong y tế. Nhân viên tại trung tâm lấy ví dụ: Dự đoán nguy cơ mắc tiểu đường của bệnh nhân dựa trên các yếu tố như chỉ số BMI, độ tuổi, huyết áp, mức đường huyết, và tiền sử bệnh lý gia đình. Sau buổi tham quan, bạn Huy đưa ra một số nhận định như sau:', '[{"id": "a", "text": "Mô hình dự đoán bệnh tiểu đường là một ứng dụng của học máy có giám sát (Supervised Learning).", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mô hình học máy tự động học từ dữ liệu có sẵn thay vì phải được lập trình cụ thể từng quy tắc.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng."}, {"id": "c", "text": "Trong học máy, không cần xử lý dữ liệu vì máy tính có thể hiểu được mọi dạng dữ liệu đầu vào.", "isCorrect": false, "explanation": "Mệnh đề (c) là Sai."}, {"id": "d", "text": "Khoa học dữ liệu kết hợp cả thống kê, lập trình và kiến thức chuyên ngành (như y học) để đưa ra phân tích và dự đoán. Định hướng Tin học ứng dụng", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c5', 'de_on_luyen_01', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Minh được giáo viên giao nhiệm vụ thiết kế trang web giới thiệu dự án học tập của nhóm, sử dụng phần mềm thiết kế web trực tuyến. Minh khởi tạo một dự án, chọn mẫu giao diện phù hợp, sau đó thêm các trang như: Giới thiệu dự án, Nhật ký học tập và Góp ý. Minh chèn thêm văn bản mô tả, hình ảnh hoạt động nhóm, video minh họa và biểu mẫu thu thập ý kiến. Sau khi xem sản phẩm của Minh, các bạn trong lớp đưa ra một số ý kiến như sau:', '[{"id": "a", "text": "Muốn thêm video vào trang web cần phải viết mã lệnh HTML.", "isCorrect": false, "explanation": "Mệnh đề (a) là Sai."}, {"id": "b", "text": "Trang Góp ý có thể chèn biểu mẫu Google Forms để thu thập ý kiến từ người xem.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng."}, {"id": "c", "text": "Phần mềm thiết kế web trực tuyến không cho phép thay đổi vị trí các thành phần như hình ảnh hay văn bản.", "isCorrect": false, "explanation": "Mệnh đề (c) là Sai."}, {"id": "d", "text": "Sau khi trang web hoàn thiện, chỉ có thể xuất bản trực tuyến (public) để mọi người truy cập.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_01_p2_c6', 'de_on_luyen_01', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Bệnh viện X triển khai hệ thống quản lý bệnh nhân bằng cơ sở dữ liệu. CSDL QL_BenhNhan gồm 3 bảng với cấu trúc như sau: • BENHNHAN (MaBN, HoTen, NgaySinh, GioiTinh, DiaChi): lưu thông tin mã bệnh nhân, họ tên, ngày sinh, giới tính và địa chỉ. • BENH (MaBenh, TenBenh, MoT', '[{"id": "a", "text": ": lưu mã bệnh, tên bệnh và mô tả chi tiết. • DIEUTRI (MaBN, MaBenh, NgayNhapVien, NgayRaVien, KetQua): lưu thông tin điều trị gồm mã bệnh nhân, mã bệnh, ngày nhập viện, ngày ra viện và kết quả điều trị. Một nhóm học sinh đang học về Cơ sở dữ liệu đưa ra một số ý kiến về hệ thống trên như sau: a) Khi một bệnh nhân ra viện, MaBN của bệnh nhân đó trong bảng BENHNHAN sẽ tự động xóa.", "isCorrect": false, "explanation": "Mệnh đề (a) là Sai."}, {"id": "b", "text": "Khi tạo bảng DIEUTRI, cần tạo khóa ngoại liên kết với bảng BENHNHAN và BENH.", "isCorrect": true, "explanation": "Mệnh đề (b) là Đúng."}, {"id": "c", "text": "Khi nhập dữ liệu trường MaBN trong bảng BENHNHAN, dữ liệu đó phải tồn tại trong bảng DIEUTRI.", "isCorrect": false, "explanation": "Mệnh đề (c) là Sai."}, {"id": "d", "text": "Để hiển thị tên bệnh nhân điều trị bệnh ''Cúm'' có kết quả là ''Khỏi'', sử dụng lệnh truy vấn: SELECT HoTen FROM BENHNHAN JOIN DIEUTRI ON BENHNHAN.MaBN = DIEUTRI.MaBN JOIN BENH ON DIEUTRI.MaBenh = BENH.MaBenh WHERE TenBenh = ''Cúm'' AND KetQua = ''Khỏi'';", "isCorrect": true, "explanation": "Mệnh đề (d) là Đúng."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

