-- Câu hỏi Phần I của de_on_luyen_02
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c1', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây mô tả đúng ứng dụng của trí tuệ nhân tạo trong thực tế?', '{"A": "Soạn văn bản bằng tay.", "B": "Gửi thư điện tử thủ công.", "C": "Đọc và phân tích ngữ nghĩa văn bản.", "D": "Xem tivi qua sóng analog."}'::jsonb, 'A', 'Câu 1. Phương án nào sau đây mô tả đúng ứng dụng của trí tuệ nhân tạo trong thực tế?
A. Sai. Soạn văn bản bằng tay là hoạt động thủ công, không có sự hỗ trợ của công nghệ thông
minh hay tự động hóa.
B. Sai. Gửi email theo cách thủ công là hành động người dùng thực hiện trực tiếp, không liên
quan đến trí tuệ nhân tạo.
C. Đúng. Đọc và phân tích ngữ nghĩa văn bản là ứng dụng tiêu biểu của trí tuệ nhân tạo, thường
thấy trong các hệ thống xử lý ngôn ngữ tự nhiên như chatbot, dịch máy, trợ lý ảo,…
D. Sai. Xem tivi qua sóng analog là công nghệ truyền hình truyền thống, không có sự tham gia
của AI.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c2', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây đúng về đặc điểm của AI?', '{"A": "Chỉ hoạt động khi có Internet.", "B": "Có khả năng học từ dữ liệu.", "C": "Thực hiện các hành động lặp đi lặp lại.", "D": "Cảm nhận cảm xúc như con người."}'::jsonb, 'A', 'Câu 2. Phương án nào sau đây đúng về đặc điểm của AI?
A. Sai. AI không cần Internet vẫn có thể hoạt động.
B. Đúng. AI có khả năng học từ dữ liệu để cải thiện hiệu suất.
C. Sai. Thực hiện lặp lại là đặc điểm của tự động hóa, không phải AI.
D. Sai. AI không cảm nhận được cảm xúc như con người.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c3', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trong hệ thống đề xuất video của YouTube, trí tuệ nhân tạo đóng vai trò nào sau đây?', '{"A": "Phát nhạc ngẫu nhiên.", "B": "Lọc quảng cáo tĩnh.", "C": "Gợi ý video phù hợp sở thích.", "D": "Tắt âm thanh nền."}'::jsonb, 'A', 'Câu 3. Trong hệ thống đề xuất video của YouTube, trí tuệ nhân tạo đóng vai trò nào sau đây?
A. Sai. Phát nhạc ngẫu nhiên có thể dùng thuật toán đơn giản, không cần AI.
B. Sai. Lọc quảng cáo tĩnh không phải vai trò chính của AI trong đề xuất video.
C. Đúng. AI phân tích hành vi người dùng để gợi ý video theo sở thích.
D. Sai. Tắt âm thanh nền là chức năng kỹ thuật, không phải ứng dụng của AI.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c4', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Một trung tâm dự báo thời tiết đang xem xét áp dụng trí tuệ nhân tạo để nâng cao chất lượng dự báo. AI được sử dụng để thực hiện nhiệm vụ nào sau đây là phù hợp?', '{"A": "Soạn thảo văn bản dự báo tự động.", "B": "Phân tích dữ liệu khí tượng, đưa ra mô hình dự đoán.", "C": "Phát sóng bản tin thời tiết trên tivi.", "D": "In các bản đồ thời tiết ra giấy."}'::jsonb, 'A', 'Câu 4. Một trung tâm dự báo thời tiết đang xem xét áp dụng trí tuệ nhân tạo để nâng cao chất
lượng dự báo. AI được sử dụng để thực hiện nhiệm vụ nào sau đây là phù hợp?
A. Sai. Soạn thảo văn bản không phải nhiệm vụ trọng tâm trong dự báo thời tiết.
B. Đúng. AI được dùng để phân tích dữ liệu lớn, nhận dạng mẫu và dự đoán xu hướng thời tiết.
C. Sai. Phát sóng bản tin không phải ứng dụng chính của AI trong dự báo thời tiết.
D. Sai. In bản đồ là thao tác thủ công, không liên quan đến AI.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c5', 'de_on_luyen_02', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Cho đoạn chương trình sau: Python C++ sum = 0 for i in range(1, 6): sum += i print(sum) #include <iostream> using namespace std; int main() { int sum = 0; for (int i = 1; i <= 5; i++) { sum += i; } cout << sum << endl; return 0; } Kết quả xuất ra màn hình là giá trị nào sau đây?', '{"A": "10", "B": "15", "C": "20", "D": "25"}'::jsonb, 'A', 'Câu 5. Kết quả xuất ra màn hình là giá trị nào sau đây?
A. Sai. 1 + 2 + 3 + 4 + 5 = 15, không phải 10.
B. Đúng. Vòng lặp cộng các số từ 1 đến 5, tổng là 15.
C. Sai. 20 là sai kết quả.
D. Sai. 25 không phải tổng đúng.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c6', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Địa chỉ IP có tác dụng nào sau đây trong mạng Internet?', '{"A": "Định danh thiết bị.", "B": "Đổi tên tệp tin gửi đi.", "C": "Định danh gói tin.", "D": "Bảo mật các gói tin."}'::jsonb, 'A', 'Câu 6. Địa chỉ IP có tác dụng nào sau đây trong mạng Internet?
A. Đúng. Địa chỉ IP dùng để định danh thiết bị trên mạng Internet.
B. Sai. Địa chỉ IP không dùng để đổi tên tệp tin gửi đi.
C. Sai. Địa chỉ IP định danh thiết bị, không phải gói tin.
D. Sai. Địa chỉ IP không liên quan đến bảo mật các gói tin.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c7', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây đúng về chức năng của giao thức HTTPS?', '{"A": "Quản lí tài khoản người dùng.", "B": "Mã hóa dữ liệu khi truyền qua mạng.", "C": "Thiết kế trang web.", "D": "Tăng tốc độ truyền tin qua mạng."}'::jsonb, 'A', 'Câu 7. Phương án nào sau đây đúng về chức năng của giao thức HTTPS?
A. Sai. HTTPS không quản lí tài khoản người dùng.
B. Đúng. HTTPS mã hóa dữ liệu khi truyền qua mạng để bảo mật thông tin.
C. Sai. HTTPS không thiết kế trang web.
D. Sai. HTTPS không tăng tốc độ truyền tin mà tập trung bảo mật.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c8', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Access Point có vai trò nào sau đây trong hệ thống mạng không dây?', '{"A": "Chia sẻ máy in.", "B": "Mở rộng vùng phủ sóng Wifi.", "C": "Quản lí tài khoản Google.", "D": "Định tuyến gói tin trong mạng."}'::jsonb, 'A', 'Câu 8. Access Point có vai trò nào sau đây trong hệ thống mạng không dây?
A. Sai. Chia sẻ máy in không phải chức năng chính của Access Point.
B. Đúng. Access Point mở rộng vùng phủ sóng Wifi trong mạng không dây.
C. Sai. Quản lí tài khoản Google không liên quan đến Access Point.
D. Sai. Access Point không định tuyến gói tin mà chỉ phát sóng Wifi.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c9', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong một mạng LAN, Switch đảm nhiệm chức năng nào sau đây?', '{"A": "Phát Wifi cho điện thoại.", "B": "Định tuyến dữ liệu ra Internet.", "C": "Chuyển dữ liệu giữa các thiết bị trong mạng.", "D": "Lưu trữ dữ liệu người dùng."}'::jsonb, 'A', 'Câu 9. Trong một mạng LAN, Switch đảm nhiệm chức năng nào sau đây?
A. Sai. Phát Wifi là chức năng của Router hoặc Access Point.
B. Sai. Định tuyến là chức năng của Router, không phải Switch.
C. Đúng. Switch chuyển dữ liệu giữa các thiết bị trong mạng LAN.
D. Sai. Lưu trữ dữ liệu không phải chức năng của Switch.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c10', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Phát biểu nào sau đây mô tả hành vi văn minh trên mạng?', '{"A": "Chia sẻ tin chưa xác thực.", "B": "Gửi tin nặc danh hàng loạt.", "C": "Kiểm chứng thông tin trước khi chia sẻ", "D": "Phát tán ảnh chế gây hiểu lầm."}'::jsonb, 'A', 'Câu 10. Phát biểu nào sau đây mô tả hành vi văn minh trên mạng?
A. Sai. Chia sẻ tin chưa xác thực có thể gây hiểu nhầm, không văn minh.
B. Sai. Gửi tin nặc danh hàng loạt là hành vi gây rối.
C. Đúng. Kiểm chứng thông tin trước khi chia sẻ là hành vi có trách nhiệm và văn minh.
D. Sai. Phát tán ảnh chế gây hiểu lầm dễ gây tranh cãi, không phù hợp.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c11', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Phát biểu nào sau đây là hành động không văn minh trên mạng?', '{"A": "Bình luận lịch sự.", "B": "Tôn trọng quyền riêng tư.", "C": "Hỏi đáp học tập.", "D": "Chia sẻ tin giả."}'::jsonb, 'A', 'Câu 11. Phát biểu nào sau đây là hành động không văn minh trên mạng?
A. Sai. Bình luận lịch sự là hành vi văn minh và tích cực trên mạng.
B. Sai. Tôn trọng quyền riêng tư là một chuẩn mực đạo đức quan trọng (hành vi văn minh).
C. Sai. Hỏi đáp học tập là hoạt động tích cực.
D. Đúng. Gửi tin giả là hành vi không văn minh, gây hoang mang.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c12', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Hành vi nào dưới đây thể hiện ứng xử phù hợp khi học online?', '{"A": "Tắt mic khi không phát biểu.", "B": "Mở mic nói chuyện riêng.", "C": "Gửi sticker không liên quan trong tiết học.", "D": "Đổi tên tham gia bằng biệt danh lạ."}'::jsonb, 'A', 'Câu 12. Hành vi nào dưới đây thể hiện ứng xử phù hợp khi học online?
A. Đúng. Tắt mic khi không phát biểu giúp tránh ồn và tập trung học tập.
B. Sai. Mở mic nói chuyện riêng gây mất tập trung và làm phiền bạn bè.
C. Sai. Gửi sticker không liên quan làm gián đoạn tiết học.
D. Sai. Đổi tên bằng biệt danh lạ có thể gây hiểu nhầm, GV khó theo dõi.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c13', 'de_on_luyen_02', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Nghề nào sau đây trong nhóm nghề dịch vụ thuộc ngành Công nghệ thông tin?', '{"A": "Quản trị mạng máy tính.", "B": "Sửa chữa, bảo trì máy tính.", "C": "Xây dựng phần mềm.", "D": "Phân tích thiết kế hệ thống."}'::jsonb, 'A', 'Câu 13. Nghề nào sau đây trong nhóm nghề dịch vụ thuộc ngành Công nghệ thông tin (CNTT)?
A. Sai. Quản trị mạng máy tính là nhóm nghề Quản trị thuộc ngành CNTT.
B. Đúng. Sửa chữa, bảo trì máy tính thuộc nhóm nghề dịch vụ CNTT.
C. Sai. Xây dựng phần mềm thuộc nhóm nghề phát triển phần mềm.
D. Sai. Phân tích thiết kế hệ thống không phải nghề dịch vụ CNTT.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c14', 'de_on_luyen_02', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Một chuyên viên quản trị hệ thống cần có kiến thức nào sau đây?', '{"A": "Kĩ năng giao tiếp.", "B": "Hiểu rõ mạng máy tính và hệ điều hành.", "C": "Biết nhiều ngôn ngữ lập trình.", "D": "Kĩ năng xử lí ảnh."}'::jsonb, 'A', 'Câu 14. Một chuyên viên quản trị hệ thống cần có kiến thức nào sau đây?
A. Sai. Kĩ năng giao tiếp không phải kiến thức.
B. Đúng. Hiểu rõ mạng máy tính và hệ điều hành là kiến thức nền tảng.
C. Sai. Biết nhiều ngôn ngữ lập trình không phải yêu cầu chính của quản trị hệ thống.
D. Sai. Kĩ năng xử lí ảnh không liên quan trực tiếp đến quản trị hệ thống.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c15', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'An là chuyên viên an toàn thông tin được giao nhiệm vụ bảo vệ hệ thống công ty khỏi các cuộc tấn công mạng. Trong vai trò đó, An thực hiện công việc nào sau đây?', '{"A": "Biên tập video giới thiệu sản phẩm.", "B": "Phát triển trò chơi điện tử cho công ty.", "C": "Giám sát, bảo vệ dữ liệu số khỏi các cuộc tấn công mạng.", "D": "Viết bài báo về an toàn thông tin để quảng bá cho công ty."}'::jsonb, 'A', 'Câu 15. An là chuyên viên an toàn thông tin được giao nhiệm vụ bảo vệ hệ thống công ty khỏi
các cuộc tấn công mạng. Trong vai trò đó, An thực hiện công việc nào sau đây?
A. Sai. Biên tập video không thuộc nhiệm vụ an toàn thông tin.


B. Sai. Phát triển trò chơi điện tử không phải công việc của chuyên viên an toàn thông tin.
C. Đúng. Giám sát, bảo vệ dữ liệu khỏi các cuộc tấn công mạng là nhiệm vụ chính.
D. Sai. Viết bài báo là hoạt động truyền thông, không phải nhiệm vụ bảo vệ hệ thống.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c16', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây tạo danh sách có thứ tự trong trang web?', '{"A": "<ul>", "B": "<ol>", "C": "<li>", "D": "<a>"}'::jsonb, 'A', 'Câu 16. Thẻ HTML nào sau đây tạo danh sách có thứ tự trong trang web?
A. Sai. Thẻ <ul> tạo danh sách không có thứ tự.
B. Đúng. Thẻ <ol> tạo danh sách có thứ tự.
C. Sai. <li> dùng để định nghĩa từng mục trong danh sách, không tạo danh sách.
D. Sai. <a> dùng để tạo liên kết, không tạo danh sách.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c17', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây đúng để căn giữa tiêu đề <h1> theo chiều ngang trong CSS?', '{"A": "align: center;", "B": "center-text: true;", "C": "text-align: center;", "D": "position: center;"}'::jsonb, 'A', 'Câu 17. Phương án nào sau đây đúng để căn giữa tiêu đề <h1> theo chiều ngang trong CSS?
A. Sai. align không phải thuộc tính hợp lệ trong CSS cho việc căn giữa văn bản.
B. Sai. center-text không phải là cú pháp hợp lệ trong CSS.
C. Đúng. text-align: center; là cú pháp đúng để căn giữa nội dung văn bản.
D. Sai. position: center; là cú pháp sai trong CSS.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c18', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Đoạn mã CSS nào sau đây thiết lập kích thước chữ tiêu đề h1 là 32 pixel?', '{"A": "h1 { font-size: 32px; }", "B": "h1 { size: 32px; }", "C": "h1 { font: 32; }", "D": "h1 { text-size: 32px; }"}'::jsonb, 'A', 'Câu 18. Đoạn mã CSS nào sau đây sẽ thiết lập kích thước chữ tiêu đề h1 là 32 pixel?
A. Đúng. font-size: 32px; là cú pháp đúng để thiết lập kích thước chữ.
B. Sai. size không phải thuộc tính CSS hợp lệ.
C. Sai. font: 32; không đủ thông tin và sai cú pháp.
D. Sai. text-size không phải thuộc tính hợp lệ trong CSS.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c19', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Mã HTML nào sau đây đúng cú pháp để tạo một liên kết mở ra trong tab mới?', '{"A": "<a href=\"page.html\" open>Trang</a>", "B": "<a href=\"page.html\" newtab>Trang</a>", "C": "<a href=\"page.html\" target=\"_blank\">Trang</a>", "D": "<a newtab href=\"page.html\">Trang</a>"}'::jsonb, 'A', 'Câu 19. Mã HTML nào sau đây là đúng cú pháp để tạo một liên kết mở ra trong tab mới?
A. Sai. open không phải thuộc tính hợp lệ cho thẻ <a>.
B. Sai. newtab không phải là thuộc tính hợp lệ.
C. Đúng. target="_blank" là thuộc tính mở liên kết trong tab mới.
D. Sai. newtab không phải cú pháp đúng của HTML.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c20', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Cần thay đổi nội dung mặc định trong cặp thẻ <title> </title> vì lí do nào sau đây?', '{"A": "Hiển thị tiêu đề trang trên tab trình duyệt và trong kết quả tìm kiếm.", "B": "Tăng tính thẩm mỹ cho phần nội dung chính trong trang web.", "C": "Trình duyệt tải trang web nhanh hơn.", "D": "Hỗ trợ người dùng đăng nhập nhanh hơn vào trang web."}'::jsonb, 'A', 'Câu 20. Cần thay đổi nội dung mặc định trong cặp thẻ <title> </title> vì lí do nào sau đây?
A. Đúng. Nội dung trong thẻ <title> hiển thị trên tab trình duyệt và kết quả tìm kiếm, giúp người
dùng nhận biết trang web.
B. Sai. Thẻ <title> không ảnh hưởng đến thẩm mỹ phần nội dung chính.
C. Sai. Nội dung thẻ <title> không làm trình duyệt tải trang nhanh hơn.
D. Sai. Thẻ <title> không hỗ trợ chức năng đăng nhập nhanh hơn.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c21', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Để gắn tệp CSS ngoài vào tài liệu HTML, thẻ nào sau đây được sử dụng đúng cách trong phần <head>?', '{"A": "<style src=\"style.css\">", "B": "<css link=\"style.css\">", "C": "<link rel=\"stylesheet\" href=\"style.css\">", "D": "<script type=\"css\" src=\"style.css\">"}'::jsonb, 'A', 'Câu 21. Để gắn tệp CSS ngoài vào tài liệu HTML, thẻ nào sau đây được sử dụng đúng cách
trong phần <head>?
A. Sai. <style> không dùng thuộc tính src, dùng cho CSS nội tuyến.
B. Sai. <css> không phải là thẻ hợp lệ trong HTML.
C. Đúng. <link rel="stylesheet" href="style.css"> là cú pháp đúng để liên kết CSS ngoài.
D. Sai. <script> dùng cho JavaScript, không phải cho CSS.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c22', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Khi thiết kế trang web bằng HTML, trường hợp nào sau đây cần sử dụng thẻ <img>?', '{"A": "Chèn hình ảnh minh họa vào trang web.", "B": "Tạo các đoạn văn bản dài trên trang web.", "C": "Thêm liên kết đến các trang web khác.", "D": "Tạo các bảng dữ liệu trên trang web."}'::jsonb, 'A', 'Câu 22. Khi thiết kế trang web bằng HTML, trường hợp nào sau đây cần sử dụng thẻ <img>?
A. Đúng. Thẻ <img> dùng để chèn hình ảnh minh họa vào trang web.
B. Sai. Đoạn văn bản dài dùng thẻ <p> hoặc các thẻ văn bản khác.
C. Sai. Thêm liên kết dùng thẻ <a>.
D. Sai. Tạo bảng dữ liệu dùng thẻ <table>.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c23', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Lan sử dụng mã CSS nào sau đây để định kiểu màu nền toàn bộ trang web đang thiết kế?', '{"A": "body { background-color: yellow; }", "B": "div { background-color: yellow; }", "C": "p { color: yellow; }", "D": "body { font-size: 16px; }"}'::jsonb, 'A', 'Câu 23. Lan sử dụng mã CSS nào sau đây để định kiểu màu nền toàn bộ trang web đang thiết
kế?
A. Đúng. body { background-color: yellow; } sẽ thay đổi màu nền cho toàn trang.
B. Sai. Chỉ ảnh hưởng đến các phần tử div, không phải toàn bộ trang.


C. Sai. Chỉ đổi màu chữ đoạn văn, không phải màu nền.
D. Sai. Chỉ thay đổi kích thước chữ, không đổi màu nền.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_02_p1_c24', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Khi thiết kế giao diện web, Lan muốn tạo khoảng cách đều đặn giữa các đoạn văn bằng cách đặt lề trên và dưới là 10px, lề trái và phải là 20px. Lan cần sử dụng mã CSS nào sau?', '{"A": "p { margin: 10px 20px; }", "B": "p { margin: 20px 10px; }", "C": "p { padding: 10px 20px; }", "D": "p { border: 10px 20px; }"}'::jsonb, 'A', 'Câu 24. Khi thiết kế giao diện web, Lan muốn tạo khoảng cách đều đặn giữa các đoạn văn bằng
cách đặt lề trên và dưới là 10px, lề trái và phải là 20px. Lan cần sử dụng mã CSS nào sau?
A. Đúng. Đặt lề trên/dưới 10px, trái/phải 20px đúng yêu cầu.
B. Sai. Đặt lề trên/dưới là 20px, trái/phải 10px, không đúng yêu cầu.
C. Sai. Thuộc tính padding là khoảng cách đến nội dung bên trong phần tử, không phải lề ngoài.
D. Sai. Thuộc tính border là viền, không phải khoảng cách lề.
PHẦN II
Điểm tối đa của 01 câu hỏi là 1 điểm.
- Thí sinh chỉ lựa chọn đúng chính xác 01 ý trong 1 câu hỏi được 0,1 điểm
- Thí sin') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_02
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c1', 'de_on_luyen_02', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Hòa đang học trực tuyến bằng laptop qua Wi-Fi. Mạng thỉnh thoảng bị chập chờn dù chỉ có một thiết bị kết nối. Hòa mang laptop lại gần Router thì tín hiệu cải thiện rõ. Sau đó, Hòa kiểm tra thấy địa chỉ IP của máy là 192.168.1.5 và boăn khoăn không biết vì sao máy mình có địa chỉ này. Hòa cũng biết Router là thiết bị định tuyến dữ liệu, nhưng cậu thắc mắc vì sao nó lại có thể phát sóng Wi-Fi. Một số ý kiến như sau:', '[{"id": "a", "text": "Nếu chỉ có một thiết bị kết nối, mạng sẽ luôn ổn định.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Khoảng cách giữa Laptop và thiết bị phát sóng ảnh hưởng đến tín hiệu mạng.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Địa chỉ 192.168.1.5 là một địa chỉ IP thuộc dải mạng cục bộ (LAN).", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Router nhà Hòa sử dụng có tích hợp chức năng Access Point nên có thể phát Wifi.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c2', 'de_on_luyen_02', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một hệ thống quản lý thư viện trường học lưu thông tin sách trong bảng SACH gồm các cột: MaSach (Mã sách), TenSach (Tên sách), TacGia (Tác giả), NamXB (Năm xuất bản). Thông tin bạn đọc được lưu trong bảng BANDOC với các cột: MaBD (Mã bạn đọc), HoTen, Lop, GioiTinh. Thông tin mượn sách được lưu trong bảng MUONSACH với các cột: MaBD, MaSach, NgayMuon, NgayTra. Sau đây là các ý kiến thảo luận của nhóm học sinh về hệ thống trên:', '[{"id": "a", "text": "MaSach trong bảng SACH bắt buộc có kiểu dữ liệu số nguyên.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "c), HoTen, Lop, GioiTinh. Thông tin mượn sách được lưu trong bảng MUONSACH với các cột: MaBD, MaSach, NgayMuon, NgayTra. Sau đây là các ý kiến thảo luận của nhóm học sinh về hệ thống trên: a) MaSach trong bảng SACH bắt buộc có kiểu dữ liệu số nguyên. b)", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": ", HoTen, Lop, GioiTinh. Thông tin mượn sách được lưu trong bảng MUONSACH với các cột: MaBD, MaSach, NgayMuon, NgayTra. Sau đây là các ý kiến thảo luận của nhóm học sinh về hệ thống trên: a) MaSach trong bảng SACH bắt buộc có kiểu dữ liệu số nguyên. b) MaBD là khóa chính trong bảng MUONSACH. c) Hệ thống quản lí thư viện trường là hệ cơ sở dữ liệu tập trung.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Sử dụng câu truy vấn sau để hiển thị tên các bạn đọc có mượn sách của thư viện. SELECT DISTINCT BANDOC.HoTen FROM BANDOC JOIN MUONSACH ON BANDOC.MaBD = MUONSACH.MaBD; B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c3', 'de_on_luyen_02', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Trong buổi học Tin học, cô giáo yêu cầu học sinh cài đặt cấu trúc dữ liệu ngăn xếp (stack) bằng ngôn ngữ lập trình. An viết đoạn chương trình bằng C++, còn Bình viết bằng Python. Cả hai đều thực hiện thao tác thêm phần tử (push), loại bỏ phần tử (pop) và in phần tử trên cùng (top). Cô giáo yêu cầu lớp xác định thứ tự phần tử được đưa ra khi thực hiện lệnh pop ba lần sau khi đã push lần lượt các giá trị 1, 2, 3 vào ngăn xếp. Mã Python của Bình Mã C++ của An stack = [] stack.append(1) stack.append(2) stack.append(3) print(stack[-1]); stack.pop() stack<int> s; s.push(1); s.push(2); s.push(3); cout << s.top(); s.pop(); Một số ý kiến như sau:', '[{"id": "a", "text": "Cả hai ngôn ngữ đều dùng nguyên lí LIFO (Last In First Out) cho ngăn xếp.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Giá trị đầu tiên được đưa ra màn hình sau thao tác top hoặc [-1] là 1.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Sau ba lần pop, ngăn xếp sẽ rỗng.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Nếu push lần lượt 1, 2, 3 rồi pop ba lần, thứ tự giá trị lấy ra sẽ là 3, 2, 1.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c4', 'de_on_luyen_02', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'Minh tham gia một cuộc thi phân tích dữ liệu với đề bài dự đoán kết quả học tập của học sinh dựa trên dữ liệu điểm số, số buổi vắng và thời gian học ở nhà. Sau khi tìm hiểu, Minh quyết định dùng mô hình học máy đơn giản là hồi quy tuyến tính. Cậu chia bộ dữ liệu thành hai phần: tập huấn luyện và tập kiểm tra. Sau quá trình huấn luyện, Minh dùng tập huấn luyện để đánh giá mô hình. Khi thấy kết quả rất cao, Minh cho rằng mô hình rất tốt. Tuy nhiên, bạn cùng lớp tỏ ra nghi ngờ vì Minh chưa đánh giá mô hình trên tập kiểm tra (dữ liệu chưa được học trước đó). Một số ý kiến như sau:', '[{"id": "a", "text": "Hồi quy tuyến tính là một mô hình học máy có thể dùng để dự đoán giá trị số.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Tập huấn luyện nên dùng để kiểm tra độ chính xác của mô hình sau khi học xong.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Nếu chỉ đánh giá mô hình trên tập huấn luyện, kết quả có thể sai lệch do mô hình nhớ quá kĩ dữ liệu đã học.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Việc đánh giá mô hình trên tập kiểm tra giúp kiểm chứng khả năng dự đoán của mô hình với dữ liệu mới.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c5', 'de_on_luyen_02', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Trong tiết Tin học, cô giáo yêu cầu học sinh thực hành thiết kế một trang web đơn giản bằng phần mềm hỗ trợ tạo trang web trực tuyến. Linh chọn một công cụ phù hợp để tạo trang web giới thiệu câu lạc bộ học tập của lớp. Cô sử dụng các tính năng có sẵn để chèn hình ảnh, văn bản, liên kết và chọn bố cục phù hợp. Sau khi hoàn thành, Linh chia sẻ trang web cho bạn bè xem thử, nhưng một số bạn không thể truy cập. Lúc đó, Linh mới nhận ra mình chưa thiết lập đúng chế độ chia sẻ. Một số ý kiến như sau:', '[{"id": "a", "text": "Phần mềm tạo web trực tuyến cho phép tạo trang web bằng cách kéo – thả, không cần viết mã HTML.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Phần mềm tạo web trực tuyến cung cấp mẫu trang web có sẵn, Linh có thể chọn để tạo trang nhanh hơn.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Sau khi chèn văn bản, Linh không thể định dạng phông chữ, màu sắc, cỡ chữ theo sở thích.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Cần chỉnh quyền chia sẻ và công khai trang để mọi người có thể truy cập vào trang web.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_02_p2_c6', 'de_on_luyen_02', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một cửa hàng triển khai hệ thống quản lý bán hàng bằng cơ sở dữ liệu (CSDL) gồm 3 bảng: • SANPHAM (MaSP, TenSP, DonGi', '[{"id": "a", "text": ": lưu thông tin sản phẩm gồm mã, tên và đơn giá. • KHACHHANG (MaKH, HoTen, SDT, DiaChi): lưu thông tin khách hàng gồm mã khách hàng, họ tên, số điện thoại và địa chỉ. • HOADON (MaHD, MaKH, MaSP, SoLuong, NgayLap): lưu các hóa đơn với mã hóa đơn, mã khách hàng, mã sản phẩm, số lượng và ngày lập hóa đơn. Một số ý kiến như sau: a) Khi tạo bảng KHACHHANG, thêm ràng buộc UNIQUE vào trường SDT nếu muốn số điện thoại không trùng nhau.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Sử dụng lệnh UPDATE để cập nhật khách hàng mới của cửa hàng.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Muốn khi xóa một khách hàng thì các hóa đơn liên quan cũng bị xóa theo, cần thiết lập ràng buộc khóa ngoại với tùy chọn ON DELETE CASCADE giữa bảng HOADON và bảng KHACHHANG.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Để hiển MaHD và SoLuong của hóa đơn có số lượng mua nhiều nhất, sử dụng lệnh SQL sau: SELECT MaHD, SoLuong FROM HOADON WHERE SoLuong = (SELECT MAX(SoLuong) FROM HOADON);", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

