INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c1', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Công việc nào dưới đây thuộc nhóm ngành phân tích và xử lý dữ liệu?', '{"A": "Quản lý và cấu hình hệ thống mạng nội bộ.", "B": "Cài đặt phần mềm bảo mật cho hệ thống máy tính.", "C": "Phân tích dữ liệu bán hàng để hỗ trợ ra quyết định kinh doanh.", "D": "Sửa chữa phần cứng máy tính bị hỏng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c2', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Kỹ năng nào dưới đây KHÔNG thuộc phạm vi công việc của chuyên viên quản trị hệ thống mạng?', '{"A": "Cấu hình và giám sát hoạt động của hệ thống mạng.", "B": "Thiết kế giao diện đồ họa cho website.", "C": "Cập nhật phần mềm bảo mật hệ thống định kỳ.", "D": "Phân tích và xử lý sự cố kết nối mạng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c3', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Để tạo một danh sách không có thứ tự trong HTML với các mục được hiển thị bằng hình vuông đặc (▪). Đoạn mã nào sau đây là đúng?', '{"A": "<ul start=\"square\">", "B": "<ol start=\"square\">", "C": "<ul type=\"square\">", "D": "<ol type=\"square\">"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c4', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Nhúng một hình ảnh vào trang web bằng thẻ <img>, để hiển thị đoạn văn bản "Logo công ty" thay thế cho hình ảnh bị lỗi. Thuộc tính trong thẻ <img> nào dưới đây là đúng?', '{"A": "src", "B": "title", "C": "alt", "D": "href"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c5', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Phương án nào dưới đây đúng về kết quả áp dụng CSS, khi một trang web đồng thời sử dụng tệp CSS ngoài (liên kết bằng thẻ <link>) và thẻ <style> nội bộ, với cùng một thuộc tính được áp dụng cho một phần tử?', '{"A": "Trang web sẽ không hiển thị đúng cách do xung đột CSS. -- 1 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "B": "Trình duyệt sẽ ngẫu nhiên chọn một trong hai thuộc tính để áp dụng.", "C": "Giá trị các thuộc tính trong thẻ <style> nội bộ sẽ được ưu tiên áp dụng.", "D": "Các thuộc tính trong tệp CSS ngoài sẽ được ưu tiên áp dụng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c6', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Ứng dụng nào sau đây là ví dụ điển hình của trí tuệ nhân tạo (AI) trong chẩn đoán bệnh?', '{"A": "Phần mềm sử dụng học máy để phân tích hình ảnh y khoa và phát hiện dấu hiệu bệnh lý.", "B": "Ứng dụng nhắc lịch uống thuốc và ghi nhận phản hồi của bệnh nhân theo thời gian thực.", "C": "Nền tảng phân tích thống kê hồ sơ bệnh án nhằm đưa ra các báo cáo sức khỏe tổng quát.", "D": "Hệ thống hỗ trợ theo dõi tình trạng bệnh nhân và cảnh báo khi có chỉ số bất thường."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c7', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Hành vi nào sau đây được xem là vi phạm Luật Sở hữu trí tuệ?', '{"A": "Tự sáng tác một bài hát và chia sẻ công khai trên mạng xã hội.", "B": "Chia sẻ đường link bài báo trên trang web chính thức của tòa soạn.", "C": "Tải và sử dụng phần mềm có bản quyền mà không mua giấy phép.", "D": "Sử dụng phần mềm miễn phí theo đúng điều khoản của nhà cung cấp."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c8', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây là đúng khi nói về vai trò của Modem ?', '{"A": "Chuyển đổi tín hiệu giữa dạng số và dạng tương tự khi truyền dữ liệu.", "B": "Phát tín hiệu không dây và cấp địa chỉ IP cho các thiết bị trong mạng.", "C": "Lưu trữ tạm thời dữ liệu mạng và thực hiện phân phối gói tin đến đích.", "D": "Kết nối các máy tính trong mạng cục bộ thông qua cáp mạng chuyên dụng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c9', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Hành vi nào sau đây bị xem là vi phạm pháp luật trên không gian mạng?', '{"A": "Tạo nhóm trò chuyện riêng để thảo luận học tập cùng bạn bè.", "B": "Bình luận thể hiện ý kiến cá nhân về một bộ phim đang chiếu.", "C": "Phát tán phần mềm độc hại gây ảnh hưởng đến dữ liệu của người khác.", "D": "Sử dụng biệt danh thay cho tên thật khi đăng ký tài khoản."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c10', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Để tạo một trang web có một đoạn văn bản quan trọng được đánh dấu bằng màu đỏ và chữ in đậm, đoạn văn bản này được bao quanh bởi thẻ <p>. Sử dụng bộ chọn CSS nào dưới đây để định dạng đoạn văn bản này?', '{"A": "mark { color: red; font-weight: bold; }", "B": "#p { color: red; font-weight: bold; } -- 2 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "C": ".p { color: red; font-weight: bold; }", "D": "p { color: red; font-weight: bold; }"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c11', 'de_on_luyen_05', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ s = 0 for i in range(1,6): s += (i*i - 2*i) print(s) int s = 0; for (int i = 1; i < 6; i++) s += (i*i - 2*i); cout << s; Phương án nào dưới đây nêu đúng giá trị của s sau khi thực hiện đoạn chương trình trên?', '{"A": "49.", "B": "20", "C": "10", "D": "25"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c12', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Đoạn mã HTML nào sau đây là đúng để tạo ra một bảng đơn giản có một hàng chứa hai ô dữ liệu riêng biệt với nội dung lần lượt là "Tên" và "Nguyễn Văn A"?', '{"A": "<table><tr><td>Tên Nguyễn Văn A</td></tr></table>", "B": "<table><tr><td>Tên</td><td>Nguyễn Văn A</td></tr></table>", "C": "<table><tr><td>Tên</td></tr><tr><td>Nguyễn Văn A</td></tr></table>", "D": "<table><tr>Tên</tr><tr>Nguyễn Văn A</tr></table>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c13', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây là một nguy cơ rủi ro về an ninh, an toàn khi sử dụng AI?', '{"A": "AI dễ bị lỗi nếu không cập nhật phần mềm.", "B": "AI có thể đưa ra dự đoán sai nếu thiếu dữ liệu học tập.", "C": "AI có thể bị lợi dụng để đưa ra quyết định tấn công hoặc gây hại.", "D": "AI không thể tương tác bằng ngôn ngữ tự nhiên."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c14', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Hành vi nào dưới đây là biểu hiện của ứng xử nhân văn trên không gian mạng?', '{"A": "Lợi dụng mạng xã hội để trêu chọc, chế giễu người có hoàn cảnh đặc biệt.", "B": "Gửi tin nhắn mang tính xúc phạm khi không đồng tình với quan điểm người khác.", "C": "Bình luận tích cực, động viên người gặp khó khăn trên mạng xã hội.", "D": "Chia sẻ hình ảnh của người khác mà chưa có sự đồng ý."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c15', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Giao thức TCP trong bộ TCP/IP đảm nhận chức năng nào sau đây?', '{"A": "Mã hóa dữ liệu trước khi tiến hành truyền qua mạng.", "B": "Phân giải tên miền để tìm địa chỉ IP tương ứng. -- 3 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "C": "Cấp phát địa chỉ IP cho các thiết bị trong hệ thống mạng.", "D": "Đảm bảo dữ liệu được truyền chính xác, đúng thứ tự."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c16', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây được sử dụng để tạo một hàng trong bảng?', '{"A": "<th>", "B": "<table>", "C": "<tr>", "D": "<td>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c17', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Để kết nối 20 máy tính trong phòng máy thành một mạng LAN sao cho đảm bảo hiệu quả và tối ưu, phương án nào dưới đây là phù hợp nhất?', '{"A": "2 switch 10 cổng.", "B": "3 switch 8 cổng.", "C": "1 switch 24 cổng.", "D": "4 switch 5 cổng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c18', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây là nguyên nhân mà các thiết bị trong mạng có thể trao đổi dữ liệu với nhau khi sử dụng cùng một giao thức mạng?', '{"A": "Vì dữ liệu được mã hóa bằng cùng một phương pháp bảo mật đặc biệt.", "B": "Do dữ liệu được đóng gói và truyền theo một quy tắc chung đã được thỏa thuận.", "C": "Nhờ khả năng nhận dạng địa chỉ vật lý (MAC) giữa các thiết bị.", "D": "Bởi mạng sẽ cung cấp tốc độ truy cập Internet ổn định cho mọi thiết bị."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c19', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Phương án nào dưới đây mô tả đúng chức năng của đoạn mã HTML sau? Mật khẩu: <input type= “password” name= “Matkhau”>', '{"A": "Hiển thị dòng có nhãn Mật khẩu và ô password để người dùng nhập mật khẩu.", "B": "Hiển thị dòng có nhãn password và ô Matkhau để người dùng nhập mật khẩu.", "C": "Hiển thị dòng có nhãn password và ô Mật khẩu để người dùng nhập mật khẩu.", "D": "Hiển thị dòng có nhãn Matkhau và ô password để người dùng nhập mật khẩu."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c20', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Trong cuộc hội thảo với chủ đề “Nhân lực CNTT: Cơ hội và Thách thức”, một khách mời đã chia sẻ: “Trong thời đại hiện nay, có rất nhiều mối đe doạ từ tấn công mạng ngày càng tinh vi. Nhiệm vụ của các chuyên viên trong ngành này là phải đảm bảo dữ liệu và hệ thống khỏi các mối đe doạ đó”. Em hãy cho biết vị khách mời đang nhắc đến nhóm công việc nào dưới đây?', '{"A": "Phân tích, xử lí dữ liệu.", "B": "Bảo mật hệ thống thông tin.", "C": "Quản trị mạng.", "D": "Sửa chữa và bảo trì máy tính."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c21', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Thẻ HTML nào sau đây thường được dùng để tạo một vùng nhập liệu cho người dùng nhập văn bản nhiều dòng trong một biểu mẫu (form)? -- 4 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học', '{"A": "<input type=\"text\">", "B": "<button>", "C": "<input type=\"password\">", "D": "<textarea></textarea>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c22', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Phát biểu nào sau đây về liên kết trong trang web là đúng?', '{"A": "Nếu trong trang Web có sử dụng liên kết ngoài thì nên sử dụng đường dẫn tương đối.", "B": "Nếu trong trang web có sử dụng liên kết trong thì nên sử dụng đường dẫn tuyệt đối.", "C": "Hai phần trên cùng một trang web có thể được liên kết với nhau bởi một siêu liên kết.", "D": "Nên sử dụng đường dẫn trực tiếp vì luôn đảm bảo có thể truy cập từ bất cứ đâu."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c23', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Hệ thống nào sau đây thể hiện AI có khả năng học và suy luận dựa trên tri thức đã thu thập?', '{"A": "Ứng dụng gợi ý video ngày càng chính xác nhờ phân tích thói quen xem của người dùng.", "B": "Thiết bị báo thức thay đổi giờ chuông dựa trên lịch sử ngủ, theo các quy tắc cài đặt sẵn.", "C": "Trang web bán hàng trực tuyến luôn hiển thị danh mục sản phẩm giống nhau cho mọi người dùng.", "D": "Máy bán hàng tự động hoàn tiền nếu người dùng không nhận được sản phẩm sau khi thanh toán."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_05_p1_c24', 'de_on_luyen_05', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Phương án nào sau đây thể hiện khả năng cảm nhận và hiểu biết môi trường xung quanh của AI?', '{"A": "Khả năng học.", "B": "Khả năng nhận thức.", "C": "Khả năng suy luận.", "D": "Khả năng hiểu ngôn ngữ."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_05
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c1', 'de_on_luyen_05', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Để quản lý hoạt động mượn sách thư viện trong trường THPT, một cơ sở dữ liệu quan hệ được xây dựng với 3 bảng như sau: • SACH (Masach, Tensach, Tacgi', '[{"id": "a", "text": "lưu thông tin mã sách, Tên sách và tên Tác giả. • NGUOIDOC (Mathe, HotenHS, Lop) lưu thông tin Mã thẻ, họ tên học sinh và lớp của học sinh. • MUONSACH (Mathe, Masach, Ngaymuon, Ngaytra) lưu thông tin việc mượn sách, gồm: Mã thẻ, Mã sách, Ngày mượn và Ngày trả. Một học sinh có thể mượn nhiều sách và mỗi sách có thể được nhiều học sinh mượn vào những -- 5 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học thời điểm khác nhau. Khi tìm hiểu về cơ sở dữ liệu trên, một số bạn học sinh đưa ra các nhận xét sau: a) Câu lệnh SQL sau đây liệt kê họ tên học sinh và ngày mượn sách của những cuốn sách có mã sách là 1: SELECT NGUOIDOC.HotenHS, MUONSACH.Ngaymuon FROM MUONSACH INNER JOIN NGUOIDOC ON MUONSACH.Mathe = NGUOIDOC.Mathe WHERE SACH.Masach = 1;", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Trường Mathe là khoá ngoài của bảng NGUOIDOC.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Để liệt kê tên và lớp của các học sinh thuộc lớp 12B2, có thể dùng câu lệnh SQL sau: SELECT HotenHS, Lop FROM NGUOIDOC WHERE Lop = ''12B2'';", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Lop là một trường tương ứng với một cột của bảng NGUOIDOC.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c2', 'de_on_luyen_05', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một công ty nhỏ đã có Internet và đang sử dụng hệ thống mạng LAN với kết nối có dây giữa các máy tính thông qua Switch. Công ty muốn mở rộng mạng không dây kết nối vào Switch đã có cho một phòng họp, cho phép khách trong phòng họp truy cập Internet của công ty thông qua máy tính xách tay hoặc các thiết bị đi động. Người quản trị mạng đã đưa ra một số giải pháp sau:', '[{"id": "a", "text": "Tất cả các thiết bị trong mạng, kể cả có dây và không dây, phải kết nối trực tiếp với Modem mới có thể truy cập Internet.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Việc công ty muốn chia sẻ tài liệu đến khách hàng cần phải sử dụng dịch vụ lưu trữ đám mây từ bên ngoài.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Thiết lập mạng Wi-Fi cho khách sẽ không ảnh hưởng đến bảo mật của mạng LAN nội bộ.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Lắp đặt một Access Point và kết nối nó với Switch đã có để cung cấp mạng Wi-Fi riêng cho phòng họp và khách. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Định hướng Khoa học máy tính", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c3', 'de_on_luyen_05', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Trong đợt ủng hộ các tỉnh thành khu vực phía Bắc bị ảnh hưởng của bão Yagi, Trung ương Mặt trận tổ quốc Việt Nam đã công bố sao kê tiền ủng hộ thông qua tài khoản của các ngân hàng là một hình thức công khai, minh bạch về huy động các nguồn lực của nhân dân. Trong đó -- 6 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học công nghệ OCR (Optical Character Recognition -Nhận dạng ký tự quang học) là công nghệ giúp chuyển đổi hình ảnh chứa văn bản (như các tài liệu được quét, hình ảnh chụp từ sách, hóa đơn, sao kê) thành văn bản kỹ thuật số đã được áp dụng để tự động hóa quá trình xử lý sao kê ngân hàng. Một số bạn học sinh đưa ra các phát biểu sau:', '[{"id": "a", "text": "Học máy tích hợp vào OCR có thể được huấn luyện để phát hiện các mẫu giao dịch bất thường trong sao kê ngân hàng, từ đó giúp phát hiện gian lận tài chính.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "c) là công nghệ giúp chuyển đổi hình ảnh chứa văn bản (như các tài liệu được quét, hình ảnh chụp từ sách, hóa đơn, sao kê) thành văn bản kỹ thuật số đã được áp dụng để tự động hóa quá trình xử lý sao kê ngân hàng. Một số bạn học sinh đưa ra các phát biểu sau: a) Học máy tích hợp vào OCR có thể được huấn luyện để phát hiện các mẫu giao dịch bất thường trong sao kê ngân hàng, từ đó giúp phát hiện gian lận tài chính. b)", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "là công nghệ giúp chuyển đổi hình ảnh chứa văn bản (như các tài liệu được quét, hình ảnh chụp từ sách, hóa đơn, sao kê) thành văn bản kỹ thuật số đã được áp dụng để tự động hóa quá trình xử lý sao kê ngân hàng. Một số bạn học sinh đưa ra các phát biểu sau: a) Học máy tích hợp vào OCR có thể được huấn luyện để phát hiện các mẫu giao dịch bất thường trong sao kê ngân hàng, từ đó giúp phát hiện gian lận tài chính. b) OCR là công nghệ giúp nhận dạng và trích xuất thông tin từ sao kê ngân hàng bằng cách quét các tài liệu sao kê giấy hoặc ảnh chụp. c) Hệ thống OCR có thể tự động nhận diện chính xác thông tin từ mọi loại sao kê mà không cần được huấn luyện với dữ liệu mẫu từ các định dạng sao kê khác nhau.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Học máy chỉ có thể hoạt động trên các sao kê được in rõ ràng và không hoạt động được trên các sao kê có chất lượng hình ảnh thấp.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c4', 'de_on_luyen_05', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'Chọn một trong hai ngôn ngữ Python hoặc C++ đề tìm hiểu một hàm cho dưới đây Hàm viết bằng ngôn ngữ Python Hàm viết bằng ngôn ngữ C++ def find(x, a, n): found = False i = 0 while (i<n) and not found: if a[i] > x: found = True i = i + 1 return found bool find(int x, int a[], int n) { bool found = false; int i = 0; while (i<n && !found) { if (a[i] > x) found = true; i= i + 1; } return found; } Một số bạn học sinh nhận xét về hàm trên như sau:', '[{"id": "a", "text": "Hàm thể hiện một thuật toán đệ quy.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Nếu mảng a = {20, 6, 3, 8} và x = 9 thì hàm trả về giá trị logic sai.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "d) { if (a[i] > x) found = true; i= i + 1; } return found; } Một số bạn học sinh nhận xét về hàm trên như sau: a) Hàm thể hiện một thuật toán đệ quy. b) Nếu mảng a = {20, 6, 3, 8} và x = 9 thì hàm trả về giá trị logic sai. c)", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "{ if (a[i] > x) found = true; i= i + 1; } return found; } Một số bạn học sinh nhận xét về hàm trên như sau: a) Hàm thể hiện một thuật toán đệ quy. b) Nếu mảng a = {20, 6, 3, 8} và x = 9 thì hàm trả về giá trị logic sai. c) Hàm có độ phức tạp thuật toán là O(n). d) Các thao tác với mảng a trong hàm không phải là thao tác hàng đợi Định hướng Tin học ứng dụng", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c5', 'de_on_luyen_05', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Để hỗ trợ quản lý hoạt động bán hàng online, một cơ sở dữ liệu quan hệ được xây dựng với 4 bảng như sau: • SANPHAM (idSanpham, tenSanpham, Gianhap, Giaban, Soluong) lưu thông tin các sản phẩm được bán trên website: mã sản phẩm, tên sản phẩm, giá nhập, giá bán, và số lượng có trong kho. -- 7 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học • KHACHHANG (idKhachhang, Hoten, Diachi) lưu thông tin người mua hàng: mã khách hàng, họ tên, Địa chỉ. • DONHANG (idDonhang, idKhachhang, ngayDathang) lưu thông tin mỗi đơn hàng được đặt: mã đơn hàng, mã khách hàng, ngày đặt hàng. • CHITIETDONHANG (idSanpham, idDonhang, soLuongmu', '[{"id": "a", "text": "lưu chi tiết sản phẩm được đặt trong từng đơn hàng: Mã sản phẩm, Mã đơn hàng và số lượng mua. Một số bạn học sinh đưa ra các ý kiến về việc khai thác cơ sở dữ liệu trên như sau: a) Khi một đơn hàng được đặt thành công, ít nhất 3 bảng cần được cập nhật là: DONHANG, CHITIETDONHANG và SANPHAM.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Có thể có nhiều đơn hàng (DONHANG) khác nhau cùng có một idKhachhang.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Câu lệnh SQL sau liệt kê tên sản phẩm và số lượng mua trong các đơn hàng. SELECT SANPHAM.tenSanpham, CHITIETDONHANG.soLuongmua FROM CHITIETDONHANG INNER JOIN SANPHAM ON CHITIETDONHANG.idSanpham = SANPHAM.idSanpham;", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Bảng CHITIETDONHANG có thể chứa thông tin về một sản phẩm chưa có trong bảng SANPHAM.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_05_p2_c6', 'de_on_luyen_05', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Bình đang thực hiện một bài tập nhóm cùng một số học sinh khác trong lớp. Các bạn đã thực hiện họp trao đổi tại nhà của Bình và thực hiện kết nối máy tính xách tay với ti vi thông minh (được trang bị đầy đủ các chuẩn kết nối) để cả nhóm cùng trao đổi dễ dàng hơn. Sau đây là một số nhận xét về việc kết nối giữa hai thiết bị của các học sinh trong nhóm:', '[{"id": "a", "text": "Sau khi kết nối, âm thanh trên máy tính sẽ chỉ có thể phát ra từ ti vi thông minh.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Có thể thực hiện kết nối với ti vi thông minh mà không cần dùng dây kết nối.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Có thể thực hiện kết nối thông qua cổng USB trên ti vi thông minh.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Nếu hai thiết bị được kết nối thông qua Wi-fi từ Access Point, hình ảnh chiếu ở trên màn hình máy tính sẽ có hiện tượng đứng hình nếu tốc độ Wi-fi chậm. -- 8 of 17 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học II.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

-- ------------------------------------------------------------------------------
