-- Câu hỏi Phần I của de_on_luyen_08
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c1', 'de_on_luyen_08', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Trong các dự án phát triển phần mềm giáo dục, chuyên viên Công nghệ Thông tin cần thực hiện công việc nào sau đây để giúp phần mềm không ngừng hoàn thiện và mang lại hiệu quả sử dụng cao?', '{"A": "Phát triển phần mềm mà không cần phản hồi từ người dùng.", "B": "Phát triển theo chỉ đạo từ đơn vị quản lý giáo dục.", "C": "Dựa vào kinh nghiệm cá nhân để phát triển.", "D": "Dựa vào phản hồi của người dùng và cập nhật liên tục."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c2', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Để thiết lập tiêu đề hiển thị trên thanh tiêu đề của trình duyệt khi thiết kế một trang web, cần sử dụng thẻ HTML nào sau đây?', '{"A": "<h1> Tiêu đề trang web </h1> đặt trong thẻ <body>", "B": "<title> Tiêu đề trang web </title> đặt trong thẻ <head>", "C": "<meta title=\"Tiêu đề trang web\"> đặt trong thẻ <head>", "D": "<header> Tiêu đề trang web </header> đặt trong thẻ <head>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c3', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Yếu tố nào sau đây là cần thiết để đảm bảo việc giao tiếp hiệu quả và chính xác giữa các máy tính và thiết bị trong một mạng?', '{"A": "Giao dịch mạng (Network transactions).", "B": "Giao thức mạng (Network protocol).", "C": "Giao thông mạng (Network traffic).", "D": "Giao tiếp mạng (Network communication)."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c4', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Cấu trúc cơ bản của một trang web HTML bao gồm các phần tử nào sau đây?', '{"A": "<html>, <head>, <body>", "B": "<div>, <span>, <table>", "C": "<title>, <link>, <meta>", "D": "<header>, <footer>, <article>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c5', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Trong HTML, thẻ nào dưới đây được sử dụng để tạo tiêu đề nhỏ nhất?', '{"A": "<p>", "B": "<h4>", "C": "<h6>", "D": "<h1> -- 1 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c6', 'de_on_luyen_08', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo (AI) khi thu thập và xử lý thông tin cá nhân có thể gây ảnh hưởng đến quyền riêng tư của người dùng theo cách nào dưới đây?', '{"A": "Cải thiện giao tiếp giữa các thiết bị.", "B": "Tăng cường bảo mật dữ liệu.", "C": "Tối ưu hóa quy trình sản xuất.", "D": "Gây ra tình trạng thu thập và lạm dụng dữ liệu cá nhân."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c7', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong mạng máy tính, giao thức IP thực hiện chức năng quan trọng nào dưới đây?', '{"A": "Phương án A", "B": "Phương án B", "C": "Phương án C", "D": "Phương án D"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c8', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Cách nào sau đây có thể giúp bạn xử lý tình huống khó xử trong không gian mạng một cách hiệu quả?', '{"A": "Học cách xử lý chúng một cách đúng mực.", "B": "Tránh mọi tình huống khó xử.", "C": "Gửi tin nhắn tức giận mỗi khi gặp khó khăn.", "D": "Bỏ qua vấn đề và không giải quyết."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c9', 'de_on_luyen_08', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Viết bằng ngôn ngữ Python Viết bằng ngôn ngữ C++ S = 0 for i in range(1, 100): if (i % 4 == 0) and (i % 7 == 0): S += i print(S) int S = 0; for (int i = 1; i < 100; i++) if ((i % 4 == 0) && (i % 7 == 0)) S += i; cout << S; Phương án nào sau đây nêu đúng giá trị của biến S sau khi thực hiện đoạn chương trình trên?', '{"A": "164.", "B": "168.", "C": "170.", "D": "166."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c10', 'de_on_luyen_08', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'biet', 'ALL', 'Trong trường hợp máy tính không thể kết nối với Internet, phương án nào dưới đây KHÔNG phải là một bước xử lý thông thường mà một kỹ thuật viên Công nghệ Thông tin nên thực hiện?', '{"A": "Kiểm tra kết nối mạng.", "B": "Cài đặt lại hệ điều hành.", "C": "Kiểm tra cài đặt IP.", "D": "Liên hệ với nhà cung cấp dịch vụ mạng."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c11', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong các thiết bị mạng sau đây, thiết bị nào có chức năng xác định cổng kết nối và thiết lập kênh truyền tạm thời để truyền dữ liệu giữa hai thiết bị trong mạng cục bộ (LAN)? -- 2 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học', '{"A": "Hub.", "B": "Modem.", "C": "Switch.", "D": "Router."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c12', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Để bảo vệ và gìn giữ tính nhân văn trong không gian mạng, hành động nào sau đây là cần thiết nhất đối với người dùng?', '{"A": "Tham gia vào các cuộc tranh luận mà không cân nhắc đến ý kiến của đối phương.", "B": "Tránh giao tiếp với những người có quan điểm trái ngược.", "C": "Nhận thức và tôn trọng sự đa dạng trong quan điểm của người khác.", "D": "Chỉ chia sẻ những thông tin mà bản thân cho là đúng mà không kiểm tra tính xác thực."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c13', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Trong CSS, cú pháp nào dưới đây được sử dụng để khai báo một phần tử hiển thị theo dạng khối?', '{"A": "display: list-item;", "B": "display: inline;", "C": "display: block;", "D": "display: none;"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
