INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c15', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Khi muốn gộp hai ô tiêu đề "Sản phẩm" và "Loại hàng" thành một ô duy nhất ở hàng tiêu đề trên cùng của bảng, sử dụng đoạn mã HTML nào sau đây?', '{"A": "<th rowspan=\"2\">Sản phẩm - Loại hàng</th>", "B": "<th colspan=\"2\">Sản phẩm - Loại hàng</th>", "C": "<td merge=\"2\">Sản phẩm - Loại hàng</td>", "D": "<tr colspan=\"2\"><th>Sản phẩm - Loại hàng</th></tr>"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c16', 'de_on_luyen_08', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Lĩnh vực nào của trí tuệ nhân tạo (AI) chuyên xử lý các tác vụ liên quan đến việc thu nhận, phân tích và nhận dạng hình ảnh từ thế giới thực?', '{"A": "AI tạo sinh.", "B": "Xử lý ngôn ngữ tự nhiên.", "C": "Thị giác máy tính.", "D": "Học máy."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c17', 'de_on_luyen_08', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Trong quy trình phát triển phần mềm, mỗi thành viên đều đảm nhận một vai trò cụ thể để đảm bảo sản phẩm đạt chất lượng cao nhất. Vậy ai là người chịu trách nhiệm chính trong việc kiểm tra và phát hiện lỗi của phần mềm trước khi được đưa vào sử dụng?', '{"A": "Quản lý dự án phát triển phần mềm.", "B": "Thiết kế giao diện người dùng.", "C": "Viết mã nguồn cho phần mềm.", "D": "Chạy thử phần mềm để tìm lỗi."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c18', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Trong thiết kế trang web, CSS đóng vai trò quan trọng trong việc nào sau đây?', '{"A": "Tinh chỉnh giao diện và kiểu dáng cho trang web. -- 3 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "B": "Lưu trữ và quản lý dữ liệu người dùng.", "C": "Cải thiện hiệu suất tải trang web.", "D": "Định nghĩa cấu trúc HTML cho trang web."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
