INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c21', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Khi gặp phải ý kiến trái chiều trong không gian mạng, hành động nào sau đây thể hiện ứng xử văn minh và tôn trọng nhất?', '{"A": "Phương án A", "B": "Phương án B", "C": "Phương án C", "D": "Phương án D"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c22', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Thẻ <head> trong cấu trúc trang HTML có vai trò quan trọng nào sau đây trong việc tổ chức thông tin trang web?', '{"A": "Cung cấp thông tin meta, tiêu đề và liên kết đến các tài nguyên bên ngoài.", "B": "Quản lý định dạng của văn bản và hình ảnh trong trang.", "C": "Chứa nội dung chính mà người dùng thấy trên trang.", "D": "Tạo ra các phần tử tương tác như biểu mẫu và nút bấm."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
