INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_08_p1_c24', 'de_on_luyen_08', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Trong các khả năng sau đây, đâu là đặc điểm nổi bật giúp trí tuệ nhân tạo (AI) vượt trội hơn con người trong một số lĩnh vực ứng dụng?', '{"A": "Làm việc liên tục không nghỉ.", "B": "Hiểu và đồng cảm.", "C": "Phân tích thông tin nhanh.", "D": "Sáng tạo và đổi mới."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_08
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c1', 'de_on_luyen_08', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Một trung tâm đào tạo nghề có 20 máy tính dành cho học viên và 3 máy tính dành cho giảng viên. Hệ thống mạng tại trung tâm được thiết lập để kết nối tất cả các máy tính, phục vụ cho việc giảng dạy và học tập. Các thiết bị mạng đang sử dụng gồm: 1 Switch 24 cổng, 1 Router với 1 cổng WAN và 2 cổng LAN; cùng với các dây cáp mạng cần thiết. Xem xét các nhận định sau và cho biết chúng đúng hay sai:', '[{"id": "a", "text": "Switch được sử dụng để nhận diện địa chỉ IP và định tuyến dữ liệu giữa các máy tính.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Router có khả năng kết nối mạng nội bộ với Internet và phân phối địa chỉ IP cho các thiết bị trong mạng.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Tất cả các máy tính của học viên sẽ được kết nối vào Switch để truy cập mạng nội bộ.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Để mở rộng khả năng kết nối không dây cho học viên sử dụng thiết bị di động, trung tâm cần mua thêm một Access Point và kết nối vào Switch hoặc Router.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c2', 'de_on_luyen_08', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một trường cao đẳng thiết lập hệ thống quản lý thư viện bằng cơ sở dữ liệu quan hệ với ba bảng chính: 1. SACH (MaSach, TenSach, TacGia, NamXB, TheLoai, SoLuong): Lưu thông tin về sách, bao gồm mã sách, tên, tác giả, năm xuất bản, thể loại và số lượng tồn kho. 2. SINHVIEN (MaSV, TenSV, Kho', '[{"id": "a", "text": ": Lưu trữ thông tin về sinh viên, gồm mã số, tên và khoa học. 3. MUONTRA (MaSV, MaSach, NgayMuon, NgayTra, SoLuong): Theo dõi các giao dịch mượn sách, bao gồm mã sinh viên, mã sách, ngày mượn, ngày trả và số lượng. Hệ thống này giúp thư viện quản lý và theo dõi sách hiệu quả, đồng thời cải thiện khả năng phục vụ sinh viên trong việc tiếp cận tài liệu học tập. Một sinh viên nhận định như sau: a) Bảng SACH gồm 6 trường dữ liệu.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Bảng SACH và bảng SINHVIEN có quan hệ với nhau qua khóa ngoại MaSV.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "MaSV là khóa chính trong bảng MUONTRA.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Hiển thị thông tin sách có số lượng tồn kho bằng 0 bằng lệnh truy vấn: SELECT * FROM SACH WHERE SoLuong = 0; Phần riêng Định hướng Khoa học máy tính", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c3', 'de_on_luyen_08', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Hà đang thực hiện một bài tập lập trình trong một khóa học. Cô viết một hàm để tính tổng các số chẵn trong một danh sách các số nguyên. Dưới đây là mã nguồn của hàm: Viết bằng ngôn ngữ Python Viết bằng ngôn ngữ bằng C++ -- 5 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học def sum_even(numbers): total = 0 for num in numbers: if num % 2 == 0: total += num return total int sum_even(vector<int>& numbers) { int total = 0; for (int num : numbers) if (num % 2 == 0) total += num; return total; } Một số bạn học sinh đưa ra các nhận xét sau:', '[{"id": "a", "text": "Hàm trên thể hiện một thuật toán tính tổng các số chẵn trong danh sách các số nguyên.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Hàm tính tổng các số chẵn trong danh sách có độ phức tạp thời gian là O(n)", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Hàm trên chỉ tính tổng các số âm trong danh sách.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Nếu mảng numbers = [1, 2, 3, 4, 5] thì hàm sẽ trả về 10.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c4', 'de_on_luyen_08', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'Trong một cuộc thảo luận về việc ứng dụng học máy trong lĩnh vực y tế, cụ thể là hỗ trợ bác sĩ chẩn đoán bệnh thông qua hình ảnh y tế như MRI, CT scan và X-quang. Các chuyên gia trong lĩnh vực công nghệ và y khoa tham gia đã đưa ra những nhận xét đa chiều về khả năng và những thách thức liên quan đến việc sử dụng học máy trong việc chẩn đoán bệnh. Một số người có nhận xét như sau:', '[{"id": "a", "text": "Học máy có khả năng phân tích hình ảnh y tế để giúp bác sĩ phát hiện các dấu hiệu bệnh.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Học máy chỉ làm việc với dữ liệu hình ảnh và không thể sử dụng dữ liệu từ các nguồn khác như báo cáo y tế hoặc thông tin văn bản.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Học máy có thể cải thiện độ chính xác trong chẩn đoán bệnh bằng cách học từ dữ liệu hình ảnh và bệnh án lịch sử.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Việc ứng dụng học máy trong chẩn đoán bệnh thông qua hình ảnh y tế có thể giúp bác sĩ đưa ra quyết định nhanh chóng, nhưng không phải lúc nào cũng đảm bảo chính xác 100%.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c5', 'de_on_luyen_08', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Trong một khóa học về công nghệ thông tin, các sinh viên được hướng dẫn thực hành sử dụng phần mềm tạo trang web để thiết kế một trang web cá nhân. Mỗi sinh viên sẽ tạo cho mình một trang web đơn giản giới thiệu về sở thích, kỹ năng và các dự án của mình. Trong buổi thực hành, các sinh viên đã thảo luận, chia sẻ ý kiến về quy trình thiết kế và những thách thức mà họ gặp phải. Một số ý kiến như sau:', '[{"id": "a", "text": "Phần mềm tạo trang web cung cấp các mẫu và giao diện người dùng thân thiện, giúp sinh viên dễ dàng tạo ra trang web mà không cần kiến thức lập trình.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Sinh viên không cần quan tâm đến kích thước hình ảnh khi chèn vào trang web, vì phần mềm sẽ tự động điều chỉnh kích thước cho phù hợp.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Sinh viên không cần phải kiểm tra tính tương thích của trang web với các trình duyệt khác nhau vì phần mềm tự động đảm bảo điều này. -- 6 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Để tạo trải nghiệm người dùng tốt hơn, sinh viên nên chú ý đến cách bố trí nội dung và tính điều hướng của trang web.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_08_p2_c6', 'de_on_luyen_08', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Trong một khóa học về cơ sở dữ liệu, sinh viên được giao nhiệm vụ thực hành tạo và khai thác một cơ sở dữ liệu dùng để quản lý thông tin sinh viên và điểm số của họ. Sinh viên sử dụng hệ quản trị cơ sở dữ liệu phổ biến như MySQL hoặc PostgreSQL để thiết kế bảng, nhập dữ liệu và thực hiện truy vấn nhằm rút ra thông tin cần thiết. Cơ sở dữ liệu bao gồm hai bảng chính: 1. SINHVIEN (MaSV, TenSV, Lop) 2. DIEM (MaSV, MonHoc, Diem) Sinh viên cần thực hiện các thao tác như tạo bảng, thêm dữ liệu, và viết các truy vấn SQL để lấy thông tin về điểm số sinh viên theo từng môn học. Các nhận xét từ sinh viên:', '[{"id": "a", "text": "Cơ sở dữ liệu giúp lưu trữ và quản lý thông tin một cách hiệu quả hơn so với việc lưu trữ trong file văn bản.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Trong bảng SINHVIEN, MaSV là một trường không bắt buộc và có thể để trống.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Việc viết truy vấn JOIN có thể giúp kết hợp dữ liệu từ bảng SINHVIEN và bảng DIEM để lấy thông tin điểm số của sinh viên theo lớp học.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Sinh viên có thể viết truy vấn để tính trung bình điểm của từng sinh viên trong bảng DIEM và kết hợp kết quả với thông tin cá nhân từ bảng SINHVIEN để tạo ra báo cáo tổng hợp. ----------- HẾT - --------- -- 7 of 14 -- Sưu tầm bởi nhóm tác giả sách giải mã kiến thức Tốt nghiệp Trung Học Phổ Thông môn Tin Học", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

