-- Câu hỏi Phần I của de_on_luyen_10
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c1', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Đặc điểm nào sau đây của trí tuệ nhân tạo là hạn chế?', '{"A": "Không bao giờ mắc phải lỗi sai sót.", "B": "Tự hiểu mọi ngôn ngữ mà không học.", "C": "Phụ thuộc chất lượng dữ liệu huấn luyện.", "D": "Thể hiện cảm xúc như người."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c2', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây phản ánh đúng ưu điểm của AI?', '{"A": "Thực hiện công việc lặp lại rất nhanh.", "B": "Luôn luôn hoạt động mà không sai sót.", "C": "Thay thế con người hoàn toàn trong mọi việc?", "D": "Chỉ có thể sử dụng khi có mạng Internet."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c3', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phát biểu nào sau đây đúng về hệ thống nhận diện khuôn mặt?', '{"A": "Chỉ hoạt động với người đeo khẩu trang.", "B": "Không thể phân biệt các khuôn mặt khác.", "C": "Có thể nhận diện trong nhiều điều kiện.", "D": "Chỉ nhận diện khi người đứng yên yên."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c4', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'AI trong trợ lí ảo như Siri hay Google Assistant có chức năng nào?', '{"A": "Tính toán tốc độ kết nối mạng Internet.", "B": "Chỉ phát nhạc theo danh sách có sẵn.", "C": "Hiểu và trả lời câu hỏi bằng giọng nói.", "D": "Thay thế chức năng của camera điện thoại."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c5', 'de_on_luyen_10', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Cho chương trình sau: Python C++ a = [1, 2, 3, 4, 5] a.reverse() for x in a: print(x,end=" ") #include <iostream> #include <algorithm> using namespace std; int main() { int a[] = {1, 2, 3, 4, 5}; reverse(a, a + 5); for (int i = 0; i < 5; i++) cout << a[i] << " "; return 0; } Đáp án nào sau đây là kết quả xuất ra màn hình của chương trình trên?', '{"A": "12345", "B": "[5,4,3,2,1]", "C": "5 4 3 2 1", "D": "[1,2,3,4,5]"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c6', 'de_on_luyen_10', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Một học sinh kết nối máy tính với mạng LAN bằng cáp mạng nhưng không truy cập được Internet. Nguyên nhân nào dưới đây hợp lí nhất?', '{"A": "Cáp mạng bị đứt hoàn toàn.", "B": "Thiết bị chưa cấp quyền truy cập mạng Wi-Fi.", "C": "Máy tính chưa được cấp địa chỉ IP hợp lệ.", "D": "Trình duyệt bị lỗi."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c7', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Nguyên nhân nào sau đây có thể khiến tín hiệu Wi-Fi yếu đi?', '{"A": "Sử dụng cáp mạng đạt chuẩn.", "B": "Có nhiều vật cản giữa thiết bị và Modem.", "C": "Sử dụng mật khẩu quá dài.", "D": "Bật chế độ máy bay."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
