INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_10_p1_c24', 'de_on_luyen_10', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'van_dung', 'ALL', 'Giả sử bạn muốn biểu mẫu có các khung nhập liệu cách đều nhau theo chiều dọc, thuộc tính nào sau đây nên sử dụng?', '{"A": "line-height", "B": "padding", "C": "margin-bottom", "D": "vertical-align Phần II. Trắc nghiệm dạng đúng sai (4 điểm): Thí sinh trả lời 4 câu hỏi cho phần thi tương ứng: Mỗi câu hỏi thí sinh tô vào ô tương ứng với đúng hoặc sai đối với mỗi ý trong từng câu hỏi của đề. A. Phần chung cho tất cả các thí sinh Câu 1. Một nhóm học sinh tổ chức hoạt động chia sẻ dữ liệu giữa các máy tính trong cùng một lớp học thông qua kết nối mạng LAN nội bộ. Tuy nhiên, một vài máy không thể truy cập vào thư mục chia sẻ của các máy khác. Các bạn cần xác định nguyên nhân và cách khắc phục. Một số ý kiến như sau: a) Mạng LAN chỉ hoạt động nếu có kết nối Internet. b) Có thể một số máy đã tắt chức năng chia sẻ trong cài đặt mạng. c) Cần kiểm tra nhóm mạng (Workgroup) hoặc địa chỉ IP của các máy. d) Giải pháp đầu tiên nên làm là cài lại hệ điều hành cho các máy bị lỗi để khắc phục. Câu 2. Tổ học sinh A muốn lưu trữ thông tin khảo sát sở thích học tập bằng Google Forms. Sau khi thu thập, nhóm xuất dữ liệu ra bảng tính và thảo luận cách lưu trữ, phân tích kết quả theo từng lớp. Một bạn đề xuất dùng cơ sở dữ liệu để dễ truy vấn, thống kê và bảo mật dữ liệu hơn. Một số ý kiến như sau: a) Google Forms là hệ cơ sở dữ liệu dùng để xử lí thống kê. b) Một cơ sở dữ liệu có thể được tạo ra từ nguồn dữ liệu khảo sát. c) Dữ liệu thu thập từ biểu mẫu có thể nhập vào các hệ quản trị cơ sở dữ liệu để truy vấn. d) Sử dụng hệ cơ sở dữ liệu giúp dễ dàng tìm học sinh có cùng sở thích từ nhiều lớp. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho chương trình sau: Python C++ def isBalanced(expr): stack = [] for ch in expr: if ch == ''('': stack.append(ch) elif ch == '')'': if not stack: return False stack.pop() return len(stack) == 0 bool isBalanced(string expr) { stack<char> s; for (char ch : expr) { if (ch == ''('') s.push(ch); else if (ch == '')'') { if (s.empty()) return false; s.pop(); } } return s.empty(); } Một số ý kiến như sau: a) Nếu biểu thức có số dấu ''('' và '')'' bằng nhau, hàm trả về True. b) Ngăn xếp được dùng để lưu dấu ''('' khi gặp. c) Khi gặp dấu '')'', nếu ngăn xếp rỗng, biểu thức không cân bằng. d) Hàm trả về False nếu tất cả dấu ngoặc đã được đóng đúng thứ tự. Câu 4. Ứng dụng Facebook có tích hợp Trí tuệ nhân tạo, học máy để thu thập dữ liệu khách hàng. Ngay cả khi một người sử dụng nhiều tài khoản để đăng nhập và sử dụng thì Facebook có thể hợp nhất dữ liệu liên quan đến người dùng đó, từ đó đưa ra các mẫu quảng cáo, các nội dung phù hợp với từng nhóm người dùng: Với vấn đề nêu trên, một số học sinh đưa ra các ý kiến như sau về Facebook: a. Facebook sử dụng trí tuệ nhân tạo và học máy để phân tích hành vi người dùng nhằm cá nhân hóa nội dung hiển thị. b. Khoa học dữ liệu là nền tảng quan trọng giúp Facebook khai thác và hiểu sâu về thói quen người dùng. c. Khi dùng Facebook trên cùng một thiết bị, một người dùng tạo hai tài khoản hoàn toàn khác nhau (sdt, email,…) thì ứng dụng KHÔNG thể phát hiện 2 tài khoản này của cùng 1 người. d. Có thể biết được giới tính hoặc ước tính độ tuổi khi người dùng cung cấp ảnh chân dung của họ. Câu 5. Nhóm bạn Mai sử dụng phần mềm thiết kế web để tạo trang giới thiệu câu lạc bộ học thuật. Nhóm dùng công cụ tạo danh sách để liệt kê hoạt động, công cụ tạo bảng để thể hiện lịch sinh hoạt và khung nội dung để hiển thị video minh họa. Một số ý kiến như sau: a) Danh sách và bảng là hai thành phần thường được dùng để tổ chức nội dung. b) Tạo danh sách trong phần mềm web yêu cầu viết mã HTML phức tạp. c) Bảng có thể dùng để hiển thị thông tin theo hàng và cột rõ ràng. d) Trong khung nội dung không thể nhúng video hoặc trang web khác vào trang chính. Câu 6. Lan đang làm việc với cơ sở dữ liệu quản lý bán hàng, trong đó có hai bảng: • HoaDon gồm các trường chính: MaHD (Mã hóa đơn), NgayLap (Ngày lập hóa đơn), MaKH (Mã khách hàng), TongTien (Tổng tiền của hóa đơn) • ChiTietHD gồm các trường: MaHD (Mã hóa đơn), MaSP (Mã sản phẩm), SoLuong (Số lượng sản phẩm trong hóa đơn), DonGia (Đơn giá của sản phẩm) Lan cần tìm các sản phẩm được khách hàng đặt mua trong ít nhất 6 hóa đơn khác nhau. Lan viết câu lệnh truy vấn: SELECT MaSP, COUNT(MaHD) AS SoLanDat FROM ChiTietHD GROUP BY MaSP HAVING COUNT(MaHD) > 5; Một số ý kiến như sau: a) Khi tạo bảng ChiTietHD cần tạo khóa ngoài MaHD liên kết đến bảng HoaDon. b) Mệnh đề HAVING lọc các sản phẩm có số lần đặt nhiều hơn 5. c) Có thể không cần dùng GROUP BY vẫn giữ nguyên ý nghĩa câu truy vấn. d) Nếu muốn giới hạn truy vấn chỉ xét các hóa đơn trong năm 2024, có thể bổ sung điều kiện lọc ở mệnh đề WHERE như sau: SELECT MaSP, COUNT(MaHD) AS SoLanDat FROM ChiTietHD WHERE YEAR(HoaDon.NgayLap) = 2024 GROUP BY MaSP HAVING COUNT(MaHD) > 5; ---Hết--- ĐÁP ÁN Phần I. Câu 1. Đặc điểm nào sau đây của trí tuệ nhân tạo là hạn chế? A. Sai. Đây không phải là một hạn chế mà là một mô tả không đúng về AI. Trí tuệ nhân tạo vẫn có thể mắc lỗi, nhất là khi dữ liệu không chính xác hoặc thuật toán chưa hoàn thiện. B. Sai. Đây là một kỳ vọng phi thực tế. AI cần được huấn luyện với dữ liệu ngôn ngữ cụ thể để hiểu và xử lý. C. Đúng. Đây là một hạn chế thực tế: nếu dữ liệu huấn luyện sai lệch hoặc không đầy đủ, AI sẽ cho kết quả kém chất lượng. D. Sai. Đây không phải là hạn chế, mà là điều AI không có khả năng thực hiện, vì AI không có cảm xúc thực sự. Câu 2. Phương án nào sau đây phản ánh đúng ưu điểm của AI? A. Đúng. AI có thể thực hiện các công việc lặp lại rất nhanh và hiệu quả. B. Sai. AI vẫn có thể mắc sai sót, nhất là khi dữ liệu đầu vào không đầy đủ hoặc sai lệch. C. Sai. AI không thể thay thế con người hoàn toàn trong mọi việc, đặc biệt là những công việc đòi hỏi tư duy sáng tạo, đạo đức hoặc cảm xúc. D. Sai. AI có thể hoạt động ngoại tuyến, không nhất thiết phải có kết nối Internet (ví dụ: AI tích hợp trong thiết bị di động, phần mềm cục bộ) Câu 3. Phát biểu nào sau đây đúng về hệ thống nhận diện khuôn mặt? A. Sai. Hệ thống không chỉ hoạt động với người đeo khẩu trang mà còn nhận diện bình thường khi không đeo. B. Sai. Hệ thống có thể phân biệt nhiều khuôn mặt khác nhau. C. Đúng. Hệ thống nhận diện khuôn mặt có thể hoạt động trong nhiều điều kiện khác nhau như ánh sáng khác nhau, góc nhìn đa dạng. D. Sai. Không chỉ nhận diện khi người đứng yên, nhiều hệ thống còn nhận diện khi người di chuyển. Câu 4. AI trong trợ lí ảo như Siri hay Google Assistant có chức năng nào? A. Sai. Việc tính toán tốc độ kết nối mạng là chức năng của hệ điều hành hoặc phần mềm đo tốc độ, không phải đặc trưng của AI trợ lí ảo. B. Sai. Trợ lí ảo không chỉ phát nhạc theo danh sách có sẵn mà còn có thể tìm kiếm, đề xuất và điều khiển bằng lệnh giọng nói. C. Đúng. Trợ lí ảo có khả năng hiểu và trả lời câu hỏi bằng giọng nói. D. Sai. Camera có chức năng riêng, trợ lí ảo không thay thế mà có thể điều khiển một số chức năng của camera. Câu 5. Đáp án nào sau đây là kết quả xuất ra màn hình của chương trình trên? A. Sai. Kết quả không phải là chuỗi 12345 liền nhau. B. Sai. Kết quả không có dấu ngoặc vuông như một mảng. C. Đúng. Kết quả là chuỗi số in ra theo thứ tự ngược: 5 4 3 2 1, cách nhau bằng dấu cách. D. Sai. Kết quả không phải là dãy số theo thứ tự ban đầu. Câu 6. Một học sinh kết nối máy tính với mạng LAN bằng cáp mạng nhưng không truy cập được Internet. Nguyên nhân nào dưới đây hợp lí nhất? A. Sai. Nếu cáp mạng bị đứt hoàn toàn, máy tính sẽ không kết nối được mạng LAN. B. Sai. Câu hỏi đề cập kết nối LAN, không phải Wi-Fi. C. Đúng. Nếu máy tính chưa được cấp địa chỉ IP hợp lệ, nó có thể kết nối cục bộ (LAN) nhưng không truy cập được Internet. D. Sai. Trình duyệt lỗi không ảnh hưởng đến kết nối mạng ở mức này. Câu 7. Nguyên nhân nào sau đây thường gây yếu tín hiệu Wi-Fi? A. Sai. Sử dụng cáp mạng đạt chuẩn không gây yếu tín hiệu Wi-Fi. B. Đúng. Nhiều vật cản giữa thiết bị và modem làm suy giảm tín hiệu Wi-Fi. C. Sai. Mật khẩu dài không ảnh hưởng tới chất lượng tín hiệu. D. Sai. Bật chế độ máy bay làm mất toàn bộ kết nối, không phải yếu tín hiệu. Câu 8. Phương án nào sau đây là ưu điểm của mạng không dây? A. Đúng. Mạng không dây cho phép giữ kết nối khi di chuyển thiết bị dễ dàng. B. Sai. Tốc độ mạng có dây thường nhanh và ổn định hơn mạng không dây. C. Sai. Mạng không dây vẫn cần router để phát sóng. D. Sai. Mạng không dây cần bảo mật để tránh truy cập trái phép. Câu 9. Phương án nào sau đây mô tả đúng chức năng của Mobile Hotspot? A. Sai. Phát nhạc và video không dây không phải là chức năng của Mobile Hotspot mà thuộc về các ứng dụng media hoặc kết nối Bluetooth, DLNA. B. Sai. Mở khóa thiết bị từ xa qua mạng thuộc về chức năng quản lý từ xa, không liên quan đến Mobile Hotspot. C. Đúng. Mobile Hotspot cho phép thiết bị (thường là điện thoại) chia sẻ kết nối Internet (Wi-Fi, 4G...) cho các thiết bị khác bằng cách tạo một điểm truy cập Wi-Fi. D. Sai. Lưu trữ dữ liệu đám mây cá nhân liên quan đến dịch vụ như Google Drive, iCloud…, không phải Mobile Hotspot. Câu 10. Giao tiếp có tính nhân văn trong không gian mạng không bao gồm hành vi nào sau đây? A. Sai. Tôn trọng sự khác biệt là biểu hiện của giao tiếp nhân văn. B. Sai. Đồng cảm với người gặp khó khăn cũng là hành vi nhân văn. C. Đúng. Kích động thù ghét giữa các nhóm là hành vi không nhân văn. D. Sai. Khuyến khích hỗ trợ cộng đồng thể hiện tính nhân văn. Câu 11. Thể hiện nào sau đây đúng trách nhiệm của cá nhân khi tham gia diễn đàn học tập trực tuyến? A. Sai. Không nên thể hiện quan điểm cá nhân bằng mọi cách mà cần tôn trọng và lịch sự. B. Sai. Bình luận bằng biểu tượng có thể không đủ để truyền đạt ý kiến rõ ràng. C. Đúng. Trả lời có lí lẽ và tôn trọng bạn học, giáo viên là trách nhiệm đúng. D. Sai. Tranh luận xây dựng, có văn hóa giúp làm rõ quan điểm, không nên tránh hoàn toàn. Câu 12. Người có trách nhiệm ứng xử nhân văn khi giao tiếp trên mạng cần thể hiện điều nào sau đây? A. Sai. Đáp trả lời xúc phạm chỉ làm tăng xung đột, không phản ánh thái độ nhân văn. B. Sai. Chia sẻ nội dung mà không quan tâm đến người khác có thể gây hiểu lầm, tổn thương hoặc vi phạm chuẩn mực. C. Đúng. Biết lắng nghe, thấu hiểu và ứng xử đúng mực là biểu hiện của sự tôn trọng và trách nhiệm khi giao tiếp trực tuyến. D. Sai. Tránh tất cả các cuộc trò chuyện mạng không giải quyết vấn đề và không phản ánh hành vi giao tiếp tích cực. Câu 13. Trong nhóm nghề CNTT, kỹ thuật viên phần cứng có nhiệm vụ nào sau đây? A. Đúng. Kỹ thuật viên phần cứng đảm nhiệm việc lắp ráp, sửa chữa và bảo trì thiết bị máy tính. B. Sai. Thiết kế giao diện website và trải nghiệm người dùng thuộc về lĩnh vực thiết kế web, không phải phần cứng. C. Sai. Soạn thảo hợp đồng và quản lý hồ sơ là công việc hành chính, không thuộc nghề CNTT. D. Sai. Hỗ trợ người dùng cài đặt phần mềm qua điện thoại là nhiệm vụ của kỹ thuật viên phần mềm hoặc hỗ trợ kỹ thuật. Câu 14. Nghề nào sau đây thuộc nhóm nghề quản trị trong CNTT? A. Đúng. Quản lý dự án CNTT là công việc điển hình của nhóm nghề quản trị, phụ trách lập kế hoạch, giám sát và triển khai dự án CNTT. B. Sai. Kỹ thuật viên lắp ráp máy tính thuộc nhóm kỹ thuật phần cứng, không thuộc quản trị. C. Sai. Lập trình viên phát triển ứng dụng di động thuộc nhóm phát triển phần mềm, không phải quản trị. D. Sai. Nhân viên nhập liệu là công việc văn phòng phổ thông, không thuộc nhóm quản trị CNTT. Câu 15. Kỹ năng nào sau đây cần thiết cho người làm nghề dịch vụ và quản trị CNTT? A. Đúng. Quản lý và giao tiếp hiệu quả là kỹ năng thiết yếu để điều phối công việc, làm việc nhóm và hỗ trợ khách hàng. B. Sai. Làm vườn và chăm sóc động vật không liên quan đến CNTT. C. Sai. Cắt may và thiết kế thời trang là kỹ năng thuộc ngành thời trang. D. Sai. Nấu ăn và pha chế đồ uống thuộc ngành dịch vụ ăn uống, không liên quan đến CNTT. Câu 16. Cặp thẻ nào sau đây được dùng để tạo bảng trong thiết kế trang Web? A. Đúng. <table>…</table> là cặp thẻ chính dùng để tạo bảng trong HTML. B. Sai. <ol>…</ol> là thẻ tạo danh sách có thứ tự (ordered list), không phải bảng. C. Sai. <tr>…</tr> là thẻ tạo dòng trong bảng, nhưng không đủ để tạo bảng mà phải nằm trong <table>. D. Sai. <ul>…</ul> là danh sách không thứ tự (unordered list), không dùng cho bảng. Câu 17. Trong HTML, thẻ nào sau đây được sử dụng để đánh dấu xóa bằng nét gạch giữa chữ? A. Sai. <strong> dùng để in đậm văn bản, không phải để gạch ngang. B. Sai. <u> dùng để gạch dưới, không phải gạch ngang chữ. C. Đúng. <del> dùng để đánh dấu văn bản bị xóa, thể hiện bằng nét gạch ngang giữa chữ. D. Sai. <mark> dùng để làm nổi bật văn bản bằng nền vàng (highlight), không gạch ngang. Câu 18. Thẻ HTML nào sau đây được dùng để định nghĩa tiêu đề của cột trong bảng? A. Sai. <td> là thẻ định nghĩa ô dữ liệu, không phải tiêu đề. B. Đúng. <th> dùng để định nghĩa ô tiêu đề của hàng hoặc cột trong bảng. C. Sai. <tr> dùng để định nghĩa một hàng trong bảng. D. Sai. <title> dùng để đặt tiêu đề trang, không liên quan đến bảng. Câu 19. Thẻ nào sau đây được sử dụng để chia nội dung trang web thành các khung (frames)? A. Sai. <section> dùng để chia nội dung thành phần, không tạo frame. B. Sai. <div> dùng để chia khối nội dung, không phải khung riêng biệt. C. Đúng. <frameset> dùng trong HTML cũ để chia trang web thành nhiều khung (frames). D. Sai. <main> định nghĩa nội dung chính của trang, không dùng để chia khung. Câu 20. Loại điều khiển nào sau đây phù hợp để người dùng chọn nhiều mục trong danh sách? A. Sai. <input type=\"radio\"> chỉ cho phép chọn một mục. B. Đúng. <select multiple> cho phép người dùng chọn nhiều mục trong danh sách. C. Sai. <textarea> dùng để nhập đoạn văn bản, không phải danh sách chọn. D. Sai. <input type=\"text\"> là trường nhập một dòng văn bản, không dùng để chọn danh sách. Câu 21. Thẻ <legend> trong biểu mẫu có vai trò nào sau đây? A. Đúng. <legend> dùng để mô tả nhóm điều khiển trong thẻ <fieldset>. B. Sai. Biểu mẫu lỗi không liên quan đến <legend>. C. Sai. Tiêu đề toàn trang được khai báo bằng thẻ <title>, không phải <legend>. D. Sai. Không dùng <legend> để tạo liên kết. Câu 22. Thuộc tính CSS nào sau đây xác định cách hiển thị các phần tử trong biểu mẫu? A. Sai. visibility chỉ điều khiển việc phần tử có hiển thị hay ẩn đi, nhưng vẫn chiếm chỗ trên trang. B. Đúng. display xác định cách phần tử được hiển thị (ví dụ: block, inline, flex…), ảnh hưởng trực tiếp đến bố cục và hiển thị trong biểu mẫu. C. Sai. position xác định vị trí phần tử trên trang (absolute, relative...), không trực tiếp quyết định cách hiển thị dạng khối hay dòng. D. Sai. float dùng để đẩy phần tử sang trái/phải, không quyết định cách hiển thị tổng thể. Câu 23. Câu lệnh CSS nào sau đây làm cho danh sách không hiển thị ký hiệu đầu dòng? A. Sai. list-decoration không phải thuộc tính hợp lệ trong CSS. B. Sai. text-decoration: none; dùng để bỏ gạch chân, không liên quan đến danh sách. C. Đúng. list-style-type: none; sẽ loại bỏ ký hiệu đầu dòng của danh sách. D. Sai. bullet: none; không phải cú pháp CSS đúng. Câu 24. Giả sử bạn muốn biểu mẫu có các khung nhập liệu cách đều nhau theo chiều dọc, thuộc tính nào sau đây nên sử dụng? A. Sai. line-height điều chỉnh khoảng cách giữa các dòng chữ, không tác động đến khoảng cách giữa các ô nhập. B. Sai. padding là khoảng cách bên trong phần tử, không kiểm soát được khoảng cách giữa các phần tử. C. Đúng. margin-bottom tạo khoảng cách phía dưới mỗi phần tử, giúp các khung nhập cách đều nhau theo chiều dọc. D. Sai. vertical-align dùng để căn chỉnh chiều dọc trong hàng, không điều chỉnh khoảng cách giữa các phần tử. Phần II. A. Phần chung cho tất cả các thí sinh Câu 1. Một nhóm học sinh tổ chức hoạt động chia sẻ dữ liệu giữa các máy tính trong cùng một lớp học thông qua kết nối mạng LAN nội bộ. Tuy nhiên, một vài máy không thể truy cập vào thư mục chia sẻ của các máy khác. Các bạn cần xác định nguyên nhân và cách khắc phục. Một số ý kiến như sau: a) Sai. Mạng LAN là mạng cục bộ, hoạt động độc lập với Internet. b) Đúng. Nếu máy tính tắt chức năng chia sẻ, các máy khác sẽ không truy cập được thư mục chia sẻ. c) Đúng. Các máy cần cùng Workgroup hoặc cùng dải IP mới có thể chia sẻ dữ liệu qua LAN. d) Sai. Cài lại hệ điều hành là giải pháp cuối cùng, không nên thực hiện ngay khi gặp lỗi chia sẻ mạng. Câu 2. Tổ học sinh A muốn lưu trữ thông tin khảo sát sở thích học tập bằng Google Forms. Sau khi thu thập, nhóm xuất dữ liệu ra bảng tính và thảo luận cách lưu trữ, phân tích kết quả theo từng lớp. Một bạn đề xuất dùng cơ sở dữ liệu để dễ truy vấn, thống kê và bảo mật dữ liệu hơn. Một số ý kiến như sau: a) Sai. Google Forms là công cụ thu thập dữ liệu, không phải hệ cơ sở dữ liệu chuyên dụng để xử lý thống kê. b) Đúng. Có thể tạo một cơ sở dữ liệu từ dữ liệu khảo sát để lưu trữ, phân loại và xử lý hiệu quả hơn. c) Đúng. Dữ liệu từ biểu mẫu có thể nhập vào hệ quản trị cơ sở dữ liệu (như MySQL, Access...) để truy vấn. d) Đúng. Hệ cơ sở dữ liệu hỗ trợ truy vấn theo điều kiện, giúp lọc nhanh học sinh có cùng sở thích từ nhiều lớp. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho chương trình sau: Python C++ def isBalanced(expr): stack = [] for ch in expr: if ch == ''('': stack.append(ch) elif ch == '')'': if not stack: return False stack.pop() return len(stack) == 0 bool isBalanced(string expr) { stack<char> s; for (char ch : expr) { if (ch == ''('') s.push(ch); else if (ch == '')'') { if (s.empty()) return false; s.pop(); } } return s.empty(); } Một số ý kiến như sau: a) Sai. Hàm trả về True chỉ khi các dấu ngoặc mở ''('' và đóng '')'' đúng thứ tự và cân bằng, không chỉ dựa vào số lượng bằng nhau. b) Đúng. Ngăn xếp được dùng để lưu các dấu ''('' khi gặp trong biểu thức. c) Đúng. Khi gặp dấu '')'', nếu ngăn xếp rỗng nghĩa là không có dấu ''('' tương ứng, biểu thức không cân bằng nên trả về False. d) Sai. Hàm trả về True khi tất cả dấu ngoặc được đóng đúng thứ tự và cân bằng; nếu không đúng sẽ trả về False. Câu 4. Ứng dụng Facebook có tích hợp Trí tuệ nhân tạo, học máy để thu thập dữ liệu khách hàng. Ngay cả khi một người sử dụng nhiều tài khoản để đăng nhập và sử dụng thì Facebook có thể hợp nhất dữ liệu liên quan đến người dùng đó, từ đó đưa ra các mẫu quảng cáo, các nội dung phù hợp với từng nhóm người dùng: Với vấn đề nêu trên, một số học sinh đưa ra các ý kiến như sau về Facebook: a) Đúng. Facebook sử dụng trí tuệ nhân tạo và học máy để phân tích hành vi người dùng nhằm cá nhân hóa nội dung và quảng cáo phù hợp. b) Đúng. Khoa học dữ liệu là nền tảng quan trọng giúp Facebook khai thác và hiểu sâu về thói quen và sở thích của người dùng. c) Sai. Facebook có thể sử dụng nhiều kỹ thuật như nhận diện thiết bị, địa chỉ IP, hành vi truy cập để phát hiện các tài khoản thuộc cùng một người, dù thông tin đăng ký khác nhau. d) Đúng. Qua ảnh chân dung, công nghệ học máy có thể ước tính giới tính và độ tuổi người dùng, hỗ trợ cá nhân hóa dịch vụ Câu 5. Nhóm bạn Mai sử dụng phần mềm thiết kế web để tạo trang giới thiệu câu lạc bộ học thuật. Nhóm dùng công cụ tạo danh sách để liệt kê hoạt động, công cụ tạo bảng để thể hiện lịch sinh hoạt và khung nội dung để hiển thị video minh họa. Một số ý kiến như sau: a) Đúng. Danh sách và bảng thường được dùng để tổ chức và trình bày nội dung trên trang web một cách rõ ràng và dễ hiểu. b) Sai. Phần mềm thiết kế web thường cung cấp công cụ tạo danh sách tự động, không cần người dùng phải viết mã HTML phức tạp. c) Đúng. Bảng dùng để hiển thị thông tin theo hàng và cột giúp tổ chức dữ liệu rõ ràng và dễ đọc. d) Sai. Khung nội dung (iframe) cho phép nhúng video hoặc trang web khác vào trang chính một cách dễ dàng. Câu 6. Lan đang làm việc với cơ sở dữ liệu quản lý bán hàng, trong đó có hai bảng: • HoaDon gồm các trường chính: MaHD (Mã hóa đơn), NgayLap (Ngày lập hóa đơn), MaKH (Mã khách hàng), TongTien (Tổng tiền của hóa đơn) • ChiTietHD gồm các trường: MaHD (Mã hóa đơn), MaSP (Mã sản phẩm), SoLuong (Số lượng sản phẩm trong hóa đơn), DonGia (Đơn giá của sản phẩm) Lan cần tìm các sản phẩm được khách hàng đặt mua trong ít nhất 6 hóa đơn khác nhau. Lan viết câu lệnh truy vấn: SELECT MaSP, COUNT(MaHD) AS SoLanDat FROM ChiTietHD GROUP BY MaSP HAVING COUNT(MaHD) > 5; Một số ý kiến như sau: a) Đúng. Trường MaHD trong bảng ChiTietHD nên là khóa ngoại liên kết đến bảng HoaDon để đảm bảo tính toàn vẹn dữ liệu. b) Đúng. Mệnh đề HAVING lọc các sản phẩm có số lần xuất hiện trong hóa đơn nhiều hơn 5 (tức ít nhất 6 lần). c) Sai. Không dùng GROUP BY sẽ không thể nhóm theo sản phẩm, dẫn đến câu truy vấn không trả về kết quả đúng theo yêu cầu. d) Sai. Câu truy vấn có lỗi vì bảng HoaDon không được JOIN với ChiTietHD nên không thể dùng YEAR(HoaDon.NgayLap) trong WHERE trực tiếp; cần phải dùng JOIN để truy vấn đúng. -- 13 of 13 --"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_10
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c1', 'de_on_luyen_10', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Đặc điểm nào sau đây của trí tuệ nhân tạo là hạn chế? A. Không bao giờ mắc phải lỗi sai sót. B. Tự hiểu mọi ngôn ngữ mà không học. C. Phụ thuộc chất lượng dữ liệu huấn luyện. D. Thể hiện cảm xúc như người.', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c2', 'de_on_luyen_10', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Phương án nào sau đây phản ánh đúng ưu điểm của AI? A. Thực hiện công việc lặp lại rất nhanh. B. Luôn luôn hoạt động mà không sai sót. C. Thay thế con người hoàn toàn trong mọi việc? D. Chỉ có thể sử dụng khi có mạng Internet.', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c3', 'de_on_luyen_10', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Phát biểu nào sau đây đúng về hệ thống nhận diện khuôn mặt? A. Chỉ hoạt động với người đeo khẩu trang. B. Không thể phân biệt các khuôn mặt khác. C. Có thể nhận diện trong nhiều điều kiện. D. Chỉ nhận diện khi người đứng yên yên.', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c4', 'de_on_luyen_10', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'AI trong trợ lí ảo như Siri hay Google Assistant có chức năng nào? A. Tính toán tốc độ kết nối mạng Internet. B. Chỉ phát nhạc theo danh sách có sẵn. C. Hiểu và trả lời câu hỏi bằng giọng nói. D. Thay thế chức năng của camera điện thoại.', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c5', 'de_on_luyen_10', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Cho chương trình sau: Python C++ a = [1, 2, 3, 4, 5] a.reverse() for x in a: print(x,end=" ") #include <iostream> #include <algorithm> using namespace std; int main() { int a[] = {1, 2, 3, 4, 5}; reverse(a, a + 5); for (int i = 0; i < 5; i++) cout << a[i] << " "; return 0; } Đáp án nào sau đây là kết quả xuất ra màn hình của chương trình trên? A. 12345 B. [5,4,3,2,1] C. 5 4 3 2 1 D. [1,2,3,4,5]', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_10_p2_c6', 'de_on_luyen_10', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Một học sinh kết nối máy tính với mạng LAN bằng cáp mạng nhưng không truy cập được Internet. Nguyên nhân nào dưới đây hợp lí nhất? A. Cáp mạng bị đứt hoàn toàn. B. Thiết bị chưa cấp quyền truy cập mạng Wi-Fi. C. Máy tính chưa được cấp địa chỉ IP hợp lệ. D. Trình duyệt bị lỗi. Câu 7. Nguyên nhân nào sau đây có thể khiến tín hiệu Wi-Fi yếu đi? A. Sử dụng cáp mạng đạt chuẩn. B. Có nhiều vật cản giữa thiết bị và Modem. C. Sử dụng mật khẩu quá dài. D. Bật chế độ máy bay. Câu 8. Phương án nào sau đây là ưu điểm của mạng không dây? A. Dễ dàng giữ kết nối khi di chuyển thiết bị. B. Tốc độ truyền tải cao hơn mạng có dây. C. Không cần dùng đến router. D. Không cần bảo mật mạng. Câu 9. Phương án nào sau đây mô tả đúng chức năng của Mobile Hotspot? A. Phát nhạc và video không dây. B. Mở khóa thiết bị từ xa qua mạng. C. Tạo điểm truy cập Internet cho thiết bị khác. D. Lưu trữ dữ liệu đám mây cá nhân. Câu 10. Giao tiếp có tính nhân văn trong không gian mạng không bao gồm hành vi nào sau đây? A. Tôn trọng sự khác biệt. B. Đồng cảm với người gặp khó khăn. C. Kích động thù ghét giữa các nhóm. D. Khuyến khích hỗ trợ cộng đồng. Câu 11. Thể hiện nào sau đây đúng trách nhiệm của cá nhân khi tham gia diễn đàn học tập trực tuyến? A. Thể hiện quan điểm cá nhân bằng mọi cách. B. Bình luận bằng các biểu tượng để giảm thời gian gõ. C. Trả lời có lí lẽ, tôn trọng bạn học và giáo viên. D. Tránh tranh luận với người không cùng quan điểm. Câu 12. Người có trách nhiệm ứng xử nhân văn khi giao tiếp trên mạng cần thể hiện điều nào sau đây? A. Đáp trả lại lời xúc phạm ngay lập tức. B. Chỉ chia sẻ điều mình thích mà không cần quan tâm người khác. C. Biết lắng nghe, thấu hiểu và ứng xử đúng mực. D. Tránh tất cả các cuộc trò chuyện mạng. Câu 13. Trong nhóm nghề CNTT, kỹ thuật viên phần cứng có nhiệm vụ nào sau đây? A. Lắp ráp, sửa chữa các thiết bị máy tính. B. Thiết kế giao diện website và trải nghiệm người dùng (UI/UX). C. Soạn thảo hợp đồng và quản lý hồ sơ hành chính. D. Hỗ trợ người dùng cài đặt phần mềm văn phòng qua điện thoại. Câu 14. Nghề nào sau đây thuộc nhóm nghề quản trị trong CNTT? A. Quản lý dự án CNTT. B. Kỹ thuật viên lắp ráp máy tính. C. Lập trình viên phát triển ứng dụng di động. D. Nhân viên nhập liệu văn phòng. Câu 15. Kỹ năng nào sau đây cần thiết cho người làm nghề dịch vụ và quản trị CNTT? A. Quản lý và giao tiếp hiệu quả. B. Làm vườn và chăm sóc động vật. C. Cắt may và thiết kế thời trang. D. Nấu ăn và pha chế đồ uống. Câu 16. Cặp thẻ nào sau đây được dùng để tạo bảng trong thiết kế trang Web. A. <table>…</table> B. <ol>…</ol> C. <tr>…</tr> D. <ul>…</ul> Câu 17. Trong HTML, thẻ nào sau đây được sử dụng để đánh dấu xóa bằng nét gạch giữa chữ? A.<strong> B. <u> C.<del> D.<mark> Câu 18. Thẻ HTML nào sau đây được dùng để định nghĩa tiêu đề của cột trong bảng? A. <td> B. <th> C. <tr> D. <title> Câu 19. Thẻ nào sau đây được sử dụng để chia nội dung trang web thành các khung (frames)? A. <section> B. <div> C. <frameset> D. <main> Câu 20. Loại điều khiển nào sau đây phù hợp để người dùng chọn nhiều mục trong danh sách? A. <input type="radio"> B. <select multiple> C. <textarea> D. <input type="text"> Câu 21. Thẻ <legend> trong biểu mẫu có vai trò nào sau đây? A. Xác định mô tả cho nhóm điều khiển được bao bởi <fieldset>. B. Hiển thị nội dung thay thế khi biểu mẫu lỗi. C. Chỉ định tiêu đề của toàn trang. D. Tạo liên kết đến biểu mẫu khác. Câu 22. Thuộc tính CSS nào sau đây xác định cách hiển thị các phần tử trong biểu mẫu? A. visibility B. display C. position D. float Câu 23. Câu lệnh CSS nào sau đây làm cho danh sách không hiển thị ký hiệu đầu dòng? A. list-decoration: none; B. text-decoration: none; C. list-style-type: none; D. bullet: none; Câu 24. Giả sử bạn muốn biểu mẫu có các khung nhập liệu cách đều nhau theo chiều dọc, thuộc tính nào sau đây nên sử dụng? A. line-height B. padding C. margin-bottom D. vertical-align Phần II. Trắc nghiệm dạng đúng sai (4 điểm): Thí sinh trả lời 4 câu hỏi cho phần thi tương ứng: Mỗi câu hỏi thí sinh tô vào ô tương ứng với đúng hoặc sai đối với mỗi ý trong từng câu hỏi của đề. A. Phần chung cho tất cả các thí sinh Câu 1. Một nhóm học sinh tổ chức hoạt động chia sẻ dữ liệu giữa các máy tính trong cùng một lớp học thông qua kết nối mạng LAN nội bộ. Tuy nhiên, một vài máy không thể truy cập vào thư mục chia sẻ của các máy khác. Các bạn cần xác định nguyên nhân và cách khắc phục. Một số ý kiến như sau:', '[{"id": "a", "text": "Mạng LAN chỉ hoạt động nếu có kết nối Internet.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Có thể một số máy đã tắt chức năng chia sẻ trong cài đặt mạng.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Cần kiểm tra nhóm mạng (Workgroup) hoặc địa chỉ IP của các máy.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Giải pháp đầu tiên nên làm là cài lại hệ điều hành cho các máy bị lỗi để khắc phục. Câu 2. Tổ học sinh A muốn lưu trữ thông tin khảo sát sở thích học tập bằng Google Forms. Sau khi thu thập, nhóm xuất dữ liệu ra bảng tính và thảo luận cách lưu trữ, phân tích kết quả theo từng lớp. Một bạn đề xuất dùng cơ sở dữ liệu để dễ truy vấn, thống kê và bảo mật dữ liệu hơn. Một số ý kiến như sau: a) Google Forms là hệ cơ sở dữ liệu dùng để xử lí thống kê. b) Một cơ sở dữ liệu có thể được tạo ra từ nguồn dữ liệu khảo sát. c) Dữ liệu thu thập từ biểu mẫu có thể nhập vào các hệ quản trị cơ sở dữ liệu để truy vấn. d) Sử dụng hệ cơ sở dữ liệu giúp dễ dàng tìm học sinh có cùng sở thích từ nhiều lớp. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho chương trình sau: Python C++ def isBalanced(expr): stack = [] for ch in expr: if ch == ''('': stack.append(ch) elif ch == '')'': if not stack: return False stack.pop() return len(stack) == 0 bool isBalanced(string expr) { stack<char> s; for (char ch : expr) { if (ch == ''('') s.push(ch); else if (ch == '')'') { if (s.empty()) return false; s.pop(); } } return s.empty(); } Một số ý kiến như sau: a) Nếu biểu thức có số dấu ''('' và '')'' bằng nhau, hàm trả về True. b) Ngăn xếp được dùng để lưu dấu ''('' khi gặp. c) Khi gặp dấu '')'', nếu ngăn xếp rỗng, biểu thức không cân bằng. d) Hàm trả về False nếu tất cả dấu ngoặc đã được đóng đúng thứ tự. Câu 4. Ứng dụng Facebook có tích hợp Trí tuệ nhân tạo, học máy để thu thập dữ liệu khách hàng. Ngay cả khi một người sử dụng nhiều tài khoản để đăng nhập và sử dụng thì Facebook có thể hợp nhất dữ liệu liên quan đến người dùng đó, từ đó đưa ra các mẫu quảng cáo, các nội dung phù hợp với từng nhóm người dùng: Với vấn đề nêu trên, một số học sinh đưa ra các ý kiến như sau về Facebook: a. Facebook sử dụng trí tuệ nhân tạo và học máy để phân tích hành vi người dùng nhằm cá nhân hóa nội dung hiển thị. b. Khoa học dữ liệu là nền tảng quan trọng giúp Facebook khai thác và hiểu sâu về thói quen người dùng. c. Khi dùng Facebook trên cùng một thiết bị, một người dùng tạo hai tài khoản hoàn toàn khác nhau (sdt, email,…) thì ứng dụng KHÔNG thể phát hiện 2 tài khoản này của cùng 1 người. d. Có thể biết được giới tính hoặc ước tính độ tuổi khi người dùng cung cấp ảnh chân dung của họ. Câu 5. Nhóm bạn Mai sử dụng phần mềm thiết kế web để tạo trang giới thiệu câu lạc bộ học thuật. Nhóm dùng công cụ tạo danh sách để liệt kê hoạt động, công cụ tạo bảng để thể hiện lịch sinh hoạt và khung nội dung để hiển thị video minh họa. Một số ý kiến như sau: a) Danh sách và bảng là hai thành phần thường được dùng để tổ chức nội dung. b) Tạo danh sách trong phần mềm web yêu cầu viết mã HTML phức tạp. c) Bảng có thể dùng để hiển thị thông tin theo hàng và cột rõ ràng. d) Trong khung nội dung không thể nhúng video hoặc trang web khác vào trang chính. Câu 6. Lan đang làm việc với cơ sở dữ liệu quản lý bán hàng, trong đó có hai bảng: • HoaDon gồm các trường chính: MaHD (Mã hóa đơn), NgayLap (Ngày lập hóa đơn), MaKH (Mã khách hàng), TongTien (Tổng tiền của hóa đơn) • ChiTietHD gồm các trường: MaHD (Mã hóa đơn), MaSP (Mã sản phẩm), SoLuong (Số lượng sản phẩm trong hóa đơn), DonGia (Đơn giá của sản phẩm) Lan cần tìm các sản phẩm được khách hàng đặt mua trong ít nhất 6 hóa đơn khác nhau. Lan viết câu lệnh truy vấn: SELECT MaSP, COUNT(MaHD) AS SoLanDat FROM ChiTietHD GROUP BY MaSP HAVING COUNT(MaHD) > 5; Một số ý kiến như sau: a) Khi tạo bảng ChiTietHD cần tạo khóa ngoài MaHD liên kết đến bảng HoaDon. b) Mệnh đề HAVING lọc các sản phẩm có số lần đặt nhiều hơn 5. c) Có thể không cần dùng GROUP BY vẫn giữ nguyên ý nghĩa câu truy vấn. d) Nếu muốn giới hạn truy vấn chỉ xét các hóa đơn trong năm 2024, có thể bổ sung điều kiện lọc ở mệnh đề WHERE như sau: SELECT MaSP, COUNT(MaHD) AS SoLanDat FROM ChiTietHD WHERE YEAR(HoaDon.NgayLap) = 2024 GROUP BY MaSP HAVING COUNT(MaHD) > 5; ---Hết---", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

