-- Câu hỏi Phần I của de_on_luyen_11
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c1', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây mô tả chức năng của trí tuệ nhân tạo?', '{"A": "Sai. Lưu trữ dữ liệu lớn là chức năng của hệ thống lưu trữ, không phải AI.", "B": "Đúng. Thực hiện các tác vụ thông minh là bản chất của trí tuệ nhân tạo.", "C": "Sai. Kết nối mạng xã hội là chức năng của các nền tảng mạng xã hội.", "D": "Sai. Tạo ra phần mềm văn phòng là công việc của lập trình viên."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c2', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Trí tuệ nhân tạo (AI) không thể thực hiện nhiệm vụ nào sau đây?', '{"A": "Sai. AI có thể nhận dạng giọng nói rất hiệu quả.", "B": "Sai. AI có thể chẩn đoán bệnh qua hình ảnh y tế nhờ học sâu và thị giác máy tính.", "C": "Sai. AI rất giỏi trong việc phân tích dữ liệu lớn (Big Data).", "D": "Đúng. AI không thể phát triển cảm xúc như con người."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c3', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Ứng dụng có tích hợp AI nào sau đây có thể bị dùng để giả mạo danh tính trong video lừa đảo, tống tiền, hoặc đánh lừa hệ thống xác thực bằng khuôn mặt?', '{"A": "Đúng. DeepFaceLab là công cụ tạo deepfake, dùng AI để giả mạo khuôn mặt trong video.", "B": "Sai. AutoSploit là công cụ tự động khai thác lỗ hổng bảo mật, không liên quan đến deepfake video.", "C": "Sai. Chat GPT là mô hình xử lý ngôn ngữ tự nhiên, không dùng để tạo video giả mạo khuôn mặt.", "D": "Sai. AI-Powered Phishing Tools thường dùng AI để tạo email hoặc tin nhắn lừa đảo. Câu 4: Một ngân hàng muốn sử dụng trí tuệ nhân tạo (AI) để giảm thiểu rủi ro từ các giao dịch gian lận. Phương án nào sau đây là ứng dụng phù hợp của AI để hỗ trợ mục tiêu này? A. Sai. Tạo giao diện website thân thiện không liên quan đến phát hiện gian lận. B. Sai. Dự đoán xu hướng đầu tư dài hạn không trực tiếp giảm rủi ro giao dịch gian lận. C. Đúng. Phân tích hành vi giao dịch để phát hiện giao dịch bất thường là ứng dụng AI hiệu quả trong chống gian lận. D. Sai. Tự động in sao kê tài khoản không giúp phát hiện gian lận. Câu 5. Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ def kt_ngto(n): if n < 2: return 0 for i in range(2, int(n**0.5) + 1): if n % i == 0: return 0 return 1 bool kt_ngto(int n) { if (n < 2) return 0; int limit = int(sqrt(n)); for (int i = 2; i <= limit; i++) { if (n % i == 0) return 0; } return 1; } Phương án nào sau đây là giá trị của hàm kt_ngto khi truyền tham số n bằng 13? A. Sai. False không phải giá trị hàm trả về trong đoạn code. B. Sai. True là kiểu dữ liệu boolean, đoạn code trả về 0 hoặc 1. C. Đúng. 13 là số nguyên tố nên hàm trả về giá trị 1. D. Sai. 0 biểu thị số không phải nguyên tố. Câu 6. Giao thức nào sau đây xử lý việc truyền email giữa các máy chủ? A. Đúng. SMTP (Simple Mail Transfer Protocol) dùng để gửi email giữa các máy chủ. B. Sai. POP3 dùng để nhận email từ máy chủ về máy khách. C. Sai. IMAP dùng để truy cập email từ máy chủ, không phải gửi. D. Sai. HTTPS là giao thức truyền tải dữ liệu web an toàn. Câu 7: Phương án nào sau đây mô tả đúng chức năng của địa chỉ MAC trong mạng máy tính? A. Đúng. Địa chỉ MAC xác định duy nhất địa chỉ vật lý của thiết bị mạng. B. Sai. Kết nối Internet tốc độ cao không phải chức năng của địa chỉ MAC. C. Sai. Mã hóa dữ liệu khi truyền qua mạng không phải nhiệm vụ của MAC. D. Sai. Định danh thiết bị trên mạng Internet là chức năng của địa chỉ IP. Câu 8. Hệ thống DNS cần thiết trong hoạt động của mạng Internet vì lí do nào sau đây? A. Đúng. DNS chuyển địa chỉ IP dạng số sang dạng tên miền giúp người dùng dễ dàng ghi nhớ địa chỉ trang web. B. Sai. Bảo vệ thông tin khi truyền dữ liệu là chức năng của các giao thức bảo mật khác như HTTPS. C. Sai. DNS không giúp ghi nhớ địa chỉ IP. D. Sai. DNS không hỗ trợ việc gửi nhận thư điện tử trực tiếp. Câu 9. Trong một công ty có hai mạng cục bộ (LAN) hoạt động độc lập. Sử dụng thiết bị nào sau đây để các máy tính ở hai mạng này có thể truy cập Internet và chia sẻ tài nguyên với nhau? A. Đúng. Router là thiết bị kết nối các mạng khác nhau và quản lý truy cập Internet. B. Sai. Modem chuyển đổi tín hiệu mạng, không kết nối hai LAN độc lập. C. Sai. Switch chỉ kết nối các thiết bị trong cùng một LAN. D. Sai. Access Point cung cấp kết nối không dây trong một LAN. Câu 10. Phương án nào sau đây thể hiện hành vi ứng xử văn minh trên mạng xã hội? A. Sai. Gửi tin nhắn nặc danh xúc phạm là hành vi không văn minh. B. Sai. Chia sẻ thông tin chưa kiểm chứng gây hiểu lầm, không phải ứng xử văn minh. C. Đúng. Bình luận lịch sự, tôn trọng người khác là ứng xử văn minh trên mạng xã hội. D. Sai. Chế giễu người khác qua mạng là hành vi tiêu cực, không văn minh. Câu 11. Phương án nào sau đây là hành động nên tránh khi giao tiếp trong không gian mạng? A. Đúng. Đăng tải nội dung gây kích động thù ghét là hành vi tiêu cực, vi phạm quy tắc ứng xử văn minh trên không gian mạng. B. Sai. Tôn trọng quyền riêng tư của người khác là hành vi nên thực hiện. C. Sai. Trả lời bình luận một cách ôn hòa giúp tạo môi trường giao tiếp lành mạnh. D. Sai. Sử dụng ngôn ngữ phù hợp là hành vi tích cực và văn minh. Câu 12. Lan muốn đăng ảnh và chia sẻ kỷ niệm về chuyến du lịch trên mạng xã hội. Hành động nào sau đây của Lan có thể gây rủi ro đến bảo mật thông tin cá nhân? A. Đúng. Chia sẻ ảnh kèm vị trí hiện tại và thông tin hộ chiếu dễ dẫn đến rò rỉ thông tin cá nhân và nguy cơ bị kẻ xấu lợi dụng. B. Sai. Thiết lập quyền riêng tư chỉ cho bạn bè xem giúp kiểm soát người xem bài viết. C. Sai. Đăng hình ảnh về cảnh đẹp mà không tiết lộ thông tin nhạy cảm thường an toàn. D. Sai. Bật xác thực hai yếu tố là biện pháp tăng cường bảo mật tài khoản. Câu 13. Công việc nào sau đây là nhiệm vụ chính của người làm nghề dịch vụ thuộc ngành CNTT? A. Sai. Dạy học là nghề thuộc lĩnh vực giáo dục. B. Sai. Thiết kế đồ họa thuộc lĩnh vực sáng tạo – truyền thông. C. Đúng. Hỗ trợ kỹ thuật, khắc phục sự cố phần cứng là nhiệm vụ của nhân viên dịch vụ trong ngành CNTT. D. Sai. Tổ chức sự kiện công nghệ không phải là nhiệm vụ nghề dịch vụ CNTT. Câu 14. Nhân lực CNTT đóng vai trò quan trọng trong lĩnh vực ngân hàng hiện đại vì lí do nào sau đây? A. Đúng. Bảo vệ thông tin khách hàng và duy trì an toàn hệ thống tài chính là trách nhiệm chính của đội ngũ CNTT trong ngân hàng. B. Sai. Làm việc với khách hàng tại quầy là nhiệm vụ của nhân viên giao dịch. C. Sai. Thiết kế sản phẩm đồ họa là công việc của bộ phận truyền thông – marketing. D. Sai. Công việc văn thư hành chính không thuộc chuyên môn CNTT. Câu 15. Minh muốn theo học một ngành tập trung vào việc bảo vệ dữ liệu và xử lý các mối đe dọa an ninh mạng trong doanh nghiệp. Ngành học nào sau đây phù hợp nhất với mục tiêu của Minh? A. Sai. Khoa học máy tính tập trung vào lý thuyết và lập trình, không chuyên sâu về bảo mật. B. Sai. Mạng máy tính tập trung vào xây dựng hệ thống mạng, ít chuyên sâu về an toàn. C. Đúng. An toàn thông tin là ngành học phù hợp để xử lý các vấn đề về bảo mật dữ liệu và phòng chống mối đe dọa mạng. D. Sai. Công nghệ phần mềm chủ yếu tập trung vào phát triển ứng dụng, không chuyên về bảo mật. Câu 16. Phương án nào sau đây mô tả đúng chức năng của thẻ <audio> trong HTML? A. Sai. Hiển thị hình ảnh là chức năng của thẻ <img>. B. Đúng. Thẻ <audio> được dùng để nhúng và phát tệp âm thanh trên trang web. C. Sai. Tạo liên kết là chức năng của thẻ <a>. D. Sai. Hiển thị video là chức năng của thẻ <video>. Câu 17. CSS không có vai trò nào sau đây trong thiết kế trang web? A. Sai. CSS định dạng kiểu dáng cho phần tử là một chức năng cơ bản. B. Đúng. Xác định cấu trúc và nội dung là nhiệm vụ của HTML, không phải CSS. C. Sai. CSS giúp thay đổi màu sắc, font chữ là chức năng phổ biến. D. Sai. CSS định kiểu cho các trạng thái như hover, active, focus,… Câu 18. Sử dụng thẻ HTML nào sau đây tạo các trường nhập liệu như ô textbox, checkbox, radio trên biểu mẫu? A. Sai. <div> chỉ tạo khối chứa, không dùng để tạo trường nhập liệu. B. Sai. <form> định nghĩa biểu mẫu nhưng không trực tiếp tạo trường nhập. C. Đúng. <input> là thẻ được dùng để tạo các loại trường nhập liệu như textbox, checkbox, radio,... D. Sai. <iframe> dùng để nhúng tài liệu khác, không liên quan biểu mẫu. Câu 19. Thẻ nào sau đây không bắt bắt buộc có trong trang HTML cơ bản? A. Sai. <html> là thẻ bao ngoài, bắt buộc trong mọi tài liệu HTML. B. Sai. <head> chứa thông tin meta, tiêu đề,… là thành phần bắt buộc. C. Sai. <body> chứa nội dung hiển thị chính, cũng bắt buộc. D. Đúng. <h1> là thẻ tiêu đề, không bắt buộc phải có trong mọi trang HTML. Câu 20. Sử dụng mã CSS nào sau đây định kiểu viền màu đỏ, dày 2px, kiểu nét liền cho thẻ <div>? A. Đúng. Cú pháp div {border: 2px solid red;} là cách viết đúng và đầy đủ. B. Sai. border-width không thể đi kèm solid như trong ví dụ. C. Sai. Thứ tự không chuẩn. D. Sai. border-style cần được tách riêng hoặc nằm trong thuộc tính border. Câu 21. Phương án nào sau đây đúng về vai trò của thẻ <mark> khi sử dụng trong văn bản HTML? A. Sai. In đậm là chức năng của thẻ <strong> hoặc <b>. B. Đúng. Thẻ <mark> được dùng để đánh dấu và làm nổi bật đoạn văn bản, thường có nền màu vàng. C. Sai. Chèn liên kết là chức năng của thẻ <a>. D. Sai. Hiển thị chữ nghiêng là chức năng của thẻ <i> hoặc <em>. Câu 22. Sử dụng mã HTML nào sau đây sẽ cho kết quả hiển thị trên trang web như hình dưới? A. Đúng. Mã lệnh đúng để hiển thị kết quả theo yêu cầu. B. Sai. list-style-type: disc; tạo dấu chấm tròn, không phải hình vuông. C. Sai. Dùng <ol> là danh sách có thứ tự, thường đánh số, không phù hợp. D. Sai. <ol> là danh sách có thứ tự. Câu 23. Mã CSS nào sau đây thay đổi màu chữ của liên kết sang màu đỏ khi người dùng di chuyển chuột lướt qua? A. Đúng. Cú pháp đúng để thay đổi màu chữ của liên kết khi chuột lướt qua liên kết. B. Sai. hover-color không phải là thuộc tính hợp lệ trong CSS. C. Sai. a:active áp dụng khi liên kết đang được nhấn, không phải lúc di chuột lướt qua. D. Sai. a:visited áp dụng cho liên kết đã được truy cập, không phải hover. Câu 24. Mã HTML nào sau đây tạo một ô nhập liệu trong biểu mẫu mà người dùng chỉ được nhập số và bắt buộc phải nhập? A. Sai. type=\"text\" cho phép nhập chữ và số, nhưng không giới hạn định dạng là số. B. Đúng. Giá trị “number” cho phép nhập số, thuộc tính required là bắt buộc nhập. C. Sai. type=\"number\" đúng định dạng nhưng thiếu required, không bắt buộc phải nhập. D. Sai. type=\"text\" không giới hạn kiểu dữ liệu và cũng thiếu required. Phần II. A. Phần chung cho tất cả các thí sinh Câu 1. Một trường học triển khai hệ thống mạng LAN để kết nối các phòng máy tính, thư viện và văn phòng. Mỗi phòng đều có nhiều máy tính được kết nối qua Switch, trong khi một Router trung tâm được sử dụng để kết nối toàn bộ hệ thống ra Internet. Để mở rộng kết nối cho các thiết bị di động như laptop và điện thoại trong khu vực thư viện và phòng họp, nhà trường sử dụng thêm Access Point. Tuy nhiên, vào giờ cao điểm, mạng thường chậm lại, đặc biệt là khi nhiều người truy cập Internet cùng lúc tại thư viện. Một số ý kiến như sau: a) Đúng. Switch là thiết bị dùng để kết nối các máy tính trong cùng mạng LAN. b) Sai. Router không có chức năng chuyển đổi giữa các chuẩn WiFi. c) Sai. Switch không phát WiFi; mạng chậm tại thư viện có thể do Access Point quá tải. d) Đúng. Khi mất Internet, các thiết bị trong mạng LAN vẫn có thể chia sẻ dữ liệu nội bộ. Câu 2. Công ty 3K vừa triển khai dự án quản lí dữ liệu khách hàng và sản phẩm. Họ được giới thiệu về các hệ quản trị cơ sở dữ liệu (CSDL). Ban quản lí biết rằng hệ CSDL quan hệ lưu trữ dữ liệu dưới dạng bảng, sử dụng ngôn ngữ SQL để truy vấn, phù hợp với dữ liệu có cấu trúc rõ ràng và có các ràng buộc dữ liệu nghiêm ngặt. Một số ý kiến như sau: a) Đúng. Bảng dữ liệu gồm các trường (cột) và bản ghi (hàng) trong CSDL quan hệ. b) Sai. SQL không chỉ truy vấn mà còn hỗ trợ tạo lập, cập nhật và quản lý cơ sở dữ liệu. c) Đúng. Ràng buộc dữ liệu giữa các bảng được thiết lập thông qua khóa ngoại (foreign key). d) Đúng. NoSQL phù hợp để lưu trữ dữ liệu phi cấu trúc như hình ảnh, video và linh hoạt khi mở rộng. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho đoạn chương trình sau: Python C++ def factorial(n): if n == 0: return 1 else: return n * factorial(n - 1) int factorial(int n) { if (n == 0) return 1; else return n * factorial(n - 1); } Một số ý kiến như sau: a) Đúng. Đây là một ví dụ cơ bản của đệ quy tuyến tính vì hàm gọi lại chính nó một lần duy nhất. b) Đúng. Điều kiện dừng if n == 0 giúp tránh vòng lặp vô hạn trong đệ quy. c) Đúng. Độ phức tạp thời gian của hàm là O(n) vì gọi n lần cho đến khi n = 0. d) Sai. Đệ quy gọi lại nhiều lần (như cây đệ quy) sẽ làm chương trình kém tối ưu, tốn tài nguyên hơn."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c4', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Một nhóm học sinh đang làm dự án nhận diện thư rác bằng mô hình học máy. Họ thu thập dữ liệu từ hộp thư đến và phân loại thành hai nhóm: “Thư thường” và “Thư rác”. Sau khi thu thập, các bạn nhận thấy một số email bị thiếu tiêu đề, một số khác chứa kí tự lạ. Để cải thiện chất lượng dữ liệu, nhóm sử dụng bước xử lí sơ bộ gồm loại bỏ dữ liệu thiếu, chuẩn hoá nội dung và trích xuất các đặc trưng như tần suất từ khoá quảng cáo. Sau khi huấn luyện mô hình, nhóm đánh giá kết quả bằng cách chạy thử trên một tập email mới. Một số ý kiến như sau: a) Đúng. Dữ liệu đầu vào có ảnh hưởng rất lớn đến hiệu quả mô hình học máy. b) Sai. Cần xử lý sơ bộ dữ liệu (loại bỏ thiếu, chuẩn hóa,…) trước khi huấn luyện để đảm bảo chất lượng mô hình. c) Đúng. Tập dữ liệu đầu vào được sử dụng để dạy mô hình gọi là tập huấn luyện (training set). d) Sai. Việc chia dữ liệu thành tập huấn luyện và kiểm tra giúp đánh giá mô hình chính xác hơn, không làm giảm chất lượng thực tế.', '{"A": "Phương án A", "B": "Phương án B", "C": "Phương án C", "D": "Phương án D"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c5', 'de_on_luyen_11', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'single_choice', 'biet', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ def kt_ngto(n): if n < 2: return 0 for i in range(2, int(n**0.5) + 1): if n % i == 0: return 0 return 1 bool kt_ngto(int n) { if (n < 2) return 0; int limit = int(sqrt(n)); for (int i = 2; i <= limit; i++) { if (n % i == 0) return 0; } return 1; } Phương án nào sau đây là giá trị của hàm kt_ngto khi truyền tham số n bằng 13?', '{"A": "Sai. False không phải giá trị hàm trả về trong đoạn code.", "B": "Sai. True là kiểu dữ liệu boolean, đoạn code trả về 0 hoặc 1.", "C": "Đúng. 13 là số nguyên tố nên hàm trả về giá trị 1.", "D": "Sai. 0 biểu thị số không phải nguyên tố."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c6', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Giao thức nào sau đây xử lý việc truyền email giữa các máy chủ?', '{"A": "Đúng. SMTP (Simple Mail Transfer Protocol) dùng để gửi email giữa các máy chủ.", "B": "Sai. POP3 dùng để nhận email từ máy chủ về máy khách.", "C": "Sai. IMAP dùng để truy cập email từ máy chủ, không phải gửi.", "D": "Sai. HTTPS là giao thức truyền tải dữ liệu web an toàn. Câu 7: Phương án nào sau đây mô tả đúng chức năng của địa chỉ MAC trong mạng máy tính? A. Đúng. Địa chỉ MAC xác định duy nhất địa chỉ vật lý của thiết bị mạng. B. Sai. Kết nối Internet tốc độ cao không phải chức năng của địa chỉ MAC. C. Sai. Mã hóa dữ liệu khi truyền qua mạng không phải nhiệm vụ của MAC. D. Sai. Định danh thiết bị trên mạng Internet là chức năng của địa chỉ IP. Câu 8. Hệ thống DNS cần thiết trong hoạt động của mạng Internet vì lí do nào sau đây? A. Đúng. DNS chuyển địa chỉ IP dạng số sang dạng tên miền giúp người dùng dễ dàng ghi nhớ địa chỉ trang web. B. Sai. Bảo vệ thông tin khi truyền dữ liệu là chức năng của các giao thức bảo mật khác như HTTPS. C. Sai. DNS không giúp ghi nhớ địa chỉ IP. D. Sai. DNS không hỗ trợ việc gửi nhận thư điện tử trực tiếp. Câu 9. Trong một công ty có hai mạng cục bộ (LAN) hoạt động độc lập. Sử dụng thiết bị nào sau đây để các máy tính ở hai mạng này có thể truy cập Internet và chia sẻ tài nguyên với nhau? A. Đúng. Router là thiết bị kết nối các mạng khác nhau và quản lý truy cập Internet. B. Sai. Modem chuyển đổi tín hiệu mạng, không kết nối hai LAN độc lập. C. Sai. Switch chỉ kết nối các thiết bị trong cùng một LAN. D. Sai. Access Point cung cấp kết nối không dây trong một LAN. Câu 10. Phương án nào sau đây thể hiện hành vi ứng xử văn minh trên mạng xã hội? A. Sai. Gửi tin nhắn nặc danh xúc phạm là hành vi không văn minh. B. Sai. Chia sẻ thông tin chưa kiểm chứng gây hiểu lầm, không phải ứng xử văn minh. C. Đúng. Bình luận lịch sự, tôn trọng người khác là ứng xử văn minh trên mạng xã hội. D. Sai. Chế giễu người khác qua mạng là hành vi tiêu cực, không văn minh. Câu 11. Phương án nào sau đây là hành động nên tránh khi giao tiếp trong không gian mạng? A. Đúng. Đăng tải nội dung gây kích động thù ghét là hành vi tiêu cực, vi phạm quy tắc ứng xử văn minh trên không gian mạng. B. Sai. Tôn trọng quyền riêng tư của người khác là hành vi nên thực hiện. C. Sai. Trả lời bình luận một cách ôn hòa giúp tạo môi trường giao tiếp lành mạnh. D. Sai. Sử dụng ngôn ngữ phù hợp là hành vi tích cực và văn minh. Câu 12. Lan muốn đăng ảnh và chia sẻ kỷ niệm về chuyến du lịch trên mạng xã hội. Hành động nào sau đây của Lan có thể gây rủi ro đến bảo mật thông tin cá nhân? A. Đúng. Chia sẻ ảnh kèm vị trí hiện tại và thông tin hộ chiếu dễ dẫn đến rò rỉ thông tin cá nhân và nguy cơ bị kẻ xấu lợi dụng. B. Sai. Thiết lập quyền riêng tư chỉ cho bạn bè xem giúp kiểm soát người xem bài viết. C. Sai. Đăng hình ảnh về cảnh đẹp mà không tiết lộ thông tin nhạy cảm thường an toàn. D. Sai. Bật xác thực hai yếu tố là biện pháp tăng cường bảo mật tài khoản. Câu 13. Công việc nào sau đây là nhiệm vụ chính của người làm nghề dịch vụ thuộc ngành CNTT? A. Sai. Dạy học là nghề thuộc lĩnh vực giáo dục. B. Sai. Thiết kế đồ họa thuộc lĩnh vực sáng tạo – truyền thông. C. Đúng. Hỗ trợ kỹ thuật, khắc phục sự cố phần cứng là nhiệm vụ của nhân viên dịch vụ trong ngành CNTT. D. Sai. Tổ chức sự kiện công nghệ không phải là nhiệm vụ nghề dịch vụ CNTT. Câu 14. Nhân lực CNTT đóng vai trò quan trọng trong lĩnh vực ngân hàng hiện đại vì lí do nào sau đây? A. Đúng. Bảo vệ thông tin khách hàng và duy trì an toàn hệ thống tài chính là trách nhiệm chính của đội ngũ CNTT trong ngân hàng. B. Sai. Làm việc với khách hàng tại quầy là nhiệm vụ của nhân viên giao dịch. C. Sai. Thiết kế sản phẩm đồ họa là công việc của bộ phận truyền thông – marketing. D. Sai. Công việc văn thư hành chính không thuộc chuyên môn CNTT. Câu 15. Minh muốn theo học một ngành tập trung vào việc bảo vệ dữ liệu và xử lý các mối đe dọa an ninh mạng trong doanh nghiệp. Ngành học nào sau đây phù hợp nhất với mục tiêu của Minh? A. Sai. Khoa học máy tính tập trung vào lý thuyết và lập trình, không chuyên sâu về bảo mật. B. Sai. Mạng máy tính tập trung vào xây dựng hệ thống mạng, ít chuyên sâu về an toàn. C. Đúng. An toàn thông tin là ngành học phù hợp để xử lý các vấn đề về bảo mật dữ liệu và phòng chống mối đe dọa mạng. D. Sai. Công nghệ phần mềm chủ yếu tập trung vào phát triển ứng dụng, không chuyên về bảo mật. Câu 16. Phương án nào sau đây mô tả đúng chức năng của thẻ <audio> trong HTML? A. Sai. Hiển thị hình ảnh là chức năng của thẻ <img>. B. Đúng. Thẻ <audio> được dùng để nhúng và phát tệp âm thanh trên trang web. C. Sai. Tạo liên kết là chức năng của thẻ <a>. D. Sai. Hiển thị video là chức năng của thẻ <video>. Câu 17. CSS không có vai trò nào sau đây trong thiết kế trang web? A. Sai. CSS định dạng kiểu dáng cho phần tử là một chức năng cơ bản. B. Đúng. Xác định cấu trúc và nội dung là nhiệm vụ của HTML, không phải CSS. C. Sai. CSS giúp thay đổi màu sắc, font chữ là chức năng phổ biến. D. Sai. CSS định kiểu cho các trạng thái như hover, active, focus,… Câu 18. Sử dụng thẻ HTML nào sau đây tạo các trường nhập liệu như ô textbox, checkbox, radio trên biểu mẫu? A. Sai. <div> chỉ tạo khối chứa, không dùng để tạo trường nhập liệu. B. Sai. <form> định nghĩa biểu mẫu nhưng không trực tiếp tạo trường nhập. C. Đúng. <input> là thẻ được dùng để tạo các loại trường nhập liệu như textbox, checkbox, radio,... D. Sai. <iframe> dùng để nhúng tài liệu khác, không liên quan biểu mẫu. Câu 19. Thẻ nào sau đây không bắt bắt buộc có trong trang HTML cơ bản? A. Sai. <html> là thẻ bao ngoài, bắt buộc trong mọi tài liệu HTML. B. Sai. <head> chứa thông tin meta, tiêu đề,… là thành phần bắt buộc. C. Sai. <body> chứa nội dung hiển thị chính, cũng bắt buộc. D. Đúng. <h1> là thẻ tiêu đề, không bắt buộc phải có trong mọi trang HTML. Câu 20. Sử dụng mã CSS nào sau đây định kiểu viền màu đỏ, dày 2px, kiểu nét liền cho thẻ <div>? A. Đúng. Cú pháp div {border: 2px solid red;} là cách viết đúng và đầy đủ. B. Sai. border-width không thể đi kèm solid như trong ví dụ. C. Sai. Thứ tự không chuẩn. D. Sai. border-style cần được tách riêng hoặc nằm trong thuộc tính border. Câu 21. Phương án nào sau đây đúng về vai trò của thẻ <mark> khi sử dụng trong văn bản HTML? A. Sai. In đậm là chức năng của thẻ <strong> hoặc <b>. B. Đúng. Thẻ <mark> được dùng để đánh dấu và làm nổi bật đoạn văn bản, thường có nền màu vàng. C. Sai. Chèn liên kết là chức năng của thẻ <a>. D. Sai. Hiển thị chữ nghiêng là chức năng của thẻ <i> hoặc <em>. Câu 22. Sử dụng mã HTML nào sau đây sẽ cho kết quả hiển thị trên trang web như hình dưới? A. Đúng. Mã lệnh đúng để hiển thị kết quả theo yêu cầu. B. Sai. list-style-type: disc; tạo dấu chấm tròn, không phải hình vuông. C. Sai. Dùng <ol> là danh sách có thứ tự, thường đánh số, không phù hợp. D. Sai. <ol> là danh sách có thứ tự. Câu 23. Mã CSS nào sau đây thay đổi màu chữ của liên kết sang màu đỏ khi người dùng di chuyển chuột lướt qua? A. Đúng. Cú pháp đúng để thay đổi màu chữ của liên kết khi chuột lướt qua liên kết. B. Sai. hover-color không phải là thuộc tính hợp lệ trong CSS. C. Sai. a:active áp dụng khi liên kết đang được nhấn, không phải lúc di chuột lướt qua. D. Sai. a:visited áp dụng cho liên kết đã được truy cập, không phải hover. Câu 24. Mã HTML nào sau đây tạo một ô nhập liệu trong biểu mẫu mà người dùng chỉ được nhập số và bắt buộc phải nhập? A. Sai. type=\"text\" cho phép nhập chữ và số, nhưng không giới hạn định dạng là số. B. Đúng. Giá trị “number” cho phép nhập số, thuộc tính required là bắt buộc nhập. C. Sai. type=\"number\" đúng định dạng nhưng thiếu required, không bắt buộc phải nhập. D. Sai. type=\"text\" không giới hạn kiểu dữ liệu và cũng thiếu required. Phần II. A. Phần chung cho tất cả các thí sinh Câu 1. Một trường học triển khai hệ thống mạng LAN để kết nối các phòng máy tính, thư viện và văn phòng. Mỗi phòng đều có nhiều máy tính được kết nối qua Switch, trong khi một Router trung tâm được sử dụng để kết nối toàn bộ hệ thống ra Internet. Để mở rộng kết nối cho các thiết bị di động như laptop và điện thoại trong khu vực thư viện và phòng họp, nhà trường sử dụng thêm Access Point. Tuy nhiên, vào giờ cao điểm, mạng thường chậm lại, đặc biệt là khi nhiều người truy cập Internet cùng lúc tại thư viện. Một số ý kiến như sau: a) Đúng. Switch là thiết bị dùng để kết nối các máy tính trong cùng mạng LAN. b) Sai. Router không có chức năng chuyển đổi giữa các chuẩn WiFi. c) Sai. Switch không phát WiFi; mạng chậm tại thư viện có thể do Access Point quá tải. d) Đúng. Khi mất Internet, các thiết bị trong mạng LAN vẫn có thể chia sẻ dữ liệu nội bộ. Câu 2. Công ty 3K vừa triển khai dự án quản lí dữ liệu khách hàng và sản phẩm. Họ được giới thiệu về các hệ quản trị cơ sở dữ liệu (CSDL). Ban quản lí biết rằng hệ CSDL quan hệ lưu trữ dữ liệu dưới dạng bảng, sử dụng ngôn ngữ SQL để truy vấn, phù hợp với dữ liệu có cấu trúc rõ ràng và có các ràng buộc dữ liệu nghiêm ngặt. Một số ý kiến như sau: a) Đúng. Bảng dữ liệu gồm các trường (cột) và bản ghi (hàng) trong CSDL quan hệ. b) Sai. SQL không chỉ truy vấn mà còn hỗ trợ tạo lập, cập nhật và quản lý cơ sở dữ liệu. c) Đúng. Ràng buộc dữ liệu giữa các bảng được thiết lập thông qua khóa ngoại (foreign key). d) Đúng. NoSQL phù hợp để lưu trữ dữ liệu phi cấu trúc như hình ảnh, video và linh hoạt khi mở rộng. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho đoạn chương trình sau: Python C++ def factorial(n): if n == 0: return 1 else: return n * factorial(n - 1) int factorial(int n) { if (n == 0) return 1; else return n * factorial(n - 1); } Một số ý kiến như sau: a) Đúng. Đây là một ví dụ cơ bản của đệ quy tuyến tính vì hàm gọi lại chính nó một lần duy nhất. b) Đúng. Điều kiện dừng if n == 0 giúp tránh vòng lặp vô hạn trong đệ quy. c) Đúng. Độ phức tạp thời gian của hàm là O(n) vì gọi n lần cho đến khi n = 0. d) Sai. Đệ quy gọi lại nhiều lần (như cây đệ quy) sẽ làm chương trình kém tối ưu, tốn tài nguyên hơn. Câu 4. Một nhóm học sinh đang làm dự án nhận diện thư rác bằng mô hình học máy. Họ thu thập dữ liệu từ hộp thư đến và phân loại thành hai nhóm: “Thư thường” và “Thư rác”. Sau khi thu thập, các bạn nhận thấy một số email bị thiếu tiêu đề, một số khác chứa kí tự lạ. Để cải thiện chất lượng dữ liệu, nhóm sử dụng bước xử lí sơ bộ gồm loại bỏ dữ liệu thiếu, chuẩn hoá nội dung và trích xuất các đặc trưng như tần suất từ khoá quảng cáo. Sau khi huấn luyện mô hình, nhóm đánh giá kết quả bằng cách chạy thử trên một tập email mới. Một số ý kiến như sau: a) Đúng. Dữ liệu đầu vào có ảnh hưởng rất lớn đến hiệu quả mô hình học máy. b) Sai. Cần xử lý sơ bộ dữ liệu (loại bỏ thiếu, chuẩn hóa,…) trước khi huấn luyện để đảm bảo chất lượng mô hình. c) Đúng. Tập dữ liệu đầu vào được sử dụng để dạy mô hình gọi là tập huấn luyện (training set). d) Sai. Việc chia dữ liệu thành tập huấn luyện và kiểm tra giúp đánh giá mô hình chính xác hơn, không làm giảm chất lượng thực tế. Câu 5. Công ty Hoàng Khôi muốn xây dựng một trang web giới thiệu sản phẩm thân thiện với người dùng và dễ dàng cập nhật nội dung. Nhóm thiết kế web của công ty được giao nhiệm vụ sử dụng phần mềm tạo trang web để thiết kế giao diện, bố trí các thành phần như hình ảnh, văn bản và liên kết. Họ cũng cần đảm bảo trang web hiển thị tốt trên nhiều thiết bị khác nhau như máy tính và điện thoại di động. Ngoài ra, nhóm phải lưu trữ mã nguồn và dữ liệu một cách hợp lí để dễ bảo trì và nâng cấp trong tương lai. Một số ý kiến như sau: a) Đúng. Phần mềm tạo trang web hỗ trợ kéo thả để thiết kế giao diện nhanh chóng. b) Sai. Thiết kế web cần chú trọng cả bố cục, nội dung và trải nghiệm người dùng (UX), không chỉ là hình ảnh. c) Đúng. Nhiều công cụ hỗ trợ hiển thị tương thích cơ bản (responsive) với các thiết bị khác nhau. d) Đúng. Lưu mã nguồn HTML giúp bảo trì và nâng cấp dễ dàng sau này. Câu 6. Một hệ cơ sở dữ liệu (CSDL) quản lí bán vé máy bay gồm 3 bảng chính: • ChuyenBay(MaCB, NoiDi, NoiDen, GioKhoiHanh) lưu thông tin chuyến bay gồm Mã chuyến bay, Nơi đi, Nơi đến, giờ khởi hành. • KhachHang(MaKH, HoTen, SoDienThoai) lưu thông tin khách hàng đặt vé gồm Mã khách hàng, họ tên, số điện thoại. • VeMayBay(MaVe, MaCB, MaKH, GiaVe) lưu thông tin vé máy bay gồm Mã vé, mã chuyến bay, mã khách hàng, giá vé. Trong quá trình thực hành với hệ CSDL quan hệ này, học sinh đưa ra một số ý kiến sau: a) Đúng. Lệnh CHECK (NoiDi <> NoiDen) giúp đảm bảo dữ liệu hợp lệ khi tạo bảng ChuyenBay. b) Đúng. Trường MaVe là khóa chính nên bắt buộc phải có giá trị, không được để trống. c) Sai. Nếu MaCB là khóa ngoại thì không thể nhập giá trị không tồn tại trong bảng ChuyenBay. d) Đúng. Câu lệnh SQL này sử dụng JOIN chính xác để truy vấn thông tin khách hàng mua vé. -- 14 of 14 --"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c8', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Hệ thống DNS cần thiết trong hoạt động của mạng Internet vì lí do nào sau đây?', '{"A": "Đúng. DNS chuyển địa chỉ IP dạng số sang dạng tên miền giúp người dùng dễ dàng ghi nhớ địa chỉ trang web.", "B": "Sai. Bảo vệ thông tin khi truyền dữ liệu là chức năng của các giao thức bảo mật khác như HTTPS.", "C": "Sai. DNS không giúp ghi nhớ địa chỉ IP.", "D": "Sai. DNS không hỗ trợ việc gửi nhận thư điện tử trực tiếp."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c9', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Trong một công ty có hai mạng cục bộ (LAN) hoạt động độc lập. Sử dụng thiết bị nào sau đây để các máy tính ở hai mạng này có thể truy cập Internet và chia sẻ tài nguyên với nhau?', '{"A": "Đúng. Router là thiết bị kết nối các mạng khác nhau và quản lý truy cập Internet.", "B": "Sai. Modem chuyển đổi tín hiệu mạng, không kết nối hai LAN độc lập.", "C": "Sai. Switch chỉ kết nối các thiết bị trong cùng một LAN.", "D": "Sai. Access Point cung cấp kết nối không dây trong một LAN."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c10', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây thể hiện hành vi ứng xử văn minh trên mạng xã hội?', '{"A": "Sai. Gửi tin nhắn nặc danh xúc phạm là hành vi không văn minh.", "B": "Sai. Chia sẻ thông tin chưa kiểm chứng gây hiểu lầm, không phải ứng xử văn minh.", "C": "Đúng. Bình luận lịch sự, tôn trọng người khác là ứng xử văn minh trên mạng xã hội.", "D": "Sai. Chế giễu người khác qua mạng là hành vi tiêu cực, không văn minh."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c11', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Phương án nào sau đây là hành động nên tránh khi giao tiếp trong không gian mạng?', '{"A": "Đúng. Đăng tải nội dung gây kích động thù ghét là hành vi tiêu cực, vi phạm quy tắc ứng xử văn minh trên không gian mạng.", "B": "Sai. Tôn trọng quyền riêng tư của người khác là hành vi nên thực hiện.", "C": "Sai. Trả lời bình luận một cách ôn hòa giúp tạo môi trường giao tiếp lành mạnh.", "D": "Sai. Sử dụng ngôn ngữ phù hợp là hành vi tích cực và văn minh."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c12', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Lan muốn đăng ảnh và chia sẻ kỷ niệm về chuyến du lịch trên mạng xã hội. Hành động nào sau đây của Lan có thể gây rủi ro đến bảo mật thông tin cá nhân?', '{"A": "Đúng. Chia sẻ ảnh kèm vị trí hiện tại và thông tin hộ chiếu dễ dẫn đến rò rỉ thông tin cá nhân và nguy cơ bị kẻ xấu lợi dụng.", "B": "Sai. Thiết lập quyền riêng tư chỉ cho bạn bè xem giúp kiểm soát người xem bài viết.", "C": "Sai. Đăng hình ảnh về cảnh đẹp mà không tiết lộ thông tin nhạy cảm thường an toàn.", "D": "Sai. Bật xác thực hai yếu tố là biện pháp tăng cường bảo mật tài khoản."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c13', 'de_on_luyen_11', '12G', 'Định hướng nghề nghiệp & Tuyển sinh CNTT', 'single_choice', 'hieu', 'ALL', 'Công việc nào sau đây là nhiệm vụ chính của người làm nghề dịch vụ thuộc ngành CNTT?', '{"A": "Sai. Dạy học là nghề thuộc lĩnh vực giáo dục.", "B": "Sai. Thiết kế đồ họa thuộc lĩnh vực sáng tạo – truyền thông.", "C": "Đúng. Hỗ trợ kỹ thuật, khắc phục sự cố phần cứng là nhiệm vụ của nhân viên dịch vụ trong ngành CNTT.", "D": "Sai. Tổ chức sự kiện công nghệ không phải là nhiệm vụ nghề dịch vụ CNTT."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c14', 'de_on_luyen_11', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'hieu', 'ALL', 'Nhân lực CNTT đóng vai trò quan trọng trong lĩnh vực ngân hàng hiện đại vì lí do nào sau đây?', '{"A": "Đúng. Bảo vệ thông tin khách hàng và duy trì an toàn hệ thống tài chính là trách nhiệm chính của đội ngũ CNTT trong ngân hàng.", "B": "Sai. Làm việc với khách hàng tại quầy là nhiệm vụ của nhân viên giao dịch.", "C": "Sai. Thiết kế sản phẩm đồ họa là công việc của bộ phận truyền thông – marketing.", "D": "Sai. Công việc văn thư hành chính không thuộc chuyên môn CNTT."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c15', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Minh muốn theo học một ngành tập trung vào việc bảo vệ dữ liệu và xử lý các mối đe dọa an ninh mạng trong doanh nghiệp. Ngành học nào sau đây phù hợp nhất với mục tiêu của Minh?', '{"A": "Sai. Khoa học máy tính tập trung vào lý thuyết và lập trình, không chuyên sâu về bảo mật.", "B": "Sai. Mạng máy tính tập trung vào xây dựng hệ thống mạng, ít chuyên sâu về an toàn.", "C": "Đúng. An toàn thông tin là ngành học phù hợp để xử lý các vấn đề về bảo mật dữ liệu và phòng chống mối đe dọa mạng.", "D": "Sai. Công nghệ phần mềm chủ yếu tập trung vào phát triển ứng dụng, không chuyên về bảo mật."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c16', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây mô tả đúng chức năng của thẻ <audio> trong HTML?', '{"A": "Sai. Hiển thị hình ảnh là chức năng của thẻ <img>.", "B": "Đúng. Thẻ <audio> được dùng để nhúng và phát tệp âm thanh trên trang web.", "C": "Sai. Tạo liên kết là chức năng của thẻ <a>.", "D": "Sai. Hiển thị video là chức năng của thẻ <video>."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c17', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'CSS không có vai trò nào sau đây trong thiết kế trang web?', '{"A": "Sai. CSS định dạng kiểu dáng cho phần tử là một chức năng cơ bản.", "B": "Đúng. Xác định cấu trúc và nội dung là nhiệm vụ của HTML, không phải CSS.", "C": "Sai. CSS giúp thay đổi màu sắc, font chữ là chức năng phổ biến.", "D": "Sai. CSS định kiểu cho các trạng thái như hover, active, focus,…"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c18', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Sử dụng thẻ HTML nào sau đây tạo các trường nhập liệu như ô textbox, checkbox, radio trên biểu mẫu?', '{"A": "Sai. <div> chỉ tạo khối chứa, không dùng để tạo trường nhập liệu.", "B": "Sai. <form> định nghĩa biểu mẫu nhưng không trực tiếp tạo trường nhập.", "C": "Đúng. <input> là thẻ được dùng để tạo các loại trường nhập liệu như textbox, checkbox, radio,...", "D": "Sai. <iframe> dùng để nhúng tài liệu khác, không liên quan biểu mẫu."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c19', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Thẻ nào sau đây không bắt bắt buộc có trong trang HTML cơ bản?', '{"A": "Sai. <html> là thẻ bao ngoài, bắt buộc trong mọi tài liệu HTML.", "B": "Sai. <head> chứa thông tin meta, tiêu đề,… là thành phần bắt buộc.", "C": "Sai. <body> chứa nội dung hiển thị chính, cũng bắt buộc.", "D": "Đúng. <h1> là thẻ tiêu đề, không bắt buộc phải có trong mọi trang HTML."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c20', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'hieu', 'ALL', 'Sử dụng mã CSS nào sau đây định kiểu viền màu đỏ, dày 2px, kiểu nét liền cho thẻ <div>?', '{"A": "Đúng. Cú pháp div {border: 2px solid red;} là cách viết đúng và đầy đủ.", "B": "Sai. border-width không thể đi kèm solid như trong ví dụ.", "C": "Sai. Thứ tự không chuẩn.", "D": "Sai. border-style cần được tách riêng hoặc nằm trong thuộc tính border."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c21', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Phương án nào sau đây đúng về vai trò của thẻ <mark> khi sử dụng trong văn bản HTML?', '{"A": "Sai. In đậm là chức năng của thẻ <strong> hoặc <b>.", "B": "Đúng. Thẻ <mark> được dùng để đánh dấu và làm nổi bật đoạn văn bản, thường có nền màu vàng.", "C": "Sai. Chèn liên kết là chức năng của thẻ <a>.", "D": "Sai. Hiển thị chữ nghiêng là chức năng của thẻ <i> hoặc <em>."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c22', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Sử dụng mã HTML nào sau đây sẽ cho kết quả hiển thị trên trang web như hình dưới?', '{"A": "Đúng. Mã lệnh đúng để hiển thị kết quả theo yêu cầu.", "B": "Sai. list-style-type: disc; tạo dấu chấm tròn, không phải hình vuông.", "C": "Sai. Dùng <ol> là danh sách có thứ tự, thường đánh số, không phù hợp.", "D": "Sai. <ol> là danh sách có thứ tự."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c23', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Mã CSS nào sau đây thay đổi màu chữ của liên kết sang màu đỏ khi người dùng di chuyển chuột lướt qua?', '{"A": "Đúng. Cú pháp đúng để thay đổi màu chữ của liên kết khi chuột lướt qua liên kết.", "B": "Sai. hover-color không phải là thuộc tính hợp lệ trong CSS.", "C": "Sai. a:active áp dụng khi liên kết đang được nhấn, không phải lúc di chuột lướt qua.", "D": "Sai. a:visited áp dụng cho liên kết đã được truy cập, không phải hover."}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('de_on_luyen_11_p1_c24', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'van_dung', 'ALL', 'Mã HTML nào sau đây tạo một ô nhập liệu trong biểu mẫu mà người dùng chỉ được nhập số và bắt buộc phải nhập?', '{"A": "Sai. type=\"text\" cho phép nhập chữ và số, nhưng không giới hạn định dạng là số.", "B": "Đúng. Giá trị “number” cho phép nhập số, thuộc tính required là bắt buộc nhập.", "C": "Sai. type=\"number\" đúng định dạng nhưng thiếu required, không bắt buộc phải nhập.", "D": "Sai. type=\"text\" không giới hạn kiểu dữ liệu và cũng thiếu required. Phần II. A. Phần chung cho tất cả các thí sinh Câu 1. Một trường học triển khai hệ thống mạng LAN để kết nối các phòng máy tính, thư viện và văn phòng. Mỗi phòng đều có nhiều máy tính được kết nối qua Switch, trong khi một Router trung tâm được sử dụng để kết nối toàn bộ hệ thống ra Internet. Để mở rộng kết nối cho các thiết bị di động như laptop và điện thoại trong khu vực thư viện và phòng họp, nhà trường sử dụng thêm Access Point. Tuy nhiên, vào giờ cao điểm, mạng thường chậm lại, đặc biệt là khi nhiều người truy cập Internet cùng lúc tại thư viện. Một số ý kiến như sau: a) Đúng. Switch là thiết bị dùng để kết nối các máy tính trong cùng mạng LAN. b) Sai. Router không có chức năng chuyển đổi giữa các chuẩn WiFi. c) Sai. Switch không phát WiFi; mạng chậm tại thư viện có thể do Access Point quá tải. d) Đúng. Khi mất Internet, các thiết bị trong mạng LAN vẫn có thể chia sẻ dữ liệu nội bộ. Câu 2. Công ty 3K vừa triển khai dự án quản lí dữ liệu khách hàng và sản phẩm. Họ được giới thiệu về các hệ quản trị cơ sở dữ liệu (CSDL). Ban quản lí biết rằng hệ CSDL quan hệ lưu trữ dữ liệu dưới dạng bảng, sử dụng ngôn ngữ SQL để truy vấn, phù hợp với dữ liệu có cấu trúc rõ ràng và có các ràng buộc dữ liệu nghiêm ngặt. Một số ý kiến như sau: a) Đúng. Bảng dữ liệu gồm các trường (cột) và bản ghi (hàng) trong CSDL quan hệ. b) Sai. SQL không chỉ truy vấn mà còn hỗ trợ tạo lập, cập nhật và quản lý cơ sở dữ liệu. c) Đúng. Ràng buộc dữ liệu giữa các bảng được thiết lập thông qua khóa ngoại (foreign key). d) Đúng. NoSQL phù hợp để lưu trữ dữ liệu phi cấu trúc như hình ảnh, video và linh hoạt khi mở rộng. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho đoạn chương trình sau: Python C++ def factorial(n): if n == 0: return 1 else: return n * factorial(n - 1) int factorial(int n) { if (n == 0) return 1; else return n * factorial(n - 1); } Một số ý kiến như sau: a) Đúng. Đây là một ví dụ cơ bản của đệ quy tuyến tính vì hàm gọi lại chính nó một lần duy nhất. b) Đúng. Điều kiện dừng if n == 0 giúp tránh vòng lặp vô hạn trong đệ quy. c) Đúng. Độ phức tạp thời gian của hàm là O(n) vì gọi n lần cho đến khi n = 0. d) Sai. Đệ quy gọi lại nhiều lần (như cây đệ quy) sẽ làm chương trình kém tối ưu, tốn tài nguyên hơn. Câu 4. Một nhóm học sinh đang làm dự án nhận diện thư rác bằng mô hình học máy. Họ thu thập dữ liệu từ hộp thư đến và phân loại thành hai nhóm: “Thư thường” và “Thư rác”. Sau khi thu thập, các bạn nhận thấy một số email bị thiếu tiêu đề, một số khác chứa kí tự lạ. Để cải thiện chất lượng dữ liệu, nhóm sử dụng bước xử lí sơ bộ gồm loại bỏ dữ liệu thiếu, chuẩn hoá nội dung và trích xuất các đặc trưng như tần suất từ khoá quảng cáo. Sau khi huấn luyện mô hình, nhóm đánh giá kết quả bằng cách chạy thử trên một tập email mới. Một số ý kiến như sau: a) Đúng. Dữ liệu đầu vào có ảnh hưởng rất lớn đến hiệu quả mô hình học máy. b) Sai. Cần xử lý sơ bộ dữ liệu (loại bỏ thiếu, chuẩn hóa,…) trước khi huấn luyện để đảm bảo chất lượng mô hình. c) Đúng. Tập dữ liệu đầu vào được sử dụng để dạy mô hình gọi là tập huấn luyện (training set). d) Sai. Việc chia dữ liệu thành tập huấn luyện và kiểm tra giúp đánh giá mô hình chính xác hơn, không làm giảm chất lượng thực tế. Câu 5. Công ty Hoàng Khôi muốn xây dựng một trang web giới thiệu sản phẩm thân thiện với người dùng và dễ dàng cập nhật nội dung. Nhóm thiết kế web của công ty được giao nhiệm vụ sử dụng phần mềm tạo trang web để thiết kế giao diện, bố trí các thành phần như hình ảnh, văn bản và liên kết. Họ cũng cần đảm bảo trang web hiển thị tốt trên nhiều thiết bị khác nhau như máy tính và điện thoại di động. Ngoài ra, nhóm phải lưu trữ mã nguồn và dữ liệu một cách hợp lí để dễ bảo trì và nâng cấp trong tương lai. Một số ý kiến như sau: a) Đúng. Phần mềm tạo trang web hỗ trợ kéo thả để thiết kế giao diện nhanh chóng. b) Sai. Thiết kế web cần chú trọng cả bố cục, nội dung và trải nghiệm người dùng (UX), không chỉ là hình ảnh. c) Đúng. Nhiều công cụ hỗ trợ hiển thị tương thích cơ bản (responsive) với các thiết bị khác nhau. d) Đúng. Lưu mã nguồn HTML giúp bảo trì và nâng cấp dễ dàng sau này. Câu 6. Một hệ cơ sở dữ liệu (CSDL) quản lí bán vé máy bay gồm 3 bảng chính: • ChuyenBay(MaCB, NoiDi, NoiDen, GioKhoiHanh) lưu thông tin chuyến bay gồm Mã chuyến bay, Nơi đi, Nơi đến, giờ khởi hành. • KhachHang(MaKH, HoTen, SoDienThoai) lưu thông tin khách hàng đặt vé gồm Mã khách hàng, họ tên, số điện thoại. • VeMayBay(MaVe, MaCB, MaKH, GiaVe) lưu thông tin vé máy bay gồm Mã vé, mã chuyến bay, mã khách hàng, giá vé. Trong quá trình thực hành với hệ CSDL quan hệ này, học sinh đưa ra một số ý kiến sau: a) Đúng. Lệnh CHECK (NoiDi <> NoiDen) giúp đảm bảo dữ liệu hợp lệ khi tạo bảng ChuyenBay. b) Đúng. Trường MaVe là khóa chính nên bắt buộc phải có giá trị, không được để trống. c) Sai. Nếu MaCB là khóa ngoại thì không thể nhập giá trị không tồn tại trong bảng ChuyenBay. d) Đúng. Câu lệnh SQL này sử dụng JOIN chính xác để truy vấn thông tin khách hàng mua vé. -- 14 of 14 --"}'::jsonb, 'A', NULL) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;

-- Câu hỏi Phần II của de_on_luyen_11
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c1', 'de_on_luyen_11', '12B', 'Mạng máy tính và Internet', 'true_false_group', 'hieu', 'ALL', 'Phương án nào sau đây mô tả chức năng của trí tuệ nhân tạo? A. Lưu trữ dữ liệu lớn. B. Thực hiện các tác vụ thông minh. C. Kết nối mạng xã hội. D. Tạo ra phần mềm văn phòng.', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c2', 'de_on_luyen_11', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Trí tuệ nhân tạo (AI) không thể thực hiện nhiệm vụ nào sau đây? A. Nhận dạng giọng nói. B. Chẩn đoán bệnh qua hình ảnh y tế. C. Phân tích dữ liệu lớn (Big Dat', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c3', 'de_on_luyen_11', '11F_CS', 'Thuật toán và Kĩ thuật lập trình', 'true_false_group', 'hieu', 'CS', 'Ứng dụng có tích hợp AI nào sau đây có thể bị dùng để giả mạo danh tính trong video lừa đảo, tống tiền, hoặc đánh lừa hệ thống xác thực bằng khuôn mặt? A. DeepFaceLab B. AutoSploit C. Chat GPT D. AI-Powered Phishing Tools Câu 4: Một ngân hàng muốn sử dụng trí tuệ nhân tạo (AI) để giảm thiểu rủi ro từ các giao dịch gian lận. Phương án nào sau đây là ứng dụng phù hợp của AI để hỗ trợ mục tiêu này? A. Tạo giao diện website thân thiện hơn với người dùng. B. Dự đoán xu hướng đầu tư dài hạn. C. Phân tích hành vi giao dịch để phát hiện giao dịch bất thường. D. Tự động in sao kê tài khoản cho khách hàng. Câu 5. Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ def kt_ngto(n): if n < 2: return 0 for i in range(2, int(n**0.5) + 1): if n % i == 0: return 0 return 1 bool kt_ngto(int n) { if (n < 2) return 0; int limit = int(sqrt(n)); for (int i = 2; i <= limit; i++) { if (n % i == 0) return 0; } return 1; } Phương án nào sau đây là giá trị của hàm kt_ngto khi truyền tham số n bằng 13? A. False B. True C. 1 D. 0 Câu 6. Giao thức nào sau đây xử lý việc truyền email giữa các máy chủ? A. SMTP. B. POP3. C. IMAP. D. HTTPS. Câu 7: Phương án nào sau đây mô tả đúng chức năng của địa chỉ MAC trong mạng máy tính? A. Xác định địa chỉ vật lý của thiết bị mạng. B. Kết nối Internet tốc độ cao. C. Mã hóa dữ liệu khi truyền qua mạng. D. Định danh thiết bị trên mạng Internet. Câu 8. Hệ thống DNS cần thiết trong hoạt động của mạng Internet vì lí do nào sau đây? A. Giúp người dùng dễ dàng ghi nhớ địa chỉ trang web qua tên miền. B. Bảo vệ thông tin người dùng khi truyền dữ liệu trên Internet. C. Giúp người dùng dễ dàng ghi nhớ địa chỉ IP của trang web. D. Hỗ trợ người dùng kiểm soát việc gửi và nhận thư điện tử. Câu 9. Trong một công ty có hai mạng cục bộ (LAN) hoạt động độc lập. Sử dụng thiết bị nào sau đây để các máy tính ở hai mạng này có thể truy cập Internet và chia sẻ tài nguyên với nhau? A. Router B. Modem C. Switch D. Access Point Câu 10. Phương án nào sau đây thể hiện hành vi ứng xử văn minh trên mạng xã hội? A. Gửi tin nhắn nặc danh xúc phạm. B. Chia sẻ thông tin chưa kiểm chứng. C. Bình luận lịch sự, tôn trọng người khác. D. Chế giễu người khác qua mạng. Câu 11. Phương án nào sau đây là hành động nên tránh khi giao tiếp trong không gian mạng? A. Đăng tải nội dung gây kích động thù ghét. B. Tôn trọng quyền riêng tư của người khác. C. Trả lời bình luận một cách ôn hòa. D. Sử dụng ngôn ngữ phù hợp. Câu 12. Lan muốn đăng ảnh và chia sẻ kỷ niệm về chuyến du lịch trên mạng xã hội. Hành động nào sau đây của Lan có thể gây rủi ro đến bảo mật thông tin cá nhân? A. Chia sẻ ảnh kèm vị trí hiện tại và thông tin hộ chiếu. B. Thiết lập quyền riêng tư chỉ bạn bè xem được bài viết. C. Đăng một số hình ảnh về cảnh đẹp trong chuyến du lịch. D. Bật xác thực hai yếu tố cho tài khoản trước khi đăng bài. Câu 13. Công việc nào sau đây là nhiệm vụ chính của người làm nghề dịch vụ thuộc ngành CNTT? A. Dạy học về lập trình web. B. Thiết kế đồ họa và sáng tạo nội dung. C. Hỗ trợ kĩ thuật, khắc phục sự cố phần cứng. D. Tổ chức sự kiện công nghệ. Câu 14. Nhân lực CNTT đóng vai trò quan trọng trong lĩnh vực ngân hàng hiện đại vì lí do nào sau đây? A. Bảo vệ thông tin khách hàng và duy trì an toàn hệ thống tài chính. B. Làm việc với khách hàng trực tiếp tại quầy giao dịch. C. Phụ trách thiết kế các sản phẩm đồ họa quảng cáo cho ngân hàng. D. Thực hiện các công việc văn thư hành chính trong ngân hàng. Câu 15. Minh muốn theo học một ngành tập trung vào việc bảo vệ dữ liệu và xử lý các mối đe dọa an ninh mạng trong doanh nghiệp. Ngành học nào sau đây phù hợp nhất với mục tiêu của Minh? A. Khoa học máy tính. B. Mạng máy tính. C. An toàn thông tin. D. Công nghệ phần mềm. Câu 16. Phương án nào sau đây mô tả đúng chức năng của thẻ <audio> trong HTML? A. Hiển thị hình ảnh trên trang web. B. Nhúng tệp âm thanh vào trang web. C. Tạo liên kết đến trang khác. D. Hiển thị video trên trang web. Câu 17. CSS không có vai trò nào sau đây trong thiết kế trang web? A. Định dạng kiểu dáng cho các phần tử. B. Xác định cấu trúc và nội dung của trang web. C. Thay đổi màu sắc, font chữ của văn bản. D. Định kiểu cho các trạng thái khác nhau của phần tử. Câu 18. Sử dụng thẻ HTML nào sau đây tạo các trường nhập liệu như ô textbox, checkbox, radio trên biểu mẫu? A. <div> B. <form> C. <input> D. <iframe> Câu 19. Thẻ nào sau đây không bắt bắt buộc có trong trang HTML cơ bản? A. <html> B. <head> C. <body> D. <h1> Câu 20. Sử dụng mã CSS nào sau đây định kiểu viền màu đỏ, dày 2px, kiểu nét liền cho thẻ <div>? A. div {border: 2px solid red;} B. div {border-color: red; border-width: 2px solid;} C. div {border: red 2px solid;} D. div {border-style: solid; border: 2px red;} Câu 21. Phương án nào sau đây đúng về vai trò của thẻ <mark> khi sử dụng trong văn bản HTML? A. Tạo đoạn văn bản in đậm. B. Đánh dấu và làm nổi bật đoạn văn bản. C. Chèn liên kết đến trang khác. D. Hiển thị đoạn văn bản ở dạng chữ nghiêng. Câu 22. Sử dụng mã HTML nào sau đây sẽ cho kết quả hiển thị trên trang web như hình dưới? A. <ul style="list-style-type: square;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ul> B. <ul style="list-style-type: disc;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ul> D. <ol style="list-style-type: square;"> C. <ol style="list-style-type: circle;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ol> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ol> Câu 23. Mã CSS nào sau đây thay đổi màu chữ của liên kết sang màu đỏ khi người dùng di chuyển chuột lướt qua? A. a:hover {color: red;} B. a {hover-color: red;} C. a:active {color: red;} D. a:visited {color: red;} Câu 24. Mã HTML nào sau đây tạo một ô nhập liệu trong biểu mẫu mà người dùng chỉ được nhập số và bắt buộc phải nhập? A. <input type="text" required> B. <input type="number" required> C. <input type="number"> D. <input type="text"> Phần II. Trắc nghiệm dạng đúng sai (4 điểm): Thí sinh trả lời 4 câu hỏi cho phần thi tương ứng: Mỗi câu hỏi thí sinh tô vào ô tương ứng với đúng hoặc sai đối với mỗi ý trong từng câu hỏi của đề. A. Phần chung cho tất cả các thí sinh Câu 1. Một trường học triển khai hệ thống mạng LAN để kết nối các phòng máy tính, thư viện và văn phòng. Mỗi phòng đều có nhiều máy tính được kết nối qua Switch, trong khi một Router trung tâm được sử dụng để kết nối toàn bộ hệ thống ra Internet. Để mở rộng kết nối cho các thiết bị di động như laptop và điện thoại trong khu vực thư viện và phòng họp, nhà trường sử dụng thêm Access Point. Tuy nhiên, vào giờ cao điểm, mạng thường chậm lại, đặc biệt là khi nhiều người truy cập Internet cùng lúc tại thư viện. Một số ý kiến như sau:', '[{"id": "a", "text": "Switch là thiết bị dùng để kết nối các máy tính trong cùng mạng LAN.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Router có vai trò chuyển đổi tín hiệu giữa các chuẩn Wifi khác nhau.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mạng chậm tại thư viện là do thiết bị Switch không đủ mạnh để phát sóng Wifi cho toàn bộ khu vực.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Khi mất tín hiệu Internet, các máy tính trong văn phòng vẫn chia sẻ dữ liệu nội bộ được cho nhau. Câu 2. Công ty 3K vừa triển khai dự án quản lí dữ liệu khách hàng và sản phẩm. Họ được giới thiệu về các hệ quản trị cơ sở dữ liệu (CSDL). Ban quản lí biết rằng hệ CSDL quan hệ lưu trữ dữ liệu dưới dạng bảng, sử dụng ngôn ngữ SQL để truy vấn, phù hợp với dữ liệu có cấu trúc rõ ràng và có các ràng buộc dữ liệu nghiêm ngặt. Một số ý kiến như sau: a) Bảng dữ liệu trong CSDL quan hệ gồm các trường và bản ghi. b) Ngôn ngữ SQL chỉ hỗ trợ truy vấn, cần dùng công cụ khác để tạo lập và cập nhật CSDL. c) Ràng buộc dữ liệu giữa các bảng thông qua khóa ngoại. d) Công ty 3K nên cân nhắc sử dụng hệ quản trị NoSQL để lưu trữ dữ liệu phi cấu trúc như hình ảnh, video và mở rộng linh hoạt. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho đoạn chương trình sau: Python C++ def factorial(n): if n == 0: return 1 else: return n * factorial(n - 1) int factorial(int n) { if (n == 0) return 1; else return n * factorial(n - 1); } Một số ý kiến như sau: a) Hàm factorial(n) là một ví dụ cơ bản của đệ quy tuyến tính. b) Hàm có điều kiện dừng khi n == 0 để tránh gọi vô hạn. c) Độ phức tạp thời gian của hàm là O(n), vì mỗi lần gọi giảm n đi 1. d) Để tối ưu chương trình, Nam nên thay đệ quy bằng đệ quy gọi lại chính nó nhiều lần (recursion tree).", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c4', 'de_on_luyen_11', '12F_CS', 'Khoa học dữ liệu & Học máy nâng cao', 'true_false_group', 'hieu', 'CS', 'Một nhóm học sinh đang làm dự án nhận diện thư rác bằng mô hình học máy. Họ thu thập dữ liệu từ hộp thư đến và phân loại thành hai nhóm: “Thư thường” và “Thư rác”. Sau khi thu thập, các bạn nhận thấy một số email bị thiếu tiêu đề, một số khác chứa kí tự lạ. Để cải thiện chất lượng dữ liệu, nhóm sử dụng bước xử lí sơ bộ gồm loại bỏ dữ liệu thiếu, chuẩn hoá nội dung và trích xuất các đặc trưng như tần suất từ khoá quảng cáo. Sau khi huấn luyện mô hình, nhóm đánh giá kết quả bằng cách chạy thử trên một tập email mới. Một số ý kiến như sau:', '[{"id": "a", "text": "Dữ liệu đầu vào là yếu tố rất quan trọng ảnh hưởng đến chất lượng mô hình học máy.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Không cần xử lí sơ bộ dữ liệu trước khi huấn luyện mô hình.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Dữ liệu đầu vào của mô hình được gọi là tập huấn luyện.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Việc chia dữ liệu thành hai tập: huấn luyện và kiểm tra sẽ làm giảm độ chính xác của mô hình.", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c5', 'de_on_luyen_11', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để xem xét đoạn chương trình sau: Đoạn chương trình viết bằng ngôn ngữ Python Đoạn chương trình viết bằng ngôn ngữ C++ def kt_ngto(n): if n < 2: return 0 for i in range(2, int(n**0.5) + 1): if n % i == 0: return 0 return 1 bool kt_ngto(int n) { if (n < 2) return 0; int limit = int(sqrt(n)); for (int i = 2; i <= limit; i++) { if (n % i == 0) return 0; } return 1; } Phương án nào sau đây là giá trị của hàm kt_ngto khi truyền tham số n bằng 13? A. False B. True C. 1 D. 0', '[{"id": "a", "text": "Mệnh đề a", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Mệnh đề b", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mệnh đề c", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Mệnh đề d", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('de_on_luyen_11_p2_c6', 'de_on_luyen_11', '11F', 'Hệ cơ sở dữ liệu và Truy vấn SQL', 'true_false_group', 'hieu', 'ALL', 'Giao thức nào sau đây xử lý việc truyền email giữa các máy chủ? A. SMTP. B. POP3. C. IMAP. D. HTTPS. Câu 7: Phương án nào sau đây mô tả đúng chức năng của địa chỉ MAC trong mạng máy tính? A. Xác định địa chỉ vật lý của thiết bị mạng. B. Kết nối Internet tốc độ cao. C. Mã hóa dữ liệu khi truyền qua mạng. D. Định danh thiết bị trên mạng Internet. Câu 8. Hệ thống DNS cần thiết trong hoạt động của mạng Internet vì lí do nào sau đây? A. Giúp người dùng dễ dàng ghi nhớ địa chỉ trang web qua tên miền. B. Bảo vệ thông tin người dùng khi truyền dữ liệu trên Internet. C. Giúp người dùng dễ dàng ghi nhớ địa chỉ IP của trang web. D. Hỗ trợ người dùng kiểm soát việc gửi và nhận thư điện tử. Câu 9. Trong một công ty có hai mạng cục bộ (LAN) hoạt động độc lập. Sử dụng thiết bị nào sau đây để các máy tính ở hai mạng này có thể truy cập Internet và chia sẻ tài nguyên với nhau? A. Router B. Modem C. Switch D. Access Point Câu 10. Phương án nào sau đây thể hiện hành vi ứng xử văn minh trên mạng xã hội? A. Gửi tin nhắn nặc danh xúc phạm. B. Chia sẻ thông tin chưa kiểm chứng. C. Bình luận lịch sự, tôn trọng người khác. D. Chế giễu người khác qua mạng. Câu 11. Phương án nào sau đây là hành động nên tránh khi giao tiếp trong không gian mạng? A. Đăng tải nội dung gây kích động thù ghét. B. Tôn trọng quyền riêng tư của người khác. C. Trả lời bình luận một cách ôn hòa. D. Sử dụng ngôn ngữ phù hợp. Câu 12. Lan muốn đăng ảnh và chia sẻ kỷ niệm về chuyến du lịch trên mạng xã hội. Hành động nào sau đây của Lan có thể gây rủi ro đến bảo mật thông tin cá nhân? A. Chia sẻ ảnh kèm vị trí hiện tại và thông tin hộ chiếu. B. Thiết lập quyền riêng tư chỉ bạn bè xem được bài viết. C. Đăng một số hình ảnh về cảnh đẹp trong chuyến du lịch. D. Bật xác thực hai yếu tố cho tài khoản trước khi đăng bài. Câu 13. Công việc nào sau đây là nhiệm vụ chính của người làm nghề dịch vụ thuộc ngành CNTT? A. Dạy học về lập trình web. B. Thiết kế đồ họa và sáng tạo nội dung. C. Hỗ trợ kĩ thuật, khắc phục sự cố phần cứng. D. Tổ chức sự kiện công nghệ. Câu 14. Nhân lực CNTT đóng vai trò quan trọng trong lĩnh vực ngân hàng hiện đại vì lí do nào sau đây? A. Bảo vệ thông tin khách hàng và duy trì an toàn hệ thống tài chính. B. Làm việc với khách hàng trực tiếp tại quầy giao dịch. C. Phụ trách thiết kế các sản phẩm đồ họa quảng cáo cho ngân hàng. D. Thực hiện các công việc văn thư hành chính trong ngân hàng. Câu 15. Minh muốn theo học một ngành tập trung vào việc bảo vệ dữ liệu và xử lý các mối đe dọa an ninh mạng trong doanh nghiệp. Ngành học nào sau đây phù hợp nhất với mục tiêu của Minh? A. Khoa học máy tính. B. Mạng máy tính. C. An toàn thông tin. D. Công nghệ phần mềm. Câu 16. Phương án nào sau đây mô tả đúng chức năng của thẻ <audio> trong HTML? A. Hiển thị hình ảnh trên trang web. B. Nhúng tệp âm thanh vào trang web. C. Tạo liên kết đến trang khác. D. Hiển thị video trên trang web. Câu 17. CSS không có vai trò nào sau đây trong thiết kế trang web? A. Định dạng kiểu dáng cho các phần tử. B. Xác định cấu trúc và nội dung của trang web. C. Thay đổi màu sắc, font chữ của văn bản. D. Định kiểu cho các trạng thái khác nhau của phần tử. Câu 18. Sử dụng thẻ HTML nào sau đây tạo các trường nhập liệu như ô textbox, checkbox, radio trên biểu mẫu? A. <div> B. <form> C. <input> D. <iframe> Câu 19. Thẻ nào sau đây không bắt bắt buộc có trong trang HTML cơ bản? A. <html> B. <head> C. <body> D. <h1> Câu 20. Sử dụng mã CSS nào sau đây định kiểu viền màu đỏ, dày 2px, kiểu nét liền cho thẻ <div>? A. div {border: 2px solid red;} B. div {border-color: red; border-width: 2px solid;} C. div {border: red 2px solid;} D. div {border-style: solid; border: 2px red;} Câu 21. Phương án nào sau đây đúng về vai trò của thẻ <mark> khi sử dụng trong văn bản HTML? A. Tạo đoạn văn bản in đậm. B. Đánh dấu và làm nổi bật đoạn văn bản. C. Chèn liên kết đến trang khác. D. Hiển thị đoạn văn bản ở dạng chữ nghiêng. Câu 22. Sử dụng mã HTML nào sau đây sẽ cho kết quả hiển thị trên trang web như hình dưới? A. <ul style="list-style-type: square;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ul> B. <ul style="list-style-type: disc;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ul> D. <ol style="list-style-type: square;"> C. <ol style="list-style-type: circle;"> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ol> <li>Hoa đào</li> <li>Hoa mai</li><li>Hoa cúc</li> </ol> Câu 23. Mã CSS nào sau đây thay đổi màu chữ của liên kết sang màu đỏ khi người dùng di chuyển chuột lướt qua? A. a:hover {color: red;} B. a {hover-color: red;} C. a:active {color: red;} D. a:visited {color: red;} Câu 24. Mã HTML nào sau đây tạo một ô nhập liệu trong biểu mẫu mà người dùng chỉ được nhập số và bắt buộc phải nhập? A. <input type="text" required> B. <input type="number" required> C. <input type="number"> D. <input type="text"> Phần II. Trắc nghiệm dạng đúng sai (4 điểm): Thí sinh trả lời 4 câu hỏi cho phần thi tương ứng: Mỗi câu hỏi thí sinh tô vào ô tương ứng với đúng hoặc sai đối với mỗi ý trong từng câu hỏi của đề. A. Phần chung cho tất cả các thí sinh Câu 1. Một trường học triển khai hệ thống mạng LAN để kết nối các phòng máy tính, thư viện và văn phòng. Mỗi phòng đều có nhiều máy tính được kết nối qua Switch, trong khi một Router trung tâm được sử dụng để kết nối toàn bộ hệ thống ra Internet. Để mở rộng kết nối cho các thiết bị di động như laptop và điện thoại trong khu vực thư viện và phòng họp, nhà trường sử dụng thêm Access Point. Tuy nhiên, vào giờ cao điểm, mạng thường chậm lại, đặc biệt là khi nhiều người truy cập Internet cùng lúc tại thư viện. Một số ý kiến như sau:', '[{"id": "a", "text": "Switch là thiết bị dùng để kết nối các máy tính trong cùng mạng LAN.", "isCorrect": true, "explanation": "Mệnh đề (a) là Đúng."}, {"id": "b", "text": "Router có vai trò chuyển đổi tín hiệu giữa các chuẩn Wifi khác nhau.", "isCorrect": false, "explanation": "Mệnh đề (b) là Sai."}, {"id": "c", "text": "Mạng chậm tại thư viện là do thiết bị Switch không đủ mạnh để phát sóng Wifi cho toàn bộ khu vực.", "isCorrect": true, "explanation": "Mệnh đề (c) là Đúng."}, {"id": "d", "text": "Khi mất tín hiệu Internet, các máy tính trong văn phòng vẫn chia sẻ dữ liệu nội bộ được cho nhau. Câu 2. Công ty 3K vừa triển khai dự án quản lí dữ liệu khách hàng và sản phẩm. Họ được giới thiệu về các hệ quản trị cơ sở dữ liệu (CSDL). Ban quản lí biết rằng hệ CSDL quan hệ lưu trữ dữ liệu dưới dạng bảng, sử dụng ngôn ngữ SQL để truy vấn, phù hợp với dữ liệu có cấu trúc rõ ràng và có các ràng buộc dữ liệu nghiêm ngặt. Một số ý kiến như sau: a) Bảng dữ liệu trong CSDL quan hệ gồm các trường và bản ghi. b) Ngôn ngữ SQL chỉ hỗ trợ truy vấn, cần dùng công cụ khác để tạo lập và cập nhật CSDL. c) Ràng buộc dữ liệu giữa các bảng thông qua khóa ngoại. d) Công ty 3K nên cân nhắc sử dụng hệ quản trị NoSQL để lưu trữ dữ liệu phi cấu trúc như hình ảnh, video và mở rộng linh hoạt. B. Phần riêng Thí sinh chỉ chọn một trong hai phần sau: Thí sinh theo định hướng Khoa học máy tính làm câu 3 và 4; Thí sinh theo định hướng Tin học ứng dụng làm câu 5 và 6. Câu 3. Cho đoạn chương trình sau: Python C++ def factorial(n): if n == 0: return 1 else: return n * factorial(n - 1) int factorial(int n) { if (n == 0) return 1; else return n * factorial(n - 1); } Một số ý kiến như sau: a) Hàm factorial(n) là một ví dụ cơ bản của đệ quy tuyến tính. b) Hàm có điều kiện dừng khi n == 0 để tránh gọi vô hạn. c) Độ phức tạp thời gian của hàm là O(n), vì mỗi lần gọi giảm n đi 1. d) Để tối ưu chương trình, Nam nên thay đệ quy bằng đệ quy gọi lại chính nó nhiều lần (recursion tree). Câu 4. Một nhóm học sinh đang làm dự án nhận diện thư rác bằng mô hình học máy. Họ thu thập dữ liệu từ hộp thư đến và phân loại thành hai nhóm: “Thư thường” và “Thư rác”. Sau khi thu thập, các bạn nhận thấy một số email bị thiếu tiêu đề, một số khác chứa kí tự lạ. Để cải thiện chất lượng dữ liệu, nhóm sử dụng bước xử lí sơ bộ gồm loại bỏ dữ liệu thiếu, chuẩn hoá nội dung và trích xuất các đặc trưng như tần suất từ khoá quảng cáo. Sau khi huấn luyện mô hình, nhóm đánh giá kết quả bằng cách chạy thử trên một tập email mới. Một số ý kiến như sau: a) Dữ liệu đầu vào là yếu tố rất quan trọng ảnh hưởng đến chất lượng mô hình học máy. b) Không cần xử lí sơ bộ dữ liệu trước khi huấn luyện mô hình. c) Dữ liệu đầu vào của mô hình được gọi là tập huấn luyện. d) Việc chia dữ liệu thành hai tập: huấn luyện và kiểm tra sẽ làm giảm độ chính xác của mô hình. Câu 5. Công ty Hoàng Khôi muốn xây dựng một trang web giới thiệu sản phẩm thân thiện với người dùng và dễ dàng cập nhật nội dung. Nhóm thiết kế web của công ty được giao nhiệm vụ sử dụng phần mềm tạo trang web để thiết kế giao diện, bố trí các thành phần như hình ảnh, văn bản và liên kết. Họ cũng cần đảm bảo trang web hiển thị tốt trên nhiều thiết bị khác nhau như máy tính và điện thoại di động. Ngoài ra, nhóm phải lưu trữ mã nguồn và dữ liệu một cách hợp lí để dễ bảo trì và nâng cấp trong tương lai. Một số ý kiến như sau: a) Phần mềm tạo trang web thường hỗ trợ kéo thả các thành phần, giúp thiết kế giao diện nhanh và đơn giản. b) Thiết kế website chỉ cần tập trung vào màu sắc và hình ảnh, không cần quan tâm đến bố cục hay trải nghiệm người dùng. c) Các phần mềm tạo trang web tự động điều chỉnh ở mức cơ bản chế độ hiển thị trang web trên các thiết bị khác nhau. d) Có thể lưu trang web dưới dạng mã nguồn HTML để lưu trữ và nâng cấp trong tương lai. Câu 6. Một hệ cơ sở dữ liệu (CSDL) quản lí bán vé máy bay gồm 3 bảng chính: • ChuyenBay(MaCB, NoiDi, NoiDen, GioKhoiHanh) lưu thông tin chuyến bay gồm Mã chuyến bay, Nơi đi, Nơi đến, giờ khởi hành. • KhachHang(MaKH, HoTen, SoDienThoai) lưu thông tin khách hàng đặt vé gồm Mã khách hàng, họ tên, số điện thoại. • VeMayBay(MaVe, MaCB, MaKH, GiaVe) lưu thông tin vé máy bay gồm Mã vé, mã chuyến bay, mã khách hàng, giá vé. Trong quá trình thực hành với hệ CSDL quan hệ này, học sinh đưa ra một số ý kiến sau: a) Cần thêm lệnh CHECK (NoiDi <> NoiDen) khi tạo bảng ChuyenBay để đảm bảo sân bay khởi hành khác với sân bay đến. b) Khi nhập dữ liệu bảng VeMayBay, không được để trống trường MaVe. c) Có thể thêm một bản ghi vào bảng VeMayBay với MaCB không tồn tại trong bảng ChuyenBay. d) Để hiển thị danh sách khách hàng đã mua vé máy bay, sử dụng câu lệnh truy vấn sau: SELECT KhachHang.HoTen, KhachHang.SoDienThoai FROM KhachHang JOIN VeMayBay ON KhachHang.MaKH = VeMayBay.MaKH; ---Hết---", "isCorrect": false, "explanation": "Mệnh đề (d) là Sai."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;

-- Cập nhật thống kê total_questions trong topics
UPDATE public.topics t SET total_questions = (SELECT COUNT(*) FROM public.questions q WHERE q.topic_id = t.id);

-- ==============================================================================
-- 5. NẠP DỮ LIỆU TRI THỨC SGK TIN HỌC 11 & 12 (KNOWLEDGE_CHUNKS CHO AI RAG)
-- ==============================================================================
-- 3. NẠP DỮ LIỆU TRI THỨC SGK TIN HỌC 12 VÀO KNOWLEDGE_CHUNKS

-- 3.1 CHUYÊN ĐỀ 12B: MẠNG MÁY TÍNH VÀ INTERNET
INSERT INTO public.knowledge_chunks (topic_id, book_source, chapter, page_number, chunk_title, content)
VALUES
(
    '12B',
    'SGK Tin học 12 - Kết Nối Tri Thức',
    'Chủ đề B: Mạng máy tính và Internet',
    12,
    'Khái niệm Địa chỉ IP và Phân biệt IPv4 với IPv6',
    'Địa chỉ IP (Internet Protocol address) là định danh duy nhất cho mỗi thiết bị khi tham gia vào mạng máy tính nhằm xác định vị trí và định tuyến gói tin.
- IPv4 (Internet Protocol version 4): Có độ dài 32 bit, được chia thành 4 nhóm (octet), mỗi nhóm 8 bit cách nhau bởi dấu chấm, biểu diễn dưới dạng số thập phân từ 0 đến 255 (Ví dụ: 192.168.1.1). Không gian địa chỉ IPv4 cung cấp khoảng 4.3 tỷ địa chỉ và hiện nay đã cạn kiệt.
- IPv6 (Internet Protocol version 6): Được thiết kế để thay thế IPv4 với độ dài 128 bit, được viết dưới dạng 8 nhóm số hexa (thập lục phân), phân tách bằng dấu hai chấm (Ví dụ: 2001:0db8:85a3:0000:0000:8a2e:0370:7334). IPv6 cung cấp không gian địa chỉ khổng lồ lên tới 2^128 địa chỉ, hỗ trợ bảo mật IPsec tích hợp sẵn và cấu hình tự động.'
),
(
    '12B',
    'SGK Tin học 12 - Kết Nối Tri Thức',
    'Chủ đề B: Mạng máy tính và Internet',
    18,
    'Thiết bị mạng: Phân biệt Switch (Bộ chuyển mạch) và Router (Bộ định tuyến)',
    'Trong kiến trúc mạng LAN và WAN:
- Switch (Bộ chuyển mạch): Hoạt động chủ yếu ở tầng Liên kết dữ liệu (Data Link Layer - Tầng 2 của mô hình OSI). Switch sử dụng bảng địa chỉ MAC (MAC Address Table) để chuyển tiếp khung dữ liệu (frame) chính xác đến cổng của thiết bị đích trong cùng một mạng nội bộ (LAN), giúp hạn chế xung đột tín hiệu và tối ưu băng thông.
- Router (Bộ định tuyến): Hoạt động ở tầng Mạng (Network Layer - Tầng 3 của mô hình OSI). Router chịu trách nhiệm kết nối hai hoặc nhiều mạng khác nhau (ví dụ kết nối mạng LAN gia đình với mạng diện rộng Internet của nhà mạng ISP). Router sử dụng bảng định tuyến (Routing Table) và địa chỉ IP để tìm đường đi ngắn nhất, tối ưu nhất cho gói tin (packet) di chuyển giữa các mạng.'
),
(
    '12B',
    'SGK Tin học 12 - Cánh Diều',
    'Chủ đề B: Mạng máy tính và Internet',
    25,
    'Giao thức mạng TCP/IP, DNS và DHCP',
    'Các giao thức mạng then chốt trong bộ giao thức TCP/IP:
- TCP (Transmission Control Protocol): Giao thức tin cậy hướng kết nối, thực hiện bắt tay 3 bước (three-way handshake), kiểm soát luồng, phát hiện lỗi và truyền lại gói tin bị mất, đảm bảo dữ liệu nhận được đầy đủ và đúng thứ tự.
- UDP (User Datagram Protocol): Giao thức không hướng kết nối, không đảm bảo truyền tin cậy nhưng tốc độ nhanh, phù hợp truyền video trực tiếp, gọi thoại VoIP, livestream.
- DNS (Domain Name System): Hệ thống phân giải tên miền giúp chuyển đổi tên miền dễ nhớ (ví dụ: google.com, tinpath.edu.vn) thành địa chỉ IP số mà máy tính hiểu được.
- DHCP (Dynamic Host Configuration Protocol): Giao thức cấp phát địa chỉ IP động tự động cho các thiết bị khi vừa kết nối vào mạng.'
);

-- 3.2 CHUYÊN ĐỀ 11F: CƠ SỞ DỮ LIỆU QUAN HỆ VÀ TRUY VẤN SQL
INSERT INTO public.knowledge_chunks (topic_id, book_source, chapter, page_number, chunk_title, content)
VALUES
(
    '11F',
    'SGK Tin học 11 - Kết Nối Tri Thức',
    'Chủ đề F: Cơ sở dữ liệu và Hệ quản trị CSDL',
    42,
    'Mô hình CSDL quan hệ: Khóa chính (Primary Key) và Khóa ngoại (Foreign Key)',
    'Trong hệ quản trị cơ sở dữ liệu quan hệ (RDBMS):
- Bảng (Relation / Table): Gồm các cột (Thuộc tính / Fields) và các hàng (Bản ghi / Tuples / Records).
- Khóa chính (Primary Key - PK): Là một hoặc một tập hợp các thuộc tính dùng để xác định duy nhất mỗi bản ghi trong bảng. Giá trị của khóa chính KHÔNG ĐƯỢC phép trùng lặp và KHÔNG ĐƯỢC chứa giá trị rỗng (NOT NULL).
- Khóa ngoại (Foreign Key - FK): Là thuộc tính trong một bảng liên kết đến khóa chính của bảng khác nhằm thiết lập mối quan hệ giữa hai bảng. Khóa ngoại đảm bảo Ràng buộc toàn vẹn tham chiếu (Referential Integrity): giá trị khóa ngoại phải tồn tại ở bảng cha hoặc mang giá trị NULL.'
),
(
    '11F',
    'SGK Tin học 11 - Kết Nối Tri Thức',
    'Chủ đề F: Cơ sở dữ liệu và Hệ quản trị CSDL',
    56,
    'Các câu lệnh truy vấn SQL căn bản: SELECT, WHERE, ORDER BY, GROUP BY, HAVING',
    'Cú pháp chuẩn truy vấn dữ liệu SQL:
1. SELECT column1, column2 FROM table_name: Chọn các cột dữ liệu cần lấy.
2. WHERE condition: Lọc các bản ghi thỏa mãn điều kiện trước khi gom nhóm (ví dụ: WHERE diem_thi >= 8.0).
3. GROUP BY column: Gom nhóm các dòng có cùng giá trị để tính toán tổng hợp (COUNT, SUM, AVG, MAX, MIN).
4. HAVING condition: Lọc điều kiện trên nhóm ĐÃ ĐƯỢC GOM NHÓM bởi GROUP BY (ví dụ: HAVING COUNT(*) > 5). Phân biệt: WHERE lọc từng dòng bản ghi, HAVING lọc nhóm.
5. ORDER BY column [ASC|DESC]: Sắp xếp kết quả tăng dần (ASC mặc định) hoặc giảm dần (DESC).
Thứ tự thực thi câu lệnh SQL: FROM -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY.'
),
(
    '11F',
    'SGK Tin học 11 - Cánh Diều',
    'Chủ đề F: Cơ sở dữ liệu và Hệ quản trị CSDL',
    68,
    'Các phép kết nối bảng trong SQL: INNER JOIN, LEFT JOIN, RIGHT JOIN',
    'Khi cần lấy thông tin từ nhiều bảng có quan hệ với nhau:
- INNER JOIN: Trả về các dòng khi có sự khớp dữ liệu giữa khóa ở cả hai bảng A và B. Nếu dòng không có cặp tương ứng sẽ bị loại bỏ.
- LEFT JOIN (LEFT OUTER JOIN): Trả về TẤT CẢ các dòng từ bảng bên trái (bảng A), và các dòng khớp từ bảng bên phải (bảng B). Nếu không có bản ghi khớp ở bảng B, các cột của bảng B sẽ nhận giá trị NULL.
- RIGHT JOIN: Trả về tất cả các dòng từ bảng bên phải và các dòng khớp từ bảng bên trái.
Ví dụ: SELECT h.ho_ten, l.ten_lop FROM hoc_sinh h INNER JOIN lop_hoc l ON h.ma_lop = l.ma_lop;'
);

-- 3.3 CHUYÊN ĐỀ 12A: TRÍ TUỆ NHÂN TẠO (AI) VÀ HỌC MÁY
INSERT INTO public.knowledge_chunks (topic_id, book_source, chapter, page_number, chunk_title, content)
VALUES
(
    '12A',
    'SGK Tin học 12 - Kết Nối Tri Thức',
    'Chủ đề A: Giới thiệu Trí tuệ nhân tạo',
    85,
    'Khái niệm Trí tuệ nhân tạo (AI) và các lĩnh vực nghiên cứu chính',
    'Trí tuệ nhân tạo (Artificial Intelligence - AI) là ngành khoa học và công nghệ nghiên cứu, xây dựng các hệ thống tính toán có khả năng thực hiện các tác vụ đòi hỏi trí thông minh của con người như: nhận thức thị giác, nhận dạng tiếng nói, hiểu ngôn ngữ tự nhiên, học hỏi từ dữ liệu và ra quyết định.
Các lĩnh vực tiêu biểu của AI:
- Học máy (Machine Learning) và Học sâu (Deep Learning).
- Thị giác máy tính (Computer Vision): Nhận dạng khuôn mặt, xe tự hành, phân tích ảnh y tế.
- Xử lý ngôn ngữ tự nhiên (NLP - Natural Language Processing): Dịch tự động, chatbot, mô hình ngôn ngữ lớn (LLM).
- Robot thông minh (Robotics) và Hệ chuyên gia (Expert Systems).'
),
(
    '12A',
    'SGK Tin học 12 - Cánh Diều',
    'Chủ đề A: Giới thiệu Trí tuệ nhân tạo',
    96,
    'Phân biệt Học có giám sát (Supervised Learning) và Học không giám sát (Unsupervised Learning)',
    'Trong Học máy (Machine Learning):
- Học có giám sát (Supervised Learning): Mô hình được huấn luyện trên tập dữ liệu ĐÃ ĐƯỢC GÁN NHÃN (Labeled Data), tức là mỗi dữ liệu đầu vào (X) đi kèm nhãn kết quả mong muốn (Y). Các bài toán phổ biến:
  + Phân loại (Classification): Dự đoán nhãn rời rạc (Ví dụ: Email là Spam hay Not Spam, chẩn đoán bệnh Đúng hay Sai).
  + Hồi quy (Regression): Dự đoán giá trị liên tục (Ví dụ: Dự đoán giá nhà, dự đoán điểm thi THPT).
- Học không giám sát (Unsupervised Learning): Dữ liệu huấn luyện CHƯA ĐƯỢC GÁN NHÃN (Unlabeled Data). Mô hình phải tự phát hiện các quy luật, cấu trúc ẩn bên trong dữ liệu. Các bài toán phổ biến:
  + Phân cụm (Clustering): Gom các khách hàng hoặc tài liệu có đặc điểm tương tự thành các cụm (Ví dụ thuật toán K-Means).
  + Giảm chiều dữ liệu (Dimensionality Reduction).'
),
(
    '12D',
    'SGK Tin học 12 - Kết Nối Tri Thức',
    'Chủ đề D: Đạo đức, pháp luật và văn hóa trong môi trường số',
    108,
    'Đạo đức AI, Quyền riêng tư và Luật An ninh mạng',
    'Khi phát triển và ứng dụng AI trong đời sống:
- Tính thiên vị và công bằng (Bias & Fairness): Dữ liệu thu thập không công bằng có thể khiến AI đưa ra kết luận phân biệt đối xử về giới tính, độ tuổi, vùng miền.
- Quyền riêng tư và bảo vệ dữ liệu cá nhân (Data Privacy): Thu thập dữ liệu người dùng phải được sự đồng ý, tuân thủ Luật An toàn thông tin mạng và Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân.
- Trách nhiệm giải trình và tính minh bạch (Explainability): Hệ thống AI cần có khả năng giải thích nguyên do đưa ra quyết định, đặc biệt trong y tế, pháp lý và tài chính.'
);

-- 3.4 CHUYÊN ĐỀ 11F_CS: THUẬT TOÁN VÀ LẬP TRÌNH NÂNG CAO
INSERT INTO public.knowledge_chunks (topic_id, book_source, chapter, page_number, chunk_title, content)
VALUES
(
    '11F_CS',
    'SGK Tin học 11 - Kết Nối Tri Thức',
    'Chuyên đề CS: Thuật toán và Lập trình nâng cao',
    120,
    'Thuật toán Đệ quy (Recursion) và Điều kiện dừng (Base Case)',
    'Đệ quy là phương pháp lập trình trong đó một hàm tự gọi lại chính nó với kích thước bài toán nhỏ hơn.
Mọi hàm đệ quy chuẩn mực phải có 2 thành phần cốt lõi:
1. Trường hợp cơ sở / Điều kiện dừng (Base Case): Trường hợp bài toán đơn giản nhất có thể trả về kết quả ngay lập tức mà không cần gọi đệ quy tiếp. Nếu thiếu điều kiện dừng, chương trình sẽ rơi vào vòng lặp vô hạn và gây lỗi tràn ngăn xếp (Stack Overflow).
2. Bước đệ quy (Recursive Step): Lời gọi chính hàm đó nhưng với tham số nhỏ dần dần hướng tới điều kiện dừng.
Ví dụ: Tính giai thừa n!
def factorial(n):
    if n <= 1:
        return 1 # Base case
    return n * factorial(n - 1) # Recursive step'
),
(
    '11F_CS',
    'SGK Tin học 11 - Cánh Diều',
    'Chuyên đề CS: Thuật toán và Lập trình nâng cao',
    134,
    'Thuật toán Tìm kiếm nhị phân (Binary Search) và Độ phức tạp thuật toán O(log n)',
    'Thuật toán tìm kiếm nhị phân áp dụng trên mảng ĐÃ ĐƯỢC SẮP XẾP.
Nguyên lý: Tại mỗi bước so sánh phần tử cần tìm với phần tử ở vị trí giữa mảng (mid).
- Nếu giá trị cần tìm bằng mid: Tìm thấy.
- Nếu giá trị cần tìm nhỏ hơn mid: Thu hẹp phạm vi tìm kiếm sang nửa bên trái (right = mid - 1).
- Nếu lớn hơn mid: Thu hẹp phạm vi sang nửa bên phải (left = mid + 1).
Độ phức tạp thời gian:
- Tìm kiếm tuần tự (Linear Search): O(n) - phải duyệt qua từng phần tử.
- Tìm kiếm nhị phân (Binary Search): O(log n) - mỗi lần so sánh loại bỏ được một nửa số lượng phần tử, tối ưu vượt trội cho dữ liệu lớn.'
);

-- 3.5 CHUYÊN ĐỀ 12G: ĐỊNH HƯỚNG NGHỀ NGHIỆP CNTT & THÔNG TIN TUYỂN SINH
INSERT INTO public.knowledge_chunks (topic_id, book_source, chapter, page_number, chunk_title, content)
VALUES
(
